import sys

TIMESTAMP_FORMAT = "%Y-%m-%dT%H:%M:%S"
STATUS_CLASSES = {"2": "ok", "3": "redirect", "4": "client_error", "5": "server_error"}


def extract_timestamp(raw, failures):
    import datetime
    try:
        return datetime.datetime.strptime(raw.strip(), TIMESTAMP_FORMAT)
    except ValueError as err:
        failures.append(str(err))
    except TypeError as err:
        failures.append(str(err))
    return None


def parse_payload(raw, failures):
    try:
        parts = raw.split()
        return (parts[0].upper(), parts[1])
    except IndexError as err:
        failures.append(str(err))
    except AttributeError as err:
        failures.append(str(err))
    return None


def evaluate_metrics(raw, failures):
    try:
        size_text, duration_text = raw.split("/")
        size = float(int(size_text))
        duration = float(duration_text)
        return (int(size), round(size / duration, 2))
    except ZeroDivisionError as err:
        failures.append(str(err))
    except ValueError as err:
        failures.append(str(err))
    return None


def analyze(logs):
    events = []
    failures = []
    for line in logs:
        try:
            record = {}
            for chunk in line.split("|"):
                key, value = chunk.split("=", 1)
                record[key.strip()] = value
            status_class = STATUS_CLASSES[record["status"].strip()[:1]]
            stamp = extract_timestamp(record["ts"], failures)
            payload = parse_payload(record.get("payload"), failures)
            metrics = evaluate_metrics(record["metrics"], failures)
            if stamp is None or payload is None or metrics is None:
                continue
            events.append((stamp.isoformat(), payload[0], payload[1], status_class,
                           metrics[0], metrics[1]))
        except KeyError as err:
            failures.append(str(err))
        except Exception as err:
            failures.append(str(err))
    return (events, failures)


def format_report(events, failures):
    lines = []
    for event in events:
        lines.append("%s %s %s -> %s (%d bytes, %.2f B/s)" % event)
    try:
        rate = 100.0 * len(events) / (len(events) + len(failures))
        lines.append("parsed %d of %d lines (%.1f%%)" % (
            len(events), len(events) + len(failures), rate))
    except ZeroDivisionError as err:
        lines.append("no log lines to report: %s" % err)
    for reason in failures:
        lines.append("failure: %s" % reason)
    return "\n".join(lines)


def main():
    logs = [line for line in sys.stdin.read().splitlines() if line.strip()]
    events, failures = analyze(logs)
    print(format_report(events, failures))


if __name__ == "__main__":
    main()

