import json
import sys


def _require_non_negative(label, value):
    if value < 0:
        raise ValueError("%s must not be negative: %r" % (label, value))
    return value


def parse_temperature(reading):
    raw = reading.get("temp_c")
    try:
        return float(raw), None
    except ValueError as err:
        return None, str(err)
    except TypeError as err:
        return None, str(err)


def parse_humidity(reading):
    samples = reading.get("humidity_samples", [])
    try:
        latest = _require_non_negative("humidity", float(samples[-1]))
    except IndexError as err:
        return None, str(err)
    except ValueError as err:
        return None, str(err)
    return latest, None


def parse_location(reading):
    try:
        return reading["site"]["name"].strip().upper(), None
    except KeyError as err:
        return None, "missing key %s" % err
    except AttributeError as err:
        return None, str(err)


def aggregate(telemetry):
    readings = []
    errors = []
    try:
        records = list(enumerate(telemetry))
    except TypeError as err:
        return readings, [str(err)]
    for index, record in records:
        try:
            temperature, temp_error = parse_temperature(record)
            humidity, humidity_error = parse_humidity(record)
            location, location_error = parse_location(record)
            problems = [m for m in (temp_error, humidity_error, location_error) if m]
            if problems:
                errors.append("record %d: %s" % (index, "; ".join(problems)))
            else:
                readings.append((location, temperature, humidity))
        except Exception as err:
            errors.append("record %d: %s" % (index, err))
    return readings, errors


def format_report(readings, errors):
    lines = []
    for location, temperature, humidity in readings:
        lines.append("%-10s %6.2f C %6.2f %%" % (location, temperature, humidity))
    try:
        average = sum(item[1] for item in readings) / float(len(readings))
        lines.append("mean temperature: %.2f C" % average)
    except ZeroDivisionError as err:
        lines.append("mean temperature unavailable (%s)" % err)
    for message in errors:
        lines.append("ERROR " + message)
    return "\n".join(lines)


def load_telemetry(path):
    handle = open(path)
    try:
        payload = handle.read()
    finally:
        handle.close()
    try:
        return json.loads(payload)
    except ValueError as err:
        sys.stderr.write("cannot parse %s: %s\n" % (path, err))
        return []


def main(argv):
    if len(argv) > 1:
        telemetry = load_telemetry(argv[1])
    else:
        telemetry = [
            {"site": {"name": " north "}, "temp_c": "21.5", "humidity_samples": [40, 41]},
            {"site": {"name": "south"}, "temp_c": None, "humidity_samples": [55]},
            {"site": {"name": "east"}, "temp_c": "n/a", "humidity_samples": []},
            {"site": {"name": 12}, "temp_c": 18, "humidity_samples": [-3]},
            {"temp_c": 19.5, "humidity_samples": [33]},
            "sensor offline",
        ]
    readings, errors = aggregate(telemetry)
    print(format_report(readings, errors))
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

