from datetime import datetime

DATE_FORMATS = ("%Y-%m-%d", "%d/%m/%Y")


def parse_identification(record):
    """Return (id_number, error_text); error_text is None on success."""
    raw = record.get("id")
    try:
        return int(raw), None
    except ValueError as err:
        return None, "bad id value: %s" % err
    except TypeError as err:
        return None, "bad id type: %s" % err


def salary_tier(record):
    """Return (tier_name, full_time_salary, error_text)."""
    try:
        amount = float(record["amount"])
    except KeyError as err:
        return None, None, "missing salary key: %s" % err
    except ValueError as err:
        return None, None, "unreadable salary: %s" % err
    ratio = float(record.get("ratio", 1.0))
    try:
        full_time = amount / ratio
    except ZeroDivisionError as err:
        return None, None, "part time ratio invalid: %s" % err
    if full_time >= 120000:
        tier = "senior"
    elif full_time >= 60000:
        tier = "mid"
    else:
        tier = "junior"
    return tier, full_time, None


def hire_date(record):
    """Return (iso_date_string, error_text)."""
    raw = record.get("hired")
    try:
        cleaned = raw.strip()
    except AttributeError as err:
        return None, "hire date not text: %s" % err
    last_error = None
    for pattern in DATE_FORMATS:
        try:
            return datetime.strptime(cleaned, pattern).strftime("%Y-%m-%d"), None
        except ValueError as err:
            last_error = "hire date format: %s" % err
    return None, last_error


def process(employees):
    parsed = []
    errors = []
    for position, record in enumerate(employees):
        try:
            pieces = record["name"].split(",")
            last = pieces[0].strip()
            first = pieces[1].strip()
        except IndexError as err:
            errors.append("row %d: name needs 'last, first' (%s)" % (position, err))
            continue
        except Exception as err:
            errors.append("row %d: %s" % (position, err))
            continue
        ident, id_error = parse_identification(record)
        tier, full_time, pay_error = salary_tier(record)
        hired, date_error = hire_date(record)
        row_errors = [text for text in (id_error, pay_error, date_error) if text]
        if row_errors:
            for text in row_errors:
                errors.append("row %d: %s" % (position, text))
            continue
        parsed.append((ident, "%s %s" % (first, last), tier, round(full_time, 2), hired))
    return parsed, errors


def main():
    raw_rows = [
        {"id": "17", "name": "Vance, Rita", "amount": 130000, "hired": "2015-04-02"},
        {"id": "18", "name": "Okoro, Sam", "amount": 45000, "ratio": 0.5, "hired": "03/11/2019"},
        {"id": "abc", "name": "Lund, Ove", "amount": 70000, "hired": "2020-01-01"},
        {"id": "20", "name": "Solo", "amount": 70000, "hired": "2020-01-01"},
        {"id": "21", "name": "Diaz, Ana", "hired": "2021-06-06"},
        {"id": "22", "name": "Blum, Kai", "amount": 50000, "ratio": 0, "hired": "2018-02-02"},
        {"id": None, "name": "Ito, Ken", "amount": 61000, "hired": 20180202},
    ]
    rows, problems = process(raw_rows)
    for row in rows:
        print("%-4s %-12s %-7s %10.2f %s" % row)
    for message in problems:
        print("ERROR " + message)


if __name__ == "__main__":
    main()

