class Batch(object):
    def __init__(self, units):
        self.units = units

    def available(self):
        return self.units


STOCK_ROWS = [("widget", "12"), ("gizmo", "0"), ("bolt", "seven"), ("bolt", "4")]
LEGACY_STOCK = {"nut": [7]}


def build_stock(rows, legacy):
    stock = {}
    for name in legacy:
        stock[name] = list(legacy[name])
    for name, units in rows:
        try:
            count = int(units)
        except ValueError as err:
            print("skipping stock row %s: %s" % (name, err))
            continue
        stock.setdefault(name, [])
        if count > 0:
            stock[name].append(Batch(count))
    return stock


def shipping_address(order):
    try:
        parts = [order["street"], order["city"], order["zip"]]
        return ", ".join(parts)
    except KeyError as err:
        return "missing shipping field %s" % err
    except TypeError as err:
        return "bad shipping field: %s" % err


def parse_money(text):
    value = float(text)
    if value < 0:
        raise ValueError("negative amount %s" % text)
    return value


def discount_total(order):
    try:
        price = parse_money(order["price"])
        qty = int(order["qty"])
        total = price * qty
        if qty >= 10:
            total = total * 0.9
        return total, total / qty
    except ZeroDivisionError as err:
        return None, "order has no items: %s" % err
    except ValueError as err:
        return None, "bad price or quantity: %s" % err


def verify_inventory(name, needed, stock):
    try:
        batches = stock.get(name, [])
        first = batches[0]
        on_hand = sum([b.available() for b in batches])
        if on_hand < needed:
            return "only %d %s left (first batch %d)" % (on_hand, name, first.available())
        return None
    except IndexError as err:
        return "%s is out of stock: %s" % (name, err)
    except AttributeError as err:
        return "corrupt batch record for %s: %s" % (name, err)


def fulfill(orders):
    stock = build_stock(STOCK_ROWS, LEGACY_STOCK)
    filled = []
    rejected = []
    try:
        pending = list(orders)
    except TypeError as err:
        return [], ["cannot iterate orders: %s" % err]
    for order in pending:
        try:
            address = shipping_address(order)
            if address.startswith("missing") or address.startswith("bad"):
                rejected.append(address)
                continue
            total, per_unit = discount_total(order)
            if total is None:
                rejected.append(per_unit)
                continue
            problem = verify_inventory(order["item"], int(order["qty"]), stock)
            if problem is not None:
                rejected.append(problem)
                continue
            filled.append((order["item"], int(order["qty"]), round(total, 2),
                           address, round(per_unit, 2)))
        except Exception as err:
            rejected.append("order dropped: %s" % err)
    return filled, rejected


def main():
    orders = [
        {"item": "widget", "qty": "10", "price": "3.50",
         "street": "1 Main St", "city": "Ames", "zip": "50010"},
        {"item": "bolt", "qty": "2", "price": "-1.00",
         "street": "9 Oak Ave", "city": "Ames", "zip": "50010"},
        {"item": "gizmo", "qty": "1", "price": "20.00",
         "street": "5 Elm St", "city": "Ames", "zip": "50011"},
        {"item": "nut", "qty": "3", "price": "0.25",
         "street": "7 Pine St", "city": "Ames", "zip": "50012"},
        {"item": "widget", "qty": "1", "price": "3.50",
         "street": None, "city": "Ames", "zip": "50010"},
        {"item": "bolt", "qty": "0", "price": "1.00",
         "street": "3 Ash St", "city": "Ames", "zip": "50013"},
        {"item": "widget", "qty": "1", "price": "3.50", "city": "Ames"},
    ]
    filled, rejected = fulfill(orders)
    for row in filled:
        print("SHIP %s x%d for $%.2f to %s (unit $%.2f)" % row)
    for reason in rejected:
        print("REJECT " + reason)


if __name__ == "__main__":
    main()

