MINIMUM_CREDITS = 12
TEXT = type('')


def parse_course_code(code):
    """Split a course code like 'MAT-101' into (department, number)."""
    try:
        dept, number = code.split('-')
    except ValueError as err:
        return str(err)
    try:
        digits = (number[0], number[1], number[2])
    except IndexError as err:
        return str(err)
    try:
        numeric = int(''.join(digits))
    except ValueError as err:
        return str(err)
    return (dept.upper(), numeric)


def grade_point_average(grades, credits):
    """Weighted average of numeric grade points; returns error text on failure."""
    points = 0.0
    earned = 0
    try:
        for code in grades:
            points += grades[code] * credits[code]
            earned += credits[code]
    except TypeError as err:
        return str(err)
    try:
        return round(points / earned, 3)
    except ZeroDivisionError as err:
        return str(err)


def _credit_units(value):
    if value < 0:
        raise ValueError("credit value %s is negative" % value)
    return value


def validate_credits(credits, minimum):
    """Sum a mapping of course -> credits and check it against a minimum."""
    try:
        items = list(credits.items())
    except AttributeError as err:
        return str(err)
    total = 0
    for code, value in items:
        try:
            total += _credit_units(value)
        except ValueError as err:
            return "%s: %s" % (code, str(err))
    if total < minimum:
        return "total credits %d below minimum %d" % (total, minimum)
    return total


def evaluate(transcripts):
    valid = []
    failures = []
    for record in transcripts:
        name = "<unknown>"
        try:
            name = record['student']
            grades = record['grades']
            credits = record['credits']
        except KeyError as err:
            failures.append("record for %s missing field %s" % (name, err))
            continue
        try:
            broken = False
            for code in sorted(grades):
                parsed = parse_course_code(code)
                if isinstance(parsed, TEXT):
                    failures.append("%s: bad course code %r (%s)" % (name, code, parsed))
                    broken = True
            if broken:
                continue
            total = validate_credits(credits, MINIMUM_CREDITS)
            if isinstance(total, TEXT):
                failures.append("%s: %s" % (name, total))
                continue
            gpa = grade_point_average(grades, credits)
            if isinstance(gpa, TEXT):
                failures.append("%s: %s" % (name, gpa))
                continue
            valid.append((name, total, gpa))
        except Exception as err:
            failures.append("%s: %s" % (name, err))
    return valid, failures


def format_report(valid, failures):
    lines = ["PASSED (%d)" % len(valid)]
    for name, credits, gpa in valid:
        lines.append("  %-10s credits=%2d gpa=%.3f" % (name, credits, gpa))
    lines.append("FAILED (%d)" % len(failures))
    for message in failures:
        lines.append("  " + message)
    return "\n".join(lines)


def main():
    transcripts = [
        {'student': 'Ada', 'grades': {'MAT-101': 4.0, 'PHY-210': 3.5},
         'credits': {'MAT-101': 8, 'PHY-210': 4}},
        {'student': 'Bob', 'grades': {'HIS-11': 3.0}, 'credits': {'HIS-11': 12}},
        {'student': 'Cleo', 'grades': {'ENG-100': 'A'}, 'credits': {'ENG-100': 14}},
        {'student': 'Dan', 'grades': {'BIO-150': 2.0}, 'credits': {'BIO-150': -3}},
        {'student': 'Eve', 'grades': {'CHE-120': 3.0}, 'credits': [('CHE-120', 12)]},
        {'student': 'Fay', 'grades': {}, 'credits': {}},
        {'grades': {'ART-101': 3.0}, 'credits': {'ART-101': 12}},
        {'student': 'Gus', 'grades': None, 'credits': {'MUS-101': 12}},
    ]
    valid, failures = evaluate(transcripts)
    print(format_report(valid, failures))


if __name__ == '__main__':
    main()

