import sys


def parse_source(tokens):
    try:
        raw = tokens[0]
    except IndexError as err:
        return None, "source: %s" % err
    try:
        return int(raw), None
    except ValueError as err:
        return None, "source: %s" % err


def parse_dest(tokens, registry):
    try:
        raw = tokens[1]
    except IndexError as err:
        return None, "dest: %s" % err
    try:
        return registry[raw], None
    except KeyError as err:
        return None, "dest: unknown node %s" % err
    except TypeError as err:
        return None, "dest: %s" % err


def parse_fields(parts):
    fields = {}
    for part in parts:
        try:
            key, value = part.split('=', 1)
        except ValueError as err:
            return None, "field %s: %s" % (part, err)
        fields[key.strip().lower()] = value
    return fields, None


def parse_weight(fields):
    try:
        raw = fields.get('w').strip().replace(',', '.')
    except AttributeError as err:
        return None, "weight: %s" % err
    try:
        return float(raw), None
    except ValueError as err:
        return None, "weight: %s" % err


def parse_header(line, state):
    try:
        key, value = line[1:].split(':', 1)
    except ValueError as err:
        return "header: %s" % err
    key = key.strip().lower()
    value = value.strip()
    if key == 'nodes':
        names = [n.strip() for n in value.split(',') if n.strip()]
        state['registry'] = dict((name, i) for i, name in enumerate(names))
        return None
    if key == 'scale':
        try:
            state['scale'] = float(value)
        except ValueError as err:
            return "header: %s" % err
        return None
    return "header: unknown key %s" % key


def build(edges):
    state = {'registry': None, 'scale': 1.0}
    graph = []
    errors = []
    for index, raw in enumerate(edges):
        lineno = index + 1
        line = raw.strip()
        if not line:
            continue
        if line.startswith('#'):
            problem = parse_header(line, state)
            if problem:
                errors.append("line %d: %s" % (lineno, problem))
            continue
        try:
            tokens = line.replace('->', ' ').split()
            src, src_err = parse_source(tokens)
            dst, dst_err = parse_dest(tokens, state['registry'])
            fields, field_err = parse_fields(tokens[2:])
            found = [e for e in (src_err, dst_err, field_err) if e]
            if found:
                for problem in found:
                    errors.append("line %d: %s" % (lineno, problem))
                continue
            weight, weight_err = parse_weight(fields)
            if weight_err:
                errors.append("line %d: %s" % (lineno, weight_err))
                continue
            graph.append((src, dst, round(weight / state['scale'], 4)))
        except ZeroDivisionError as err:
            errors.append("line %d: scale: %s" % (lineno, err))
        except Exception as err:
            errors.append("line %d: unexpected: %s" % (lineno, err))
    return graph, errors


def format_report(graph, errors):
    lines = ["edges: %d" % len(graph)]
    for edge in graph:
        lines.append("  %d -> %d (%.4f)" % edge)
    lines.append("errors: %d" % len(errors))
    for problem in errors:
        lines.append("  " + problem)
    return "\n".join(lines)


def main():
    graph, errors = build(sys.stdin.read().splitlines())
    print(format_report(graph, errors))
    return 1 if errors else 0


if __name__ == '__main__':
    sys.exit(main())

