import re


def extract_name(segments):
    try:
        text = ":".join(segments)
        pieces = [piece.strip() for piece in re.split(r"[:|]", text) if piece.strip()]
        return pieces[0], None
    except IndexError as err:
        return None, "no exercise name (%s)" % err
    except TypeError as err:
        return None, "unusable name fields (%s)" % err


def count_sets(spec):
    try:
        total_sets = 0
        total_reps = 0
        for term in spec.split("+"):
            count_text, reps_text = term.strip().split("x")
            count = int(count_text)
            reps = int(reps_text)
            total_sets += count
            total_reps += count * reps
        average = float(total_reps) / total_sets
        return (total_sets, average), None
    except ValueError as err:
        return None, "bad set spec %r (%s)" % (spec, err)
    except ZeroDivisionError as err:
        return None, "cannot average reps of %r (%s)" % (spec, err)


def extract_weight(fields):
    try:
        raw = fields["weight"]
        return float(raw.replace("lb", "").replace("kg", "").strip()), None
    except ValueError as err:
        return None, "bad weight value (%s)" % err
    except KeyError as err:
        return None, "missing weight field (%s)" % err


def parse(workouts):
    results = []
    errors = []
    for index, entry in enumerate(workouts):
        try:
            if hasattr(entry, "get"):
                segments = [entry.get("exercise"), entry.get("sets"),
                            "weight=%s" % entry.get("weight")]
            else:
                segments = entry.split("|")
            name, name_err = extract_name(segments)
            if name_err:
                errors.append("entry %d: %s" % (index + 1, name_err))
                continue
            sets_info, sets_err = count_sets(segments[1])
            if sets_err:
                errors.append("entry %d: %s" % (index + 1, sets_err))
                continue
            fields = {}
            for chunk in segments[2].split(";"):
                pair = chunk.split("=", 1)
                if len(pair) == 2:
                    fields[pair[0].strip().lower()] = pair[1].strip()
            weight, weight_err = extract_weight(fields)
            if weight_err:
                errors.append("entry %d: %s" % (index + 1, weight_err))
                continue
            results.append((name, sets_info[0], sets_info[1], weight))
        except AttributeError as err:
            errors.append("entry %d: not a log line (%s)" % (index + 1, err))
        except Exception as err:
            errors.append("entry %d: unexpected problem (%s)" % (index + 1, err))
    return results, errors


def main():
    logs = [
        "Bench Press | 3x10+2x8 | weight=135lb",
        "Squat | 5x5 | weight=225 lb",
        "",
        {"exercise": "Deadlift", "sets": "1x5", "weight": "315lb"},
        {"sets": "3x12", "weight": "40kg"},
        None,
        "Curl | 0x12 | weight=30lb",
        "Row | 3xten | weight=95lb",
        "Press | 3x8 | rpe=7",
        42,
    ]
    records, problems = parse(logs)
    print("parsed %d records" % len(records))
    for record in records:
        print("%-12s sets=%d avg_reps=%.1f weight=%.1f" % record)
    print("found %d errors" % len(problems))
    for message in problems:
        print(message)


if __name__ == "__main__":
    main()

