        return None, "publication year unreadable: %s" % err
    if year < 1450 or year > 2100:
        return None, "publication year %d out of range" % year
    return year, None


def parse_authors(field, registry):
    try:
        parts = field.split(";")
    except AttributeError as err:
        return None, "author list is not text: %s" % err
    names = []
    for part in parts:
        key = part.strip().lower()
