    try:
        mean = sum([row[3] for row in rows]) // len(rows)
        head = "%d titles catalogued, mean year %d" % (len(rows), mean)
    except ZeroDivisionError as err:
        head = "no titles catalogued (%s)" % err
    return "%s, %d rejected" % (head, len(errors))


