import sys
import datetime

TIME_FORMAT = "%H:%M"

RAW_SCHEDULE = [
    "AB123 | 08:30 | 10:45",
    "QQ7 | 23:10 | 01:05",
    "X9 | 06:00 | 07:30",
    "LH99X | 09:15 | 11:00",
    "BA404 | 25:61 | 12:00",
    "AF200 | 14:20",
]


def parse_flight_number(code):
    try:
        text = code.strip().upper()
        carrier = text[0] + text[1]
        digits = int(text[2:])
        return "%s%03d" % (carrier, digits), None
    except ValueError as err:
        return None, str(err)
    except IndexError as err:
        return None, str(err)


def parse_departure(value):
    try:
        moment = datetime.datetime.strptime(value, TIME_FORMAT)
        return moment.time(), None
    except ValueError as err:
        return None, str(err)
    except TypeError as err:
        return None, str(err)


def parse_arrival(value):
    try:
        moment = datetime.datetime.strptime(value.strip(), TIME_FORMAT)
        return moment.time(), None
    except ValueError as err:
        return None, str(err)
    except AttributeError as err:
        return None, str(err)


def build_flights(lines):
    flights = []
    problems = []
    for line in lines:
        try:
            code, departure, arrival = line.split("|")
        except ValueError as err:
            problems.append("record '%s': %s" % (line, err))
            continue
        flights.append({"code": code, "departure": departure, "arrival": arrival})
    return flights, problems


def minutes_aloft(departure, arrival):
    start = departure.hour * 60 + departure.minute
    end = arrival.hour * 60 + arrival.minute
    if end < start:
        end += 24 * 60
    return end - start


def schedule(flights):
    departures = []
    logs = []
    for index, flight in enumerate(flights):
        try:
            number, failure = parse_flight_number(flight["code"])
            if failure is not None:
                logs.append("flight %d number: %s" % (index, failure))
                continue
            departure, failure = parse_departure(flight["departure"])
            if failure is not None:
                logs.append("%s departure: %s" % (number, failure))
                continue
            arrival, failure = parse_arrival(flight["arrival"])
            if failure is not None:
                logs.append("%s arrival: %s" % (number, failure))
                continue
            departures.append((number, departure.strftime(TIME_FORMAT),
                               arrival.strftime(TIME_FORMAT),
                               minutes_aloft(departure, arrival)))
        except KeyError as err:
            logs.append("flight %d missing field %s" % (index, err))
        except Exception as err:
            logs.append("flight %d rejected: %s" % (index, err))
    return departures, logs


def format_report(departures, logs, limit):
    lines = []
    for number, departure, arrival, minutes in departures:
        mark = " LONG" if minutes > limit else ""
        lines.append("%s %s -> %s (%d min)%s" % (number, departure, arrival, minutes, mark))
    for entry in logs:
        lines.append("DISCREPANCY: %s" % entry)
    return "\n".join(lines)


def main(argv):
    limit = 180
    if argv:
        try:
            limit = int(argv[0])
        except ValueError as err:
            print("keeping default limit: %s" % err)
    flights, problems = build_flights(RAW_SCHEDULE)
    departures, logs = schedule(flights)
    print(format_report(departures, problems + logs, limit))


if __name__ == "__main__":
    main(sys.argv[1:])

