import re

REGION_CODES = {'02': 'Greater Boston', '10': 'Manhattan', '94': 'Bay Area'}


def extract_price(text):
    try:
        chunk = text.split('$')[1]
    except IndexError as err:
        return None, str(err)
    digits = chunk.split()[0].replace(',', '').rstrip('.')
    try:
        return int(digits), None
    except ValueError as err:
        return None, str(err)


def parse_fields(text):
    fields = {}
    zip_match = re.search(r'(?:zip|postal code)\D{0,3}(\w+)', text, re.I)
    if zip_match is not None:
        fields['zip'] = zip_match.group(1)
    area_match = re.search(r'([\d.,]+)\s*(?:sq\s*\.?\s*ft|sqft|square feet)', text, re.I)
    if area_match is not None:
        fields['area'] = area_match.group(1)
    return fields


def extract_footage(fields, price):
    raw = fields.get('area')
    if raw is None:
        return None, None, 'square footage not stated'
    try:
        area = float(raw.replace(',', ''))
    except ValueError as err:
        return None, None, str(err)
    try:
        per_foot = price / area
    except ZeroDivisionError as err:
        return area, None, str(err)
    return area, per_foot, None


def extract_postal(fields, regions):
    code = fields.get('zip')
    try:
        length = len(code)
    except TypeError as err:
        return None, str(err)
    if length != 5 or not code.isdigit():
        return None, 'malformed postal code %r' % (code,)
    try:
        region = regions[code[:2]]
    except KeyError as err:
        return None, str(err)
    return (code, region), None


def appraise(listings):
    properties = []
    logs = []
    for index, listing in enumerate(listings):
        try:
            text = listing.strip()
        except AttributeError as err:
            logs.append('entry %d: %s' % (index, err))
            continue
        try:
            price, price_err = extract_price(text)
            if price_err is not None:
                logs.append('entry %d: %s' % (index, price_err))
                continue
            fields = parse_fields(text)
            area, per_foot, area_err = extract_footage(fields, price)
            if area_err is not None:
                logs.append('entry %d: %s' % (index, area_err))
                continue
            location, loc_err = extract_postal(fields, REGION_CODES)
            if loc_err is not None:
                logs.append('entry %d: %s' % (index, loc_err))
                continue
            properties.append((text[:26], price, area, per_foot, location[0], location[1]))
        except Exception as err:
            logs.append('entry %d: unexpected %s' % (index, err))
    return properties, logs


def format_row(prop):
    return '%-28s $%9d %8.1f sqft  $%7.2f/sqft  %s (%s)' % (
        prop[0], prop[1], prop[2], prop[3], prop[4], prop[5])


def summarize(properties):
    total = sum([prop[1] for prop in properties])
    try:
        average = total / float(len(properties))
    except ZeroDivisionError as err:
        return 'nothing appraised: %s' % (err,)
    return 'appraised %d properties, mean price $%.2f' % (len(properties), average)


def main():
    listings = [
        'Cozy condo, $650,000, 1,200 sq ft, zip 02139',
        'Loft with view $1,450,000 980 sqft postal code 10011',
        'Bungalow, $725000, 0 sqft, zip: 94110',
        'Fixer upper, 1500 square feet, zip 02139',
        'Ranch home, $abc,000, 1800 sqft, zip 94110',
        'Townhouse $499,000 1100 sq ft in Springfield',
        'Villa $2,000,000 2400 sqft zip 77002',
        None,
    ]
    properties, logs = appraise(listings)
    for prop in properties:
        print(format_row(prop))
    print(summarize(properties))
    for line in logs:
        print('LOG ' + line)


if __name__ == '__main__':
    main()

