from __future__ import division
from fractions import Fraction

UNITS = {
    "cup": "cup", "cups": "cup",
    "tbsp": "tbsp", "tablespoon": "tbsp", "tablespoons": "tbsp",
    "tsp": "tsp", "teaspoon": "tsp", "teaspoons": "tsp",
    "g": "g", "gram": "g", "grams": "g",
    "ml": "ml", "milliliter": "ml", "milliliters": "ml",
}


def parse_name(tokens):
    """Return the ingredient name (the last word of the line) and an error text."""
    try:
        return " ".join(tokens).split()[-1], None
    except IndexError as err:
        return None, str(err)
    except TypeError as err:
        return None, str(err)


def parse_quantity(tokens, portions):
    """Return the amount needed for a single portion and an error text."""
    try:
        return Fraction(tokens[0]) / portions, None
    except ValueError as err:
        return None, str(err)
    except ZeroDivisionError as err:
        return None, str(err)


def parse_unit(tokens):
    """Return the canonical unit of measurement and an error text."""
    try:
        return UNITS[tokens[1].lower()], None
    except KeyError as err:
        return None, str(err)
    except AttributeError as err:
        return None, str(err)


def format_amount(amount):
    whole = amount.numerator // amount.denominator
    rest = amount - whole
    if rest == 0:
        return str(whole)
    if whole == 0:
        return "%d/%d" % (rest.numerator, rest.denominator)
    return "%d %d/%d" % (whole, rest.numerator, rest.denominator)


def scale(recipes):
    """Scale every ingredient line; return the adjusted tuples and the errors."""
    adjusted = []
    errors = []
    for entry in recipes:
        try:
            tag = "%s (%s -> %s portions)" % entry
            raw, base, target = entry
            tokens = raw.split() if hasattr(raw, "split") else raw
            name, problem = parse_name(tokens)
            if problem is not None:
                errors.append("%s: %s" % (tag, problem))
                continue
            per_portion, problem = parse_quantity(tokens, base)
            if problem is not None:
                errors.append("%s: %s" % (tag, problem))
                continue
            unit, problem = parse_unit(tokens)
            if problem is not None:
                errors.append("%s: %s" % (tag, problem))
                continue
            adjusted.append((name, per_portion * target, unit))
        except TypeError as err:
            errors.append("bad entry %r: %s" % (entry, err))
        except Exception as err:
            errors.append("bad entry %r: %s" % (entry, err))
    return adjusted, errors


def main():
    recipes = [
