import re


def validate_email(raw):
    try:
        if len(raw) > 254:
            return None, "address longer than 254 characters"
        local, domain = raw.strip().split("@")
    except TypeError as err:
        return None, str(err)
    except ValueError as err:
        return None, str(err)
    if not local or "." not in domain:
        return None, "malformed address %r" % raw
    return (local + "@" + domain).lower(), None


def format_phone(raw):
    try:
        groups = re.findall(r"\d+", str(raw))
        area = int(groups[0])
        subscriber = int("".join(groups[1:]))
    except IndexError as err:
        return None, str(err)
    except ValueError as err:
        return None, str(err)
    digits = "%07d" % subscriber
    if area > 999 or len(digits) != 7:
        return None, "cannot format number %r" % raw
    return "(%03d) %s-%s" % (area, digits[:3], digits[3:]), None


def build_address(contact):
    try:
        street = contact["street"].strip()
        city = contact["city"].strip()
        postal = contact["postal"].strip().upper()
    except KeyError as err:
        return None, "missing field %s" % str(err)
    except AttributeError as err:
        return None, str(err)
    return "%s, %s %s" % (street, city, postal), None


def synchronize(contacts):
    valid = []
    errors = []
    for index, contact in enumerate(contacts):
        try:
            filled = len([value for value in contact.values() if value])
            score = 100.0 * filled / len(contact)
            email, email_problem = validate_email(contact.get("email"))
            phone, phone_problem = format_phone(contact.get("phone"))
            address, address_problem = build_address(contact)
            problems = [p for p in (email_problem, phone_problem, address_problem) if p]
            if problems:
                errors.append("%s: %s" % (contact["name"], "; ".join(problems)))
            else:
                valid.append((contact["name"], email, phone, address, round(score, 1)))
        except ZeroDivisionError as err:
            errors.append("contact #%d holds no fields (%s)" % (index, err))
        except Exception as err:
            errors.append("contact #%d rejected: %s" % (index, err))
    return valid, errors


def report(valid, errors):
    try:
        rate = 100.0 * len(valid) / (len(valid) + len(errors))
    except ZeroDivisionError as err:
        return "nothing to synchronize (%s)" % err
    lines = ["synchronized %d contacts, %.1f%% clean" % (len(valid), rate)]
    for entry in valid:
        lines.append("  %s | %s | %s | %s | %.1f%% complete" % entry)
    for message in errors:
        lines.append("  ! %s" % message)
    return "\n".join(lines)


