def parse_coords(text):
    """Return ((x, y, z), error_text) parsed from an 'x,y,z' field."""
    parts = text.split(",")
    try:
        raw = (parts[0], parts[1], parts[2])
    except IndexError as err:
        return None, "coordinates truncated: %s" % err
    try:
        return (float(raw[0]), float(raw[1]), float(raw[2])), ""
    except ValueError as err:
        return None, "coordinates unreadable: %s" % err


def parse_health(text):
    """Return (hp, percent, error_text) parsed from a 'current/max' field."""
    try:
        current, maximum = [int(part) for part in text.split("/")]
        if min(current, maximum) < 0:
            raise ValueError("negative amount in '%s'" % text)
    except ValueError as err:
        return None, None, "health unreadable: %s" % err
    try:
        percent = int(100.0 * current / maximum + 0.5)
    except ZeroDivisionError as err:
        return current, None, "health scale lost: %s" % err
    return current, percent, ""


def parse_inventory(raw):
    """Return (items, error_text) from 'name:count;name:count' or pair records."""
    items = []
    try:
        entries = raw.split(";")
    except AttributeError as err:
        try:
            entries = ["%s:%s" % (pair[0], pair[1]) for pair in raw]
        except TypeError as pair_err:
            return items, "inventory record broken: %s (%s)" % (pair_err, err)
    for entry in entries:
        try:
            name, amount = entry.split(":")
            items.append("%s x%d" % (name.strip(), int(amount)))
        except ValueError as err:
            return items, "item '%s' invalid: %s" % (entry, err)
    return items, ""


def load(saves):
    """Restore every save record, collecting a report for each corrupted one."""
    players = []
    reports = []
    for index, save in enumerate(saves):
        try:
            name, position = save["name"], save["position"]
            health, inventory = save["health"], save["inventory"]
        except KeyError as err:
            reports.append("save %d: missing field %s" % (index, err))
            continue
        try:
            coords, coord_err = parse_coords(position)
            hp, percent, hp_err = parse_health(health)
            items, item_err = parse_inventory(inventory)
            failure = coord_err or hp_err or item_err
        except Exception as err:
            failure = "unreadable save: %s" % err
        if failure:
            reports.append("save %d (%s): %s" % (index, name, failure))
        else:
            players.append((name, coords, hp, percent, items))
    return players, reports

