ARTISTS = {
    "nina": {"name": "nina simone", "label": "Bethlehem"},
    "sun ra": {"name": "sun ra", "label": "Saturn"},
    "aphex": {"name": "aphex twin"},
}


def parse_title(fields):
    try:
        raw = fields[0]
        return raw[0].upper() + raw[1:], None
    except IndexError as err:
        return None, "title: %s" % err
    except TypeError as err:
        return None, "title: %s" % err


def parse_artist(fields):
    try:
        entry = ARTISTS[fields[1].strip().lower()]
        return "%s (%s)" % (entry["name"].title(), entry["label"]), None
    except KeyError as err:
        return None, "artist: no entry for %s" % err
    except AttributeError as err:
        return None, "artist: %s" % err


def parse_duration(fields):
    try:
        minutes, seconds = fields[2].split(":")
        total = int(minutes) * 60 + int(seconds)
        return total, round(int(fields[3]) * 60.0 / total, 1), None
    except ValueError as err:
        return None, None, "duration: %s" % err
    except ZeroDivisionError as err:
        return None, None, "tempo: %s" % err


def ingest(playlists):
    tracks = []
    errors = []
    for number, playlist in enumerate(playlists, 1):
        try:
            records = list(playlist)
        except TypeError as err:
            errors.append("playlist %d: %s" % (number, err))
            continue
        for position, record in enumerate(records, 1):
            label = "playlist %d track %d" % (number, position)
            try:
                if hasattr(record, "split"):
                    fields = [part.strip() for part in record.split("|")]
                else:
                    fields = list(record)
                title, problem = parse_title(fields)
                artist, artist_problem = parse_artist(fields)
                seconds, bpm, time_problem = parse_duration(fields)
                for message in (problem, artist_problem, time_problem):
                    if message is not None:
                        errors.append("%s: %s" % (label, message))
                if problem is None and artist_problem is None and time_problem is None:
                    tracks.append((title, artist, seconds, bpm))
            except TypeError as err:
                errors.append("%s: bad record sequence: %s" % (label, err))
            except Exception as err:
                errors.append("%s: unexpected %s" % (label, err))
    return tracks, errors


def summarize(tracks, errors):
    lines = []
    for title, artist, seconds, bpm in tracks:
        lines.append("%-22s %-26s %2d:%02d  %6.1f BPM"
                     % (title, artist, seconds // 60, seconds % 60, bpm))
    try:
        average = sum(track[3] for track in tracks) / float(len(tracks))
        lines.append("average tempo %.1f BPM over %d tracks" % (average, len(tracks)))
    except ZeroDivisionError as err:
        lines.append("no tempo average available: %s" % err)
    for message in errors:
        lines.append("ERROR %s" % message)
    return lines


def main():
    playlists = [
        ["Sinnerman|nina|10:20|930", "|sun ra|4:00|110", "Hiss|sun ra|0:00|118"],
        17,
        [("Windowlicker", "aphex", "6:07", "128"), ("Bad Row", 5, "3:00", "100"),
         42, ["Nubia", "nina", 200, "100"], "solar drift|sun ra|5:00|450",
         "Ain't Got No|nina|2:xx|95"],
    ]
    tracks, errors = ingest(playlists)
    for line in summarize(tracks, errors):
        print(line)


if __name__ == "__main__":
    main()

