import hashlib

HEADER_LEN = 8


def extract_header(raw):
    try:
        separator = raw[HEADER_LEN]
    except IndexError as err:
        return None, "header: %s" % err
    if separator not in (58, ":"):
        return None, "header: missing separator after %d bytes" % HEADER_LEN
    try:
        header = raw[:HEADER_LEN].decode("ascii")
    except UnicodeDecodeError as err:
        return None, "header: %s" % err
    return header.strip(), None


def extract_size(field):
    try:
        size = int(field)
    except ValueError as err:
        return None, "size: %s" % err
    except TypeError as err:
        return None, "size: %s" % err
    if size < 0:
        return None, "size: negative payload size %d" % size
    return size, None


def extract_checksum(payload, algorithm):
    data = bytearray(payload)
    try:
        spread = sum(data) // len(data)
    except ZeroDivisionError as err:
        return None, "checksum: %s" % err
    try:
        factory = getattr(hashlib, algorithm)
    except AttributeError as err:
        return None, "checksum: %s" % err
    digest = factory(bytes(payload)).hexdigest()
    return "%s-%02x" % (digest[:8], spread % 256), None


def build_packet(spec):
    try:
        raw_text, size_text, algorithm = spec.split("|")
    except ValueError as err:
        return None, "spec %r: %s" % (spec, err)
    packet = {"raw": raw_text.encode("latin-1"), "algorithm": algorithm}
    if size_text != "":
        packet["size"] = size_text
    return packet, None


def decode(packets):
    messages = []
    errors = []
    for index, packet in enumerate(packets):
        try:
            raw = packet["raw"]
            algorithm = packet["algorithm"]
        except KeyError as err:
            errors.append("packet %d: missing field %s" % (index, err))
            continue
        try:
            header, failure = extract_header(raw)
            if failure is None:
                payload = raw[HEADER_LEN + 1:]
                size, failure = extract_size(packet.get("size"))
            if failure is None:
                checksum, failure = extract_checksum(payload, algorithm)
            if failure is None and size != len(payload):
                failure = "size: declared %d but got %d" % (size, len(payload))
            if failure is not None:
                errors.append("packet %d: %s" % (index, failure))
                continue
            messages.append((header, payload.decode("utf-8", "replace"), checksum))
        except Exception as err:
            errors.append("packet %d: unhandled %s" % (index, err))
