import sys

CASTS = {"level": int, "ratio": float, "tag": str}
CHOICES = {"mode": {"fast": 1, "slow": 2}}
FORMATS = {"level": "%d", "ratio": "%.2f", "tag": "%s", "mode": "%d"}


def flag_name(token):
    try:
        if token[0] != "-" or token[1] != "-":
            return None, "not a flag: %s" % (token,)
        return token[2:], None
    except IndexError as err:
        return None, "malformed flag %r: %s" % (token, err)
    except TypeError as err:
        return None, "flag must be text, got %r: %s" % (token, err)


def convert_value(name, raw):
    if name in CHOICES:
        try:
            return CHOICES[name][raw], None
        except KeyError as err:
            return None, "unrecognized choice %s for --%s" % (err, name)
    caster = CASTS.get(name)
    if caster is None:
        return None, "unknown flag --%s" % name
    try:
        return caster(raw), None
    except ValueError as err:
        return None, "bad value for --%s: %s" % (name, err)


def enforce_constraint(name, value):
    if name == "ratio":
        try:
            share = 100.0 / value
        except ZeroDivisionError as err:
            return None, "--ratio must be non-zero: %s" % err
        if share > 1000.0:
            return None, "--ratio %s is too small" % value
        return value, None
    if name == "tag":
        try:
            cleaned = value.strip().lower()
        except AttributeError as err:
            return None, "--tag needs text: %s" % err
        if not cleaned:
            return None, "--tag must not be blank"
        return cleaned, None
    return value, None


def extract(arguments):
    options = []
    errors = []
    try:
        total = len(arguments)
    except TypeError as err:
        return options, ["argument list is not a sequence: %s" % err]
    index = 0
    while index < total:
        token = arguments[index]
        index += 1
        name, problem = flag_name(token)
        if problem is not None:
            errors.append(problem)
            continue
        if index >= total:
            errors.append("--%s expects a value" % name)
            continue
        value, problem = convert_value(name, arguments[index])
        index += 1
        if problem is not None:
            errors.append(problem)
            continue
        value, problem = enforce_constraint(name, value)
        if problem is not None:
            errors.append(problem)
            continue
        try:
            options.append((name, value, "--%s=%s" % (name, FORMATS[name] % value)))
        except TypeError as err:
            errors.append("cannot render --%s: %s" % (name, err))
        except Exception as err:
            errors.append("failed to handle %s: %s" % (token, err))
    return options, errors


def main(argv):
    options, errors = extract(argv[1:])
    for option in options:
        print("accepted %s" % option[2])
    for message in errors:
        print("error: %s" % message)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

