import sys
import time

DEFAULT_RATE = 0.035
ID_PREFIX_SEPARATOR = "-"


def migrate_identifier(raw_id):
    try:
        width = len(raw_id)
    except TypeError as err:
        return None, "identifier is null: %s" % err
    try:
        prefix, digits = raw_id.split(ID_PREFIX_SEPARATOR)
        number = int(digits)
    except ValueError as err:
        return None, "identifier layout: %s" % err
    padding = width - len(prefix) - len(ID_PREFIX_SEPARATOR)
    return "%s%s%0*d" % (prefix.upper(), ID_PREFIX_SEPARATOR, padding, number), None


def migrate_balance(raw_balance, term_months, rate):
    try:
        amount = float(raw_balance)
    except ValueError as err:
        return None, "balance is not numeric: %s" % err
    try:
        interest = amount * rate / term_months
    except ZeroDivisionError as err:
        return None, "interest period invalid: %s" % err
    return round(amount + interest, 2), None


def migrate_date(raw_date):
    parts = raw_date.split("/")
    try:
        normalized = "%s-%s-%s" % (parts[2], parts[1], parts[0])
    except IndexError as err:
        return None, "date is truncated: %s" % err
    try:
        stamp = time.strptime(normalized, "%Y-%m-%d")
    except ValueError as err:
        return None, "date does not parse: %s" % err
    return time.strftime("%Y-%m-%d", stamp), None


def migrate(records, rate=DEFAULT_RATE):
    migrated = []
    failures = []
    for position, record in enumerate(records):
        try:
            raw_id = record["id"]
            raw_balance = record["balance"]
            raw_date = record["created"]
            term_months = record["term_months"]
        except KeyError as err:
            failures.append("record %d: missing field %s" % (position, err))
            continue
        try:
            new_id, id_error = migrate_identifier(raw_id)
            new_balance, balance_error = migrate_balance(raw_balance, term_months, rate)
            new_date, date_error = migrate_date(raw_date)
        except Exception as err:
            failures.append("record %d: unhandled %s" % (position, err))
            continue
        problem = id_error or balance_error or date_error
        if problem:
            failures.append("record %d: %s" % (position, problem))
        else:
            migrated.append((new_id, new_balance, new_date))
    return migrated, failures


def parse_rate(text):
    try:
        return float(text)
    except ValueError as err:
        sys.stderr.write("ignoring rate argument (%s)\n" % err)
        return DEFAULT_RATE


def main(argv):
    rate = parse_rate(argv[1]) if len(argv) > 1 else DEFAULT_RATE
    legacy = [
        {"id": "usr-42", "balance": "1500.00", "created": "31/12/2019", "term_months": 12},
        {"id": None, "balance": "10", "created": "01/01/2020", "term_months": 6},
        {"id": "usr-7", "balance": "abc", "created": "01/01/2020", "term_months": 6},
        {"id": "usr-8", "balance": "99.5", "created": "02/02/2021", "term_months": 0},
        {"id": "usr-9", "balance": "20", "created": "2021", "term_months": 3},
        {"id": "usr-10", "balance": "20", "created": "31/31/2021", "term_months": 3},
        {"id": "usr-11", "created": "01/03/2021", "term_months": 3},
    ]
    migrated, failures = migrate(legacy, rate)
    for row in migrated:
        print("OK %s | %.2f | %s" % row)
    for line in failures:
        print("FAIL %s" % line)


if __name__ == "__main__":
    main(sys.argv)

