import os

BOOL_WORDS = ["false", "true"]
BOOLEAN_KEYS = ("debug", "verbose")


class Environment(object):
    def __init__(self, name, memory_limit, permissions=None):
        self.name = name
        self.memory_limit = memory_limit
        if permissions is not None:
            self.permissions = permissions


def extract_key(line):
    try:
        fields = line.split("=", 1)
        key = fields[0].strip().lower()
        value = fields[1].strip()
    except IndexError as err:
        return None, None, str(err)
    except TypeError as err:
        return None, None, str(err)
    return key, value, None


def convert_value(key, raw):
    try:
        if raw.startswith("$"):
            raw = os.environ[raw[1:]]
        if key in BOOLEAN_KEYS:
            return bool(BOOL_WORDS.index(raw.lower())), None
        if raw.isdigit() or raw.startswith("-"):
            return int(raw), None
    except ValueError as err:
        return None, str(err)
    except KeyError as err:
        return None, str(err)
    return raw, None


def configure(lines):
    settings = []
    alerts = []
    for index, line in enumerate(lines, 1):
        try:
            key, raw, problem = extract_key(line)
            if problem is not None:
                detail = [index, problem]
                alerts.append("line %d: missing separator (%s)" % detail)
                continue
            if key == "" or key.startswith("#"):
                continue
            value, problem = convert_value(key, raw)
            if problem is not None:
                alerts.append("line %d: %s=%s rejected (%s)" % (index, key, raw, problem))
                continue
            settings.append((key, value))
        except TypeError as err:
            alerts.append("line %d: alert formatting failed (%s)" % (index, err))
        except Exception as err:
            alerts.append("line %d: unexpected %s (%s)" % (index, err.__class__.__name__, err))
    return settings, alerts


def validate_environment(env, values):
    try:
        share = env.memory_limit // values.get("workers", 1)
        mode = env.permissions
    except AttributeError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)
    return "%s: %d MB per worker, mode %o" % (env.name, share, mode)


def main():
    os.environ["APP_HOME"] = "/srv/app"
    primary = ["# main config", "port=8080", "debug=true", "workers=4",
               "home=$APP_HOME", "timeout-broken", "token=$MISSING_TOKEN"]
    fallback = ["workers=0", "debug=yes", b"port=9090"]
    jobs = (("primary", primary, Environment("primary", 2048, 0o640)),
            ("fallback", fallback, Environment("fallback", 512)))
    for name, lines, env in jobs:
        settings, alerts = configure(lines)
        print("%s settings: %s" % (name, settings))
        for alert in alerts:
            print("  alert: " + alert)
        print("  env: " + validate_environment(env, dict(settings)))


if __name__ == "__main__":
    main()

