def extract_code(field):
    try:
        code = field.strip().upper()
        int(code, 36)
    except ValueError as err:
        return None, str(err)
    try:
        head = code[0]
        serial = code[5]
    except IndexError as err:
        return None, str(err)
    if not (head.isalpha() and serial.isdigit()):
        return None, "malformed product code %s" % code
    return code, None


def quantity_change(qty_field, pack_field):
    try:
        units = int(qty_field.strip())
        pack_size = int(pack_field.strip())
        packs = units // pack_size
    except ValueError as err:
        return None, None, str(err)
    except ZeroDivisionError as err:
        return None, None, str(err)
    return units, packs, None


def locate_bin(code, zone, layout):
    try:
        shelf = layout[zone.strip().upper()]
    except KeyError as err:
        return None, str(err)
    try:
        slot = shelf.get(code[0], shelf.get("*"))
    except AttributeError as err:
        return None, str(err)
    if slot is None:
        return None, "no slot for %s in zone %s" % (code, zone)
    return "%s-%s" % (zone.strip().upper(), slot), None


