import sys

FORMULARY = {
    "aspirin": "aspirin 81mg (antiplatelet)",
    "metformin": "metformin 500mg (antidiabetic)",
    "lisinopril": "lisinopril 10mg (ace inhibitor)",
    "atorvastatin": "atorvastatin 20mg (statin)",
}

SAMPLE_RECORDS = [
    "name=Ann Blake; age=34; bp=128/82; meds=aspirin, metformin",
    "name=Bo Chen; age=12775/365; bp=140/90; bp=138/86; meds=lisinopril",
    "name=Cara Diaz; age=fifty; bp=118/76; meds=aspirin",
    "name=Dev Efron; bp=150; meds=atorvastatin",
    "name=Eve Fisher; age=4015/0; meds=aspirin",
    "name=Ida Gray; age=61; bp=134/88; meds=herbal tonic",
    "name=Jon Hale; age=47; bp=126/80",
]


def extract_age(raw):
    try:
        if "/" in raw:
            days, days_per_year = raw.split("/", 1)
            return int(days) // int(days_per_year)
        return int(raw)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def measure_pressure(readings):
    try:
        parts = readings[0].split("/")
        systolic = int(parts[0])
        diastolic = int(parts[1])
        return "%d/%d (span %d)" % (systolic, diastolic, systolic - diastolic)
    except IndexError as err:
        return str(err)
    except TypeError as err:
        return str(err)


def list_medications(raw, formulary):
    try:
        names = [name.strip().lower() for name in raw.split(",")]
        return [formulary[name] for name in names if name]
    except AttributeError as err:
        return str(err)
    except KeyError as err:
        return str(err)


def parse_fields(record):
    fields = {}
    for chunk in record.split(";"):
        if "=" not in chunk:
            continue
        key, value = chunk.split("=", 1)
        key = key.strip().lower()
        if key == "bp":
            fields.setdefault("bp", []).append(value.strip())
        else:
            fields[key] = value.strip()
    return fields


def review(patients):
    records = []
    errors = []
    for index, record in enumerate(patients):
        try:
            fields = parse_fields(record)
            age = extract_age(fields.get("age", ""))
            pressure = measure_pressure(fields.get("bp"))
            drugs = list_medications(fields.get("meds"), FORMULARY)
            label = "%s, %d yrs" % (fields.get("name", "unknown"), age)
            records.append((label, age, pressure, drugs))
        except TypeError as err:
            errors.append("record %d: %s" % (index, err))
        except Exception as err:
            errors.append("record %d: unexpected %s" % (index, err))
    return records, errors


def mean_age(records):
    total = sum(entry[1] for entry in records)
    try:
        return "%.1f" % (total / float(len(records)))
    except ZeroDivisionError as err:
        return str(err)


def main(argv):
    lines = SAMPLE_RECORDS
    if len(argv) > 1:
        try:
            handle = open(argv[1])
            lines = [line for line in handle.read().splitlines() if line.strip()]
            handle.close()
        except IOError as err:
            print("cannot read chart file: %s" % (err,))
            return 1
    records, errors = review(lines)
    for entry in records:
        print("%s | BP %s | meds: %s" % (entry[0], entry[2], entry[3]))
    print("mean age: %s" % (mean_age(records),))
    for message in errors:
        print("ERROR %s" % (message,))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

