import math

def extract_temperature(payload):
    try:
        raw = payload["temperature"]
    except KeyError as err:
        return None, "missing temperature key %s" % err
    try:
        celsius = float(raw)
    except (TypeError, ValueError) as err:
        return None, "bad temperature value: %s" % err
    if math.isnan(celsius):
        return None, "temperature is not a number"
    return celsius, None


def peak_voltage(payload):
    try:
        readings = payload["power"]
    except KeyError as err:
        return None, "missing power key %s" % err
    try:
        first = readings[0]
    except IndexError as err:
        return None, "empty power array: %s" % err
    except TypeError as err:
        return None, "power is not indexable: %s" % err
    peak = None
    for index in range(len(readings)):
        try:
            value = float(readings[index])
        except (TypeError, ValueError) as err:
            return None, "non-numeric power at index %d: %s" % (index, err)
        if peak is None or value > peak:
            peak = value
    if first < 0:
        return None, "power array starts below zero"
    return peak, None


def efficiency_ratio(payload):
    try:
        output = float(payload["output"])
        intake = float(payload["intake"])
    except KeyError as err:
        return None, "missing metric %s" % err
    except (TypeError, ValueError) as err:
        return None, "unusable metric: %s" % err
    try:
        ratio = output / intake
    except ZeroDivisionError as err:
        return None, "intake is zero: %s" % err
    return ratio, None


def summarize(index, payload):
    celsius, problem = extract_temperature(payload)
    if problem is not None:
        return "payload %d rejected: %s" % (index, problem)
    peak, problem = peak_voltage(payload)
    if problem is not None:
        return "payload %d rejected: %s" % (index, problem)
    ratio, problem = efficiency_ratio(payload)
    if problem is not None:
        return "payload %d rejected: %s" % (index, problem)
    try:
        label = payload["id"].strip()
    except KeyError as err:
        return "payload %d rejected: missing identifier %s" % (index, err)
    except AttributeError as err:
        return "payload %d rejected: identifier not text: %s" % (index, err)
    return "%s: temp=%.1fC peak=%.2fV eff=%.3f" % (label, celsius, peak, ratio)


def validate(payloads):
    results = []
    for index in range(len(payloads)):
        payload = payloads[index]
        try:
            results.append(summarize(index, payload))
        except TypeError as err:
            results.append("payload %d rejected: not a mapping: %s" % (index, err))
    return results


def main():
    batch = [
        {"id": " probe-a ", "temperature": "-41.5", "power": [3, 7.5, 2],
         "output": 40, "intake": 50},
        {"id": "probe-b", "temperature": "warm", "power": [1], "output": 1,
         "intake": 2},
        {"id": "probe-c", "temperature": 12, "power": [], "output": 1,
         "intake": 2},
        {"id": "probe-d", "temperature": 5, "power": [2, 4], "output": 3,
         "intake": 0},
        {"temperature": 5, "power": [2, 4], "output": 3, "intake": 1},
        ["not", "a", "mapping"],
    ]
    for line in validate(batch):
        print(line)


if __name__ == "__main__":
    main()

