RISK_MULTIPLIERS = {
    "equity": 1.4,
    "bond": 0.6,
    "cash": 0.1,
    "commodity": 1.8,
}


def moving_average(prices, window):
    """Average of the last `window` historical prices."""
    try:
        values = [float(p) for p in prices[-window:]]
        return sum(values) / len(values)
    except ValueError as err:
        print("bad price value: %s" % err)
        return 0.0
    except ZeroDivisionError as err:
        print("no prices to average: %s" % err)
        return 0.0
    except TypeError as err:
        print("unusable price window: %s" % err)
        return 0.0


def parse_weighting(asset, index):
    """Return the weighting of the asset at `index` inside its own list."""
    try:
        raw = asset["weights"][index]
        weight = float(raw)
        if weight < 0:
            raise ValueError("negative weighting %r" % raw)
        return weight
    except KeyError as err:
        print("asset has no weights entry: %s" % err)
        return 0.0
    except IndexError as err:
        print("weighting slot %d missing: %s" % (index, err))
        return 0.0
    except ValueError as err:
        print("invalid weighting: %s" % err)
        return 0.0


def category_multiplier(asset):
    try:
        category = asset["category"].strip().lower()
        return RISK_MULTIPLIERS[category]
    except KeyError as err:
        print("unknown category mapping: %s" % err)
        return 1.0
    except AttributeError as err:
        print("category is not text: %s" % err)
        return 1.0
    except TypeError as err:
        print("category not hashable: %s" % err)
        return 1.0


def score_asset(asset, index):
    average = moving_average(asset.get("prices", []), 3)
    weight = parse_weighting(asset, index)
    return average * weight * category_multiplier(asset)


def analyze(portfolios):
    scores = []
    for portfolio in portfolios:
        total = 0.0
        try:
            for index, asset in enumerate(portfolio):
                total += score_asset(asset, index)
        except TypeError as err:
            print("portfolio not iterable: %s" % err)
            scores.append(None)
            continue
        except AttributeError as err:
            print("asset is not a mapping: %s" % err)
            scores.append(None)
            continue
        scores.append(round(total, 2))
    return scores


def main():
    data = [
        [
            {"category": "equity", "prices": [10, 11, 12], "weights": [0.5]},
            {"category": "Bond", "prices": ["100", "102", "104"], "weights": [0.2, 0.3]},
        ],
        [
            {"category": "gold", "prices": [], "weights": [1.0]},
            {"category": "cash", "prices": [1, 1, "x"], "weights": [-0.4]},
        ],
        [42],
        None,
    ]
    for line in ("portfolio %d risk: %s" % (i, s) for i, s in enumerate(analyze(data))):
        print(line)


if __name__ == "__main__":
    main()

