import sys

USERS = ["alice", "bob", "carol", "dave"]


def handle_message(args):
    try:
        target = args[0]
    except IndexError as err:
        return "message error: no recipient (%s)" % err
    if target.startswith("#"):
        try:
            index = int(target[1:])
        except ValueError as err:
            return "message error: bad user index (%s)" % err
        try:
            target = USERS[index]
        except IndexError as err:
            return "message error: index out of bounds (%s)" % err
    elif not target.isalnum():
        return "message error: invalid identifier '%s'" % target
    body = " ".join(args[1:])
    if not body:
        return "message error: nothing to send to %s" % target
    return "to %s: %s" % (target, body)


def handle_math(args):
    try:
        operator = args[0]
        left_text = args[1]
        right_text = args[2]
    except IndexError as err:
        return "math error: missing operand (%s)" % err
    try:
        left = float(left_text)
        right = float(right_text)
    except ValueError as err:
        return "math error: non-numeric operand (%s)" % err
    operations = {
        "add": lambda a, b: a + b,
        "sub": lambda a, b: a - b,
        "mul": lambda a, b: a * b,
        "div": lambda a, b: a / b,
    }
    try:
        function = operations[operator]
    except KeyError as err:
        return "math error: unsupported operator %s" % err
    try:
        result = function(left, right)
    except ZeroDivisionError as err:
        return "math error: division by zero (%s)" % err
    return "%s(%s, %s) = %g" % (operator, left_text, right_text, result)


def handle_moderation(args):
    try:
        name = args[0]
    except IndexError as err:
        return "moderation error: no user given (%s)" % err
    if name not in USERS:
        return "moderation error: unknown user '%s'" % name
    duration = 60
    if len(args) > 1:
        try:
            duration = int(args[1])
        except ValueError as err:
            return "moderation error: invalid duration (%s)" % err
    return "muted %s for %d seconds" % (name, duration)


def execute(commands):
    handlers = {"msg": handle_message, "calc": handle_math, "mute": handle_moderation}
    responses = []
    for line in commands:
        words = line.split()
        if not words:
            responses.append("empty command ignored")
            continue
        try:
            handler = handlers[words[0]]
        except KeyError as err:
            responses.append("unknown command %s" % err)
            continue
        responses.append(handler(words[1:]))
    return responses


def main():
    lines = [line.rstrip("\n") for line in sys.stdin]
    for response in execute(lines):
        print(response)


if __name__ == "__main__":
    main()

