ROUTE_MAP = {
    "boston": [42.36, -71.06],
    "denver": [39.74, -104.99],
    "miami": [25.76, -80.19],
    "seattle": [],
}

WEIGHT_CLASS = {
    "light": 1.0,
    "standard": 2.5,
    "heavy": 4.0,
}


def compute_distance(destination, axis):
    try:
        coords = ROUTE_MAP[destination]
    except KeyError as err:
        return None, "unknown destination %s" % err
    try:
        base = coords[axis]
    except IndexError as err:
        return None, "coordinate index error: %s" % err
    try:
        span = abs(base) * 60.0 / len(coords)
    except ZeroDivisionError as err:
        return None, "empty coordinate list: %s" % err
    return round(span, 2), None


def convert_weight(raw_weight, category):
    try:
        kilos = float(raw_weight)
    except ValueError as err:
        return None, "bad weight value: %s" % err
    try:
        factor = WEIGHT_CLASS[category]
    except KeyError as err:
        return None, "unknown weight class %s" % err
    return round(kilos * factor, 2), None


def estimate_cost(pounds, miles, multiplier):
    try:
        per_mile = pounds / miles
    except ZeroDivisionError as err:
        return None, "zero mileage: %s" % err
    try:
        total = per_mile * multiplier * miles
    except TypeError as err:
        return None, "bad multiplier: %s" % err
    try:
        if total < 0:
            raise ArithmeticError("negative total %.2f" % total)
    except ArithmeticError as err:
        return None, "cost rejected: %s" % err
    return round(total, 2), None


def route(shipments):
    results = []
    for record in shipments:
        try:
            dest = record["destination"]
            weight = record["weight"]
            klass = record["class"]
        except KeyError as err:
            results.append("FAILED: missing field %s" % err)
            continue
        miles, problem = compute_distance(dest, record.get("axis", 0))
        if problem:
            results.append("FAILED: %s" % problem)
            continue
        pounds, problem = convert_weight(weight, klass)
        if problem:
            results.append("FAILED: %s" % problem)
            continue
        cost, problem = estimate_cost(pounds, miles, record.get("rate", 1.0))
        if problem:
            results.append("FAILED: %s" % problem)
            continue
        results.append("%s: %.2f mi, %.2f kg, $%.2f" % (dest, miles, pounds, cost))
    return results


def main():
    shipments = [
        {"destination": "boston", "weight": "120", "class": "standard"},
        {"destination": "atlantis", "weight": "10", "class": "light"},
        {"destination": "seattle", "weight": "10", "class": "light"},
        {"destination": "denver", "weight": "5", "class": "light", "axis": 4},
        {"destination": "miami", "weight": "heavy-ish", "class": "heavy"},
        {"destination": "miami", "weight": "40", "class": "featherweight"},
        {"destination": "denver", "weight": "80", "class": "heavy", "rate": "fast"},
        {"destination": "boston", "weight": "60", "class": "light", "rate": -2.0},
        {"weight": "60", "class": "light"},
    ]
    for line in route(shipments):
        print(line)


if __name__ == "__main__":
    main()

