ANSWER_KEY = ['a', 'c', 'b', 'd']
MAX_MC_POINTS = 60.0
MAX_ESSAY_POINTS = 40.0


def grade_multiple_choice(submission):
    notes = []
    try:
        answers = submission['answers']
    except KeyError as err:
        return 0.0, ['no multiple choice section (%s)' % err]
    correct = 0
    for position, choice in enumerate(answers):
        try:
            expected = ANSWER_KEY[position]
        except IndexError as err:
            notes.append('answer %d has no key entry (%s)' % (position, err))
            break
        try:
            given = choice.strip().lower()
        except AttributeError as err:
            notes.append('answer %d is not text (%s)' % (position, err))
            continue
        if given == expected:
            correct += 1
    return MAX_MC_POINTS * correct / float(len(ANSWER_KEY)), notes


def evaluate_essay(submission):
    try:
        paragraphs = submission['essay']
    except KeyError as err:
        return 0.0, ['no essay submitted (%s)' % err]
    notes = []
    try:
        opening = paragraphs[0]
    except IndexError as err:
        return 0.0, ['essay contains no paragraphs (%s)' % err]
    if not opening[:1].isupper():
        notes.append('opening paragraph is not capitalised')
    words = []
    for paragraph in paragraphs:
        words.extend(paragraph.split())
    try:
        average = sum(len(word) for word in words) / float(len(words))
    except ZeroDivisionError as err:
        return 0.0, ['essay has no words to measure (%s)' % err]
    length_score = min(1.0, len(words) / 120.0)
    style_score = min(1.0, average / 5.0)
    return MAX_ESSAY_POINTS * (0.7 * length_score + 0.3 * style_score), notes


def calculate_bonus(submission):
    try:
        raw = submission['bonus']
    except KeyError as err:
        return 0.0, ['no extra credit recorded (%s)' % err]
    try:
        return float(raw), []
    except ValueError as err:
        return 0.0, ['extra credit is not numeric (%s)' % err]


def describe(student_id, total, notes):
    letter = 'F'
    for bound, mark in [(90, 'A'), (80, 'B'), (70, 'C'), (60, 'D')]:
        if total >= bound:
            letter = mark
            break
    text = '%s: %.1f (%s)' % (student_id, total, letter)
    if notes:
        text += ' - ' + '; '.join(notes)
    return text


def grade(submissions):
    results = []
    for submission in submissions:
        try:
            student_id = submission['student_id']
        except KeyError as err:
            results.append('unidentified submission rejected (%s)' % err)
            continue
        mc_points, notes = grade_multiple_choice(submission)
        essay_points, essay_notes = evaluate_essay(submission)
        bonus, bonus_notes = calculate_bonus(submission)
        total = min(100.0, mc_points + essay_points + bonus)
        results.append(describe(student_id, total, notes + essay_notes + bonus_notes))
    return results


def load_submissions(path):
    import json
    try:
        handle = open(path)
    except IOError as err:
        print('cannot read %s (%s)' % (path, err))
        return []
    try:
        return json.load(handle)
    except ValueError as err:
        print('%s is not valid JSON (%s)' % (path, err))
        return []
    finally:
        handle.close()


def main():
    import sys
    if len(sys.argv) > 1:
        submissions = load_submissions(sys.argv[1])
    else:
        submissions = [
            {'student_id': 's1', 'answers': ['A', 'c', 'b', 'd'],
             'essay': ['Water cycles through the air.', 'Rain returns it to rivers.'],
             'bonus': '2.5'},
            {'student_id': 's2', 'answers': ['a', 7, 'b', 'd', 'a'],
             'essay': [], 'bonus': 'none'},
            {'answers': ['a'], 'essay': ['   ']},
        ]
    for line in grade(submissions):
        print(line)


if __name__ == '__main__':
    main()

