def parse_temperature(device):
    try:
        readings = device["sensors"]["temperature"]
    except KeyError as err:
        return "temp=unavailable(missing %s)" % err
    try:
        latest = readings[-1]
    except IndexError as err:
        return "temp=unavailable(no samples: %s)" % err
    try:
        celsius = float(latest)
    except ValueError as err:
        return "temp=unavailable(bad sample: %s)" % err
    return "temp=%.1fC" % celsius


def analyze_battery(device):
    section = device.get("battery", {})
    history = section.get("history", [])
    try:
        first, last = history[0], history[-1]
    except IndexError as err:
        return "battery=unknown(empty history: %s)" % err
    try:
        drop = first - last
    except TypeError as err:
        return "battery=unknown(bad reading type: %s)" % err
    try:
        drain = drop / float(section.get("hours", 0))
    except ZeroDivisionError as err:
        return "battery=%d%% (drain unknown: %s)" % (last, err)
    return "battery=%d%% (drain %.2f%%/h)" % (last, drain)


def build_ip_map(devices):
    ip_map = {}
    unmapped = []
    for record in devices:
        try:
            ip_map[record["id"]] = record["network"]["ip"]
        except (KeyError, TypeError) as err:
            unmapped.append("%s" % err)
    return ip_map, unmapped


def check_network(device, ip_map):
    try:
        address = ip_map[device["id"]]
    except KeyError as err:
        return "net=offline(no ip for %s)" % err
    try:
        port = int(device["network"].get("port", "0"))
    except ValueError as err:
        return "net=%s(bad port: %s)" % (address, err)
    return "net=%s:%d" % (address, port)


def synchronize(devices):
    ip_map, unmapped = build_ip_map(devices)
    summary = []
    for record in devices:
        try:
            label = record["name"]
        except TypeError as err:
            summary.append("malformed record: %s" % err)
            continue
        parts = [parse_temperature(record),
                 analyze_battery(record),
                 check_network(record, ip_map)]
        summary.append("%s: %s" % (label, ", ".join(parts)))
    if unmapped:
        summary.append("hub: %d device(s) without ip mapping" % len(unmapped))
    return summary


def main():
    devices = [
        {"id": "th1", "name": "Thermostat",
         "sensors": {"temperature": ["20.5", "21.25"]},
         "battery": {"history": [98, 91], "hours": 24},
         "network": {"ip": "10.0.0.4", "port": "8080"}},
        {"id": "cam2", "name": "Camera",
         "sensors": {"temperature": []},
         "battery": {"history": ["80%", "72%"], "hours": 12},
         "network": {"ip": "10.0.0.7", "port": "https"}},
        {"id": "snk3", "name": "Smoke Alarm",
         "sensors": {"humidity": [0.4]},
         "battery": {"history": [55], "hours": 0},
         "network": {"port": "9000"}},
        ["broken", "record"],
    ]
    for line in synchronize(devices):
        print(line)


if __name__ == "__main__":
    main()

