    except KeyError, err:
        return "net=offline(no ip for %s)" % err
    try:
        port = int(device["network"].get("port", "0"))
    except ValueError, err:
        return "net=%s(bad port: %s)" % (address, err)
    return "net=%s:%d" % (address, port)


def synchronize(devices):
    ip_map, unmapped = build_ip_map(devices)
    summary = []
    for record in devices:
        try:
            label = record["name"]
        except TypeError, err:
            summary.append("malformed record: %s" % err)
            continue
        parts = [parse_temperature(record),
                 analyze_battery(record),
                 check_network(record, ip_map)]
        summary.append("%s: %s" % (label, ", ".join(parts)))
    if unmapped:
        summary.append("hub: %d device(s) without ip mapping" % len(unmapped))
    return summary


