    "vancomycin": {"base_mg_per_kg": 15, "forms": [500, 1000]},
    "cefalexin": {"base_mg_per_kg": 25, "forms": []},
}


def _validated_rate(patient, entry):
    rate = patient.get("dose_override", entry["base_mg_per_kg"])
    if rate < 0:
        raise ValueError("negative mg/kg rate %s" % rate)
    return rate


def parse_demographics(patient):
    profile = {}
    try:
        profile["age"] = int(patient["age"])
    except KeyError as err:
        return {"error": "missing demographic field %s" % err}
    except ValueError as err:
        return {"error": "unreadable age (%s)" % err}
    try:
        raw_weight = patient["weight_history"][-1]
    except KeyError as err:
        return {"error": "missing weight history %s" % err}
    except IndexError as err:
        return {"error": "no recorded weight (%s)" % err}
    try:
        profile["weight"] = float(raw_weight)
    except ValueError as err:
        return {"error": "invalid weight string (%s)" % err}
    return profile


def lookup_base_dose(patient):
    name = patient.get("medication", "").strip().lower()
    try:
        entry = DOSE_TABLE[name]
    except KeyError as err:
        return {"error": "unrecognized medication %s" % err}
    try:
        per_kg = _validated_rate(patient, entry)
    except ValueError as err:
        return {"error": "bad dosage rate (%s)" % err}
    try:
        unit = sorted(entry["forms"])[0]
    except IndexError as err:
        return {"error": "no formulation stocked (%s)" % err}
    return {"per_kg": per_kg, "unit": unit, "name": name}


def compute_adjustment(patient, profile, base):
    try:
        factor = min(1.0, 90.0 / float(patient.get("kidney_score", 90)))
    except ZeroDivisionError as err:
        return {"error": "kidney function score of zero (%s)" % err}
    try:
        allergies = [a.strip().lower() for a in patient.get("allergies", [])]
    except TypeError as err:
        return {"error": "allergy list is not iterable (%s)" % err}
    except AttributeError as err:
        return {"error": "non-text allergy entry (%s)" % err}
    if base["name"] in allergies:
        return {"error": "allergy contraindication for %s" % base["name"]}
    if profile["age"] < 12:
        factor = factor * 0.6
    return {"factor": factor}


def calculate(patients):
    results = []
    for patient in patients:
        try:
            pid = patient["id"]
        except KeyError as err:
            results.append("ERROR: patient record without identifier %s" % err)
            continue
        stages = [parse_demographics(patient)]
        stages.append(lookup_base_dose(patient))
        failed = [s for s in stages if "error" in s]
        if failed:
            results.append("ERROR %s: %s" % (pid, failed[0]["error"]))
            continue
        profile, base = stages
        adj = compute_adjustment(patient, profile, base)
        if "error" in adj:
            results.append("ERROR %s: %s" % (pid, adj["error"]))
            continue
        milligrams = profile["weight"] * base["per_kg"] * adj["factor"]
        units = max(1, int(round(milligrams / base["unit"])))
        results.append("%s: %s %d mg (%d x %d mg)" % (
            pid, base["name"], units * base["unit"], units, base["unit"]))
    return results


def main():
    patients = [
        {"id": "P1", "age": 40, "weight_history": [70.5], "medication": "Amoxicillin"},
        {"id": "P2", "age": 8, "weight_history": ["24"], "medication": "ibuprofen",
         "kidney_score": 45},
        {"id": "P3", "age": 55, "weight_history": [], "medication": "vancomycin"},
        {"id": "P4", "age": 30, "weight_history": ["heavy"], "medication": "ibuprofen"},
        {"id": "P5", "age": 60, "weight_history": [80], "medication": "aspirin"},
        {"id": "P6", "age": 25, "weight_history": [65], "medication": "cefalexin"},
        {"id": "P7", "age": 70, "weight_history": [60], "medication": "vancomycin",
         "kidney_score": 0},
        {"id": "P8", "age": 33, "weight_history": [55], "medication": "ibuprofen",
         "allergies": None},
        {"id": "P9", "age": 33, "weight_history": [55], "medication": "ibuprofen",
         "allergies": ["ibuprofen"]},
        {"age": 33, "weight_history": [55], "medication": "ibuprofen"},
    ]
    for line in calculate(patients):
        print(line)


if __name__ == "__main__":
    main()

