import math

ENCHANTMENTS = {"fire": 12, "frost": 9, "holy": 15, "void": 20}


def parse_weapon(weapon):
    try:
        rolls = weapon["damage"]
    except KeyError as err:
        print("weapon is missing key %s" % err)
        return 0
    try:
        primary = rolls[0]
    except IndexError as err:
        print("weapon has no damage rolls: %s" % err)
        return 0
    try:
        base = int(primary)
    except ValueError as err:
        print("primary roll is not a number: %s" % err)
        return 0
    bonus = 0
    for extra in rolls[1:]:
        try:
            bonus += int(extra)
        except ValueError as err:
            print("ignoring secondary roll %r (%s)" % (extra, err))
    return base + bonus


def calculate_armor(armor):
    plates = armor.get("defense", [])
    try:
        weakest = min(plates)
    except ValueError as err:
        print("empty defense array: %s" % err)
        return 0.0, 0.0
    try:
        scale = math.sqrt(armor.get("balance", 1))
    except ValueError as err:
        print("negative balance constraint: %s" % err)
        scale = 1.0
    total = sum(plates)
    try:
        mitigation = total / float(armor["weight"])
    except ZeroDivisionError as err:
        print("weightless armor breaks mitigation ratio: %s" % err)
        mitigation = 0.0
    except KeyError as err:
        print("armor is missing key %s" % err)
        mitigation = 0.0
    return (total + weakest) * scale, mitigation


def evaluate_accessory(accessory):
    try:
        power = ENCHANTMENTS[accessory.get("enchantment")]
    except KeyError as err:
        print("unknown enchantment mapping for %s" % err)
        return 0.0
    try:
        multiplier = float(accessory.get("multiplier"))
    except TypeError as err:
        print("invalid multiplier type: %s" % err)
        multiplier = 1.0
    except ValueError as err:
        print("multiplier string is not numeric: %s" % err)
        multiplier = 1.0
    return power * multiplier


def equip(characters):
    stats = []
    for character in characters:
        name = character.get("name", "unnamed")
        try:
            inventory = character["inventory"]
        except KeyError as err:
            print("%s carries no inventory (%s)" % (name, err))
            inventory = {}
        defense, mitigation = calculate_armor(inventory.get("armor", {}))
        stats.append({"name": name,
                      "attack": parse_weapon(inventory.get("weapon", {})),
                      "defense": defense,
                      "mitigation": mitigation,
                      "magic": evaluate_accessory(inventory.get("accessory", {}))})
    return stats


def main():
    roster = [
        {"name": "Aria", "inventory": {"weapon": {"damage": ["12", "4", "x"]},
                                       "armor": {"defense": [5, 9], "weight": 7, "balance": 4},
                                       "accessory": {"enchantment": "fire", "multiplier": "2.5"}}},
        {"name": "Borin", "inventory": {"weapon": {"crit": 3},
                                        "armor": {"defense": [], "weight": 0},
                                        "accessory": {"enchantment": "chaos", "multiplier": 2}}},
        {"name": "Cael", "inventory": {"weapon": {"damage": []},
                                       "armor": {"defense": [4], "weight": 0, "balance": -9},
                                       "accessory": {"enchantment": "void"}}},
        {"name": "Dain"},
    ]
    for entry in equip(roster):
        print("%-6s atk=%d def=%.1f mit=%.2f magic=%.1f" % (entry["name"], entry["attack"],
                                                            entry["defense"], entry["mitigation"],
                                                            entry["magic"]))


if __name__ == "__main__":
    main()

