text_nat:
NUTRIENT_DB = {
    'oats': {'protein': 13.0, 'carbs': 67.0, 'fat': 7.0},
    'milk': {'protein': 3.4, 'carbs': 5.0, 'fat': 1.0},
    'peanut': {'protein': 26.0, 'carbs': 16.0, 'fat': 49.0},
    'chicken': {'protein': 27.0, 'carbs': 0.0, 'fat': 3.6},
    'rice': {'protein': 7.0, 'carbs': 78.0, 'fat': 0.6},
}
UNIT_GRAMS = {'g': 1.0, 'kg': 1000.0, 'cup': 120.0, 'tbsp': 15.0}
KNOWN_ALLERGENS = ('nuts', 'dairy', 'gluten', 'soy')


def match_ingredients(recipe):
    matched = []
    notes = []
    for raw in recipe['ingredients']:
        try:
            parts = raw.split()
            amount = float(parts[0])
            unit = parts[1]
            name = parts[2].lower()
        except AttributeError as err:
            notes.append("ingredient entry %r is not text (%s)" % (raw, err))
            continue
        except ValueError as err:
            notes.append("invalid measurement in %r (%s)" % (raw, err))
            continue
        except IndexError as err:
            notes.append("incomplete ingredient %r (%s)" % (raw, err))
            continue
        try:
            grams = amount * UNIT_GRAMS[unit]
        except KeyError as err:
            notes.append("unknown unit in %r (%s)" % (raw, err))
            continue
        try:
            macros = NUTRIENT_DB[name]
        except KeyError as err:
            notes.append("no database entry for %s (%s)" % (name, err))
            continue
        matched.append((grams, macros))
    return matched, notes


def calculate_calories(matched, recipe):
    totals = {'protein': 0.0, 'carbs': 0.0, 'fat': 0.0}
    notes = []
    for grams, macros in matched:
        for key in totals:
            totals[key] += grams * macros[key] / 100.0
    calories = totals['protein'] * 4 + totals['carbs'] * 4 + totals['fat'] * 9
    try:
        weights = [float(p) for p in recipe.get('portions', [])]
    except ValueError as err:
        notes.append("portion list holds text (%s)" % err)
        weights = []
    try:
        totals['avg_portion'] = round(sum(weights) / len(weights), 1)
    except ZeroDivisionError as err:
        notes.append("no portions recorded (%s)" % err)
        totals['avg_portion'] = 0.0
    try:
        servings = int(recipe.get('servings', 0))
    except ValueError as err:
        notes.append("serving count is not numeric (%s)" % err)
        servings = 0
    try:
        totals['per_serving'] = round(calories / servings, 1)
    except ZeroDivisionError as err:
        notes.append("cannot split %.0f kcal over 0 servings (%s)" % (calories, err))
        totals['per_serving'] = 0.0
    totals['calories'] = round(calories, 1)
    for key in ('protein', 'carbs', 'fat'):
        totals[key] = round(totals[key], 1)
    return totals, notes


def detect_allergens(recipe):
    found = []
    notes = []
    try:
        warnings = recipe['allergens']
    except KeyError as err:
        notes.append("allergen warnings absent (%s)" % err)
        return found, notes
    for flag in warnings:
        try:
            label = flag.strip().lower()
        except AttributeError as err:
            notes.append("allergen flag %r is not a label (%s)" % (flag, err))
            continue
        if label in KNOWN_ALLERGENS:
            found.append(label)
        else:
            notes.append("unrecognised allergen %s" % label)
    return found, notes


def analyze(recipes):
    results = []
    for recipe in recipes:
        try:
            title = recipe['name']
            matched, notes = match_ingredients(recipe)
        except KeyError as err:
            results.append("recipe structure error: missing field %s" % err)
            continue
        except TypeError as err:
            results.append("recipe structure error: %s" % err)
            continue
        totals, calorie_notes = calculate_calories(matched, recipe)
        allergens, allergen_notes = detect_allergens(recipe)
        totals['name'] = title
        totals['allergens'] = allergens
        totals['warnings'] = notes + calorie_notes + allergen_notes
        results.append(totals)
    return results


def main():
    recipes = [
        {'name': 'Porridge', 'ingredients': ['1 cup oats', '2 cup milk'],
         'portions': [250, 250], 'servings': 2, 'allergens': ['dairy']},
        {'name': 'Nut Bowl', 'ingredients': ['50 g peanut', 'lots g rice', '3 tbsp honey'],
         'portions': [], 'servings': 0, 'allergens': ['nuts', True]},
        {'ingredients': ['100 g chicken'], 'servings': 1},
        ['not', 'a', 'recipe'],
    ]
    for entry in analyze(recipes):
        if isinstance(entry, dict):
            print("%s: %.1f kcal (%.1f per serving)" % (
                entry['name'], entry['calories'], entry['per_serving']))
            print("  P %.1fg / C %.1fg / F %.1fg, avg portion %.1fg" % (
                entry['protein'], entry['carbs'], entry['fat'], entry['avg_portion']))
            print("  allergens: %s" % (", ".join(entry['allergens']) or "none"))
            for warning in entry['warnings']:
                print("  ! %s" % warning)
        else:
            print(entry)


if __name__ == '__main__':
    main()

