import math

BASE_PRICE_PER_SQM = 1800.0
REFERENCE_PRICE = 2000.0
WEAR_WEIGHT = 0.6

ZIP_RATES = {"10001": 1.35, "60614": 1.10, "77002": 0.92}
PRICE_HISTORY = {
    "10001": [2400.0, 2550.0, 2610.0],
    "60614": [2050.0, 1990.0],
    "77002": [],
}


def compute_area(prop):
    """Sum the floor areas given as [length, width] pairs."""
    try:
        floors = prop["dimensions"]
    except KeyError as err:
        print("missing dimension key %s; area treated as 0" % err)
        return 0.0
    total = 0.0
    for floor in floors:
        try:
            length = floor[0]
            width = floor[1]
        except IndexError as err:
            print("incomplete floor record (%s); skipped" % err)
            continue
        try:
            total += float(length) * float(width)
        except ValueError as err:
            print("bad dimension value: %s" % err)
    return total


def neighborhood_modifier(prop):
    zip_code = str(prop.get("zip", ""))
    try:
        rate = ZIP_RATES[zip_code]
    except KeyError as err:
        print("unknown zip code %s; using neutral rate" % err)
        rate = 1.0
    try:
        history = PRICE_HISTORY[zip_code]
        average = sum(history) / float(len(history))
    except KeyError as err:
        print("no price history for zip %s" % err)
        average = REFERENCE_PRICE
    except ZeroDivisionError as err:
        print("empty historical price list for %s (%s)" % (zip_code, err))
        average = REFERENCE_PRICE
    try:
        trend = math.sqrt(average / REFERENCE_PRICE)
    except ValueError as err:
        print("negative value anomaly in history of %s: %s" % (zip_code, err))
        trend = 1.0
    return rate * trend


def depreciation_factor(prop, current_year=2024):
    try:
        year = int(prop.get("year_built", current_year))
    except TypeError as err:
        print("invalid year type: %s" % err)
        year = current_year
    except ValueError as err:
        print("unparsable construction year: %s" % err)
        year = current_year
    age = current_year - year
    try:
        return 1.0 - min(WEAR_WEIGHT, WEAR_WEIGHT * (1.0 - 1.0 / age))
    except ZeroDivisionError as err:
        print("building age is zero, no wear applied (%s)" % err)
        return 1.0


def format_report(address, area, value):
    return "%-28s %8.1f sqm  %12.2f" % (address, area, value)


def appraise(properties):
    estimates = []
    for prop in properties:
        try:
            address = prop["address"]
        except KeyError as err:
            print("property without address field %s" % err)
            address = "<unlisted parcel>"
        area = compute_area(prop)
        value = area * BASE_PRICE_PER_SQM
        value *= neighborhood_modifier(prop)
        value *= depreciation_factor(prop)
        value = round(value, 2)
        estimates.append(value)
        print(format_report(address, area, value))
    return estimates


def main():
    portfolio = [
        {"address": "12 Willow St", "zip": "10001",
         "dimensions": [[10, 8], [10, 8]], "year_built": 1998},
        {"address": "44 Lake Dr", "zip": "60614",
         "dimensions": [[12, "9.5"], [12]], "year_built": "2024"},
        {"address": "8 Bayou Rd", "zip": "77002",
         "dimensions": [[15, 10]], "year_built": None},
        {"zip": "99999", "year_built": 1975},
    ]
    totals = appraise(portfolio)
    print("portfolio total: %.2f" % sum(totals))


if __name__ == "__main__":
    main()

