PORT_MAP = {20: "FTP", 22: "SSH", 25: "SMTP", 53: "DNS", 80: "HTTP", 443: "HTTPS"}


def parse_fields(raw):
    record = {}
    for token in raw.strip().split(";"):
        if not token:
            continue
        key, value = token.split("=")
        record[key.strip()] = value.strip()
    return record


def extract_ip(record):
    try:
        octets = [int(part) for part in record["src"].split(".")]
        return "%d.%d.%d.%d" % (octets[0], octets[1], octets[2], octets[3])
    except KeyError as err:
        print("network layer: record has no %s section" % err)
    except ValueError as err:
        print("network layer: bad address segment (%s)" % err)
    except IndexError as err:
        print("network layer: truncated address (%s)" % err)
    return None


def parse_port(token):
    port = int(token)
    if port < 0:
        raise ValueError("negative port %d" % port)
    return port


def identify_protocol(headers):
    try:
        return PORT_MAP[parse_port(headers[0])]
    except IndexError as err:
        print("transport layer: no headers to inspect (%s)" % err)
        return "UNKNOWN"
    except ValueError as err:
        print("transport layer: unusable port value (%s)" % err)
        return "UNKNOWN"
    except KeyError as err:
        return "PORT-%s" % err


def compute_bandwidth(byte_count, duration):
    try:
        total = float(byte_count)
    except TypeError as err:
        print("accounting: byte count of wrong type (%s)" % err)
        return None
    except ValueError as err:
        print("accounting: byte count not numeric (%s)" % err)
        return None
    try:
        return round(total / duration, 2)
    except ZeroDivisionError as err:
        print("accounting: zero duration, rate undefined (%s)" % err)
        return 0.0


def analyze(logs):
    results = []
    for index, raw in enumerate(logs):
        try:
            record = parse_fields(raw)
        except ValueError as err:
            print("log %d: unexpected record format (%s)" % (index, err))
            continue
        address = extract_ip(record)
        if address is None:
            continue
        headers = [tok for tok in record.get("hdr", "").split(",") if tok]
        try:
            duration = float(record["dur"])
        except KeyError as err:
            print("log %d: missing duration field %s" % (index, err))
            duration = 0.0
        except ValueError as err:
            print("log %d: duration not a number (%s)" % (index, err))
            duration = 0.0
        results.append({
            "source": address,
            "protocol": identify_protocol(headers),
            "duration": duration,
            "bandwidth": compute_bandwidth(record.get("bytes"), duration),
        })
    return results


def main():
    logs = [
        "src=192.168.1.10;hdr=443,SYN;bytes=2048;dur=1.6",
        "src=10.0.0.5;hdr=22,ACK;bytes=512;dur=0",
        "src=172.16.4;hdr=80;bytes=100;dur=2",
        "src=10.0.0.9;hdr=;bytes=64;dur=1",
        "src=10.0.0.11;hdr=-80,SYN;bytes=abc;dur=x",
        "src=8.8.8.8;hdr=9999;dur=4",
        "malformed line without separators",
    ]
    for entry in analyze(logs):
        print("%(source)s %(protocol)s %(duration)ss %(bandwidth)s B/s" % entry)


if __name__ == "__main__":
    main()

