import datetime

MAINTENANCE_INTERVALS = {"CNC-100": 90, "PRESS-200": 180, "LATHE-300": 365}


def check_temperature(machine):
    try:
        readings = machine["thermal"]["readings"]
    except KeyError as err:
        return "temperature data missing: %s" % err
    try:
        latest = readings[-1]
    except IndexError as err:
        return "no temperature samples: %s" % err
    try:
        celsius = float(latest)
    except (ValueError, TypeError) as err:
        return "unreadable temperature: %s" % err
    if celsius > 95.0:
        return "OVERHEATING at %.1fC" % celsius
    if celsius < 5.0:
        return "too cold at %.1fC" % celsius
    return "temperature normal at %.1fC" % celsius


def validate_speed(machine):
    rotations = machine.get("rotations", [])
    try:
        total = sum(float(r) for r in rotations)
    except ValueError as err:
        return "invalid rotation value: %s" % err
    try:
        average = total / len(rotations)
    except ZeroDivisionError as err:
        return "no rotation samples: %s" % err
    try:
        cycle_seconds = float(machine.get("cycle_seconds", 0))
        rate = average / cycle_seconds
    except ZeroDivisionError as err:
        return "cannot compute output rate: %s" % err
    except ValueError as err:
        return "invalid cycle time: %s" % err
    if rate > 50.0:
        return "speed too high (%.2f parts/s)" % rate
    return "speed nominal (%.2f parts/s)" % rate


def schedule_maintenance(machine, today):
    try:
        interval = MAINTENANCE_INTERVALS[machine["model"]]
    except KeyError as err:
        return "unknown model, cannot schedule: %s" % err
    try:
        last = datetime.datetime.strptime(machine.get("last_service", ""), "%Y-%m-%d").date()
    except ValueError as err:
        return "bad service date: %s" % err
    due = last + datetime.timedelta(days=interval)
    if due <= today:
        return "maintenance overdue since %s" % due.isoformat()
    return "next maintenance %s" % due.isoformat()


def monitor(machines):
    today = datetime.date.today()
    statuses = []
    for machine in machines:
        try:
            name = machine["id"]
        except (KeyError, TypeError) as err:
            statuses.append("unidentified machine skipped: %s" % err)
            continue
        parts = [check_temperature(machine),
                 validate_speed(machine),
                 schedule_maintenance(machine, today)]
        statuses.append("%s: %s" % (name, "; ".join(parts)))
    return statuses


def main():
    fleet = [
        {"id": "M1", "model": "CNC-100", "last_service": "2024-01-15",
         "thermal": {"readings": [70, 82, 91]}, "rotations": [1200, 1180], "cycle_seconds": 30},
        {"id": "M2", "model": "PRESS-200", "last_service": "15/01/2024",
         "thermal": {"readings": []}, "rotations": ["fast", 900], "cycle_seconds": 10},
        {"id": "M3", "model": "DRILL-999", "last_service": "2025-06-01",
         "thermal": {}, "rotations": [], "cycle_seconds": 0},
        {"model": "CNC-100"},
    ]
    for line in monitor(fleet):
        print(line)


if __name__ == "__main__":
    main()

