BOOK_DEPTH = {"AAPL": [190.4, 190.6, 190.8], "MSFT": [410.0, 410.5], "GOOG": []}
ACCOUNTS = {"alice": {"balance": 50000.0, "margin": 2.0}, "bob": {"balance": 1200.0, "margin": "none"}}


def validate_price(order):
    try:
        ticker = order["ticker"]
        base = MARKET_PRICES[ticker]
    except KeyError as err:
        return None, "unknown ticker %s" % (err,)

    depth = BOOK_DEPTH.get(ticker, [])
    try:
        best = depth[order.get("level", 0)]
    except IndexError as err:
        return None, "book level out of range: %s" % (err,)

    try:
        limit = float(order.get("limit", base))
    except ValueError as err:
        return None, "bad limit value: %s" % (err,)

    if limit < best:
        return None, "limit %.2f below best offer %.2f" % (limit, best)
    return best, None


def check_volume(order):
    ticker = order["ticker"]
    depth = BOOK_DEPTH.get(ticker, [])
    try:
        levels = len(depth)
        if levels == 0:
            raise LookupError("no resting orders for %s" % ticker)
    except LookupError as err:
        return None, "empty book: %s" % (err,)

    try:
        qty = int(order["quantity"])
        if qty <= 0:
            raise ArithmeticError("quantity %d is not positive" % qty)
    except ArithmeticError as err:
        return None, "volume constraint: %s" % (err,)

    try:
        avg = sum(depth) / levels
        per_level = qty / (levels - 1)
    except ZeroDivisionError as err:
        return None, "cannot spread fills: %s" % (err,)

    return (qty, avg, per_level), None


def verify_account(order, notional):
    try:
        account = ACCOUNTS[order["user"]]
        balance = account["balance"]
    except KeyError as err:
        return False, "no account data for %s" % (err,)

    try:
        buying_power = balance * float(account["margin"])
    except ValueError as err:
        return False, "margin requirement invalid: %s" % (err,)

    if buying_power < notional:
        return False, "insufficient buying power %.2f < %.2f" % (buying_power, notional)
    return True, None


def trade(orders):
    results = []
    for order in orders:
        try:
            oid = order["id"]
        except KeyError as err:
            results.append("rejected: missing order identifier (%s)" % (err,))
            continue

        price, error = validate_price(order)
        if error:
            results.append("%s rejected: %s" % (oid, error))
            continue

        volume, error = check_volume(order)
        if error:
            results.append("%s rejected: %s" % (oid, error))
            continue

        qty, avg, per_level = volume
        ok, error = verify_account(order, qty * price)
        if not ok:
            results.append("%s rejected: %s" % (oid, error))
            continue

        results.append("%s filled %d @ %.2f (avg book %.2f, %.2f per level)"
                       % (oid, qty, price, avg, per_level))
    return results


