ERAS = ["Prehistoric", "Ancient", "Medieval", "Early Modern", "Modern"]
REGIONS = {"EU": "Europe", "AS": "Asia", "AF": "Africa", "AM": "Americas"}


def date_artifact(artifact):
    notes = []
    try:
        era_index = artifact["era"]
    except KeyError as err:
        notes.append("era key missing: %s" % err)
        era_index = len(ERAS) - 1
    try:
        era_name = ERAS[era_index]
    except IndexError as err:
        notes.append("era index out of range: %s" % err)
        era_name = "Unclassified"
    except TypeError as err:
        notes.append("era index not usable: %s" % err)
        era_name = "Unclassified"
    try:
        year = int(artifact.get("year", ""))
    except ValueError as err:
        notes.append("year not an integer: %s" % err)
        year = None
    return {"era": era_name, "year": year, "dating_notes": notes}


def track_origin(artifact):
    notes = []
    try:
        region = REGIONS[artifact.get("region")]
    except KeyError as err:
        notes.append("unknown region code: %s" % err)
        region = "Unattributed"
    verified = artifact.get("verified")
    try:
        verified = verified.strip().lower() in ("yes", "true")
    except AttributeError as err:
        notes.append("verification flag not text: %s" % err)
        verified = bool(verified)
    coords = artifact.get("coordinates", [])
    try:
        site = (float(coords[0]), float(coords[1]))
    except IndexError as err:
        notes.append("coordinates incomplete: %s" % err)
        site = None
    except ValueError as err:
        notes.append("coordinates not numeric: %s" % err)
        site = None
    return {"region": region, "verified": verified, "site": site,
            "origin_notes": notes}


def score_preservation(artifact):
    notes = []
    damage = artifact.get("damage_points", 0)
    span = artifact.get("inspection_years", 0)
    try:
        rate = float(damage) / span
    except ZeroDivisionError as err:
        notes.append("degradation rate undefined: %s" % err)
        rate = 0.0
    try:
        condition = artifact["material"] + "/" + artifact.get("condition", "")
    except TypeError as err:
        notes.append("material condition malformed: %s" % err)
        condition = "unknown"
    score = max(0.0, 100.0 - rate * 10.0)
    return {"condition": condition, "degradation_rate": round(rate, 3),
            "score": round(score, 2), "preservation_notes": notes}


def catalog(artifacts):
    entries = []
    for artifact in artifacts:
        try:
            reg = artifact["registration"]
        except KeyError as err:
            reg = "PENDING-%d" % (len(entries) + 1)
            print("missing registration number (%s), assigned %s" % (err, reg))
        entry = {"registration": reg}
        entry.update(date_artifact(artifact))
        entry.update(track_origin(artifact))
        entry.update(score_preservation(artifact))
        entries.append(entry)
    return entries


def main():
    records = [
        {"registration": "A-1", "era": 2, "year": "1450", "region": "EU",
         "verified": "yes", "coordinates": [48.85, 2.35], "material": "stone",
         "condition": "stable", "damage_points": 12, "inspection_years": 4},
        {"era": 9, "year": "circa 700", "region": "ZZ", "verified": 1,
         "coordinates": [], "material": None, "damage_points": 5,
         "inspection_years": 0},
    ]
    for entry in catalog(records):
        print("%s | %s | %s | score %s" % (entry["registration"], entry["era"],
                                           entry["region"], entry["score"]))


if __name__ == "__main__":
    main()

