import math

STATIONS = {"A1": "Central", "B2": "Harbor", "C3": "Airport", "D4": "Museum"}


def stop_distance(stops, i, j):
    try:
        first = stops[i]
        second = stops[j]
    except IndexError as err:
        print("stop index out of bounds: %s" % err)
        return 0.0
    try:
        lat1 = float(first["lat"])
        lon1 = float(first["lon"])
        lat2 = float(second["lat"])
        lon2 = float(second["lon"])
    except KeyError as err:
        print("missing stop coordinate: %s" % err)
        return 0.0
    except ValueError as err:
        print("invalid coordinate value: %s" % err)
        return 0.0
    return math.sqrt((lat1 - lat2) ** 2 + (lon1 - lon2) ** 2) * 111.0


def route_length(stops):
    total = 0.0
    for i in range(len(stops) - 1):
        total += stop_distance(stops, i, i + 1)
    return total


def travel_time(distance, traffic):
    try:
        average = sum(traffic) / float(len(traffic))
    except ZeroDivisionError as err:
        print("empty traffic data array: %s" % err)
        return distance / 30.0 * 60.0
    except TypeError as err:
        print("unusable traffic sample: %s" % err)
        return distance / 30.0 * 60.0
    if average < 0:
        print("unexpected negative traffic speed: %.2f" % average)
        average = abs(average)
    try:
        hours = distance / average
    except ZeroDivisionError as err:
        print("average speed is zero: %s" % err)
        return float("inf")
    return hours * 60.0


def transfer_penalty(transfers, loads):
    penalty = 0.0
    for code in transfers:
        try:
            name = STATIONS[code]
        except KeyError as err:
            print("unknown station code: %s" % err)
            continue
        try:
            load = float(loads.get(code, 0))
        except ValueError as err:
            print("passenger load for %s is not numeric: %s" % (name, err))
            continue
        penalty += 2.0 + load / 100.0
    return penalty


def plan(routes):
    times = []
    for route in routes:
        try:
            name = route["id"]
        except KeyError as err:
            print("skipping route with missing identifier: %s" % err)
            continue
        stops = route.get("stops", [])
        minutes = travel_time(route_length(stops), route.get("traffic", []))
        minutes += transfer_penalty(route.get("transfers", []), route.get("loads", {}))
        print("route %s planned at %.2f minutes" % (name, minutes))
        times.append(round(minutes, 2))
    return times

