ROW_SEATS = {"A": 8, "B": 10, "C": 12}
BRANDS = {"3": "AMEX", "4": "VISA", "5": "MASTERCARD"}
PROMOS = {"NONE": 0.0, "STUDENT": 0.15, "MATINEE": 0.25}


def build_house():
    house = {}
    for row in ROW_SEATS:
        house[row] = [False] * ROW_SEATS[row]
    return house


def select_seat(house, req):
    try:
        row = str(req["row"]).upper()
    except KeyError, err:
        return None, "no row given (%s)" % err
    try:
        seat_no = int(req.get("seat", ""))
    except ValueError, err:
        return None, "invalid seat number (%s)" % err
    try:
        seats = house[row]
        occupied = seats[seat_no - 1]
    except KeyError, err:
        return None, "unknown row %s" % err
    except IndexError, err:
        return None, "seat out of range (%s)" % err
    if occupied:
        return None, "seat %s%d already taken" % (row, seat_no)
    seats[seat_no - 1] = True
    return (row, seat_no), None


def parse_price(req):
    try:
        return float(req.get("price", 0)), None
    except ValueError, err:
        return None, "unreadable ticket price (%s)" % err


def apply_discount(price, req):
    code = str(req.get("promo", "NONE")).upper()
    try:
        rate = PROMOS[code]
    except KeyError, err:
        return price, "unknown promo code %s" % err
    try:
        member_off = price * 0.02 * req.get("level", 0)
    except TypeError, err:
        return price * (1.0 - rate), "membership level ignored (%s)" % err
    return price * (1.0 - rate) - member_off, None


def charge(card, amount):
    if amount < 0:
        raise ValueError("negative amount %.2f" % amount)
    return "%s/%s" % (card[-4:], "%.2f" % amount)


def process_payment(req, amount):
    card = str(req.get("card", "")).strip()
    try:
        brand = BRANDS[card[0]]
    except IndexError, err:
        return None, "empty credit card string (%s)" % err
    except KeyError, err:
        return None, "unsupported card brand %s" % err
    try:
        receipt = charge(card, amount)
    except ValueError, err:
        return None, "payment refused: %s" % err
    try:
        share = amount / float(req.get("split", 1))
    except ZeroDivisionError, err:
        return None, "cannot split the bill among zero friends (%s)" % err
    return (brand, receipt, share), None


def book(requests):
    house = build_house()
    confirmations = []
    for index, req in enumerate(requests):
        try:
            title = req["title"]
        except KeyError, err:
            confirmations.append("Request %d rejected: missing movie title (%s)" % (index, err))
            continue
        seat, problem = select_seat(house, req)
        if problem is not None:
            confirmations.append("Request %d rejected: %s" % (index, problem))
            continue
        price, problem = parse_price(req)
        if problem is not None:
            confirmations.append("Request %d rejected: %s" % (index, problem))
            continue
        price, note = apply_discount(price, req)
        payment, problem = process_payment(req, price)
        if problem is not None:
            confirmations.append("Request %d rejected: %s" % (index, problem))
            continue
        line = "Request %d confirmed: %s seat %s%d, %s %s, %.2f each" % (
            index, title, seat[0], seat[1], payment[0], payment[1], payment[2])
        if note is not None:
            line = line + " [%s]" % note
        confirmations.append(line)
    return confirmations


def main():
    orders = [
        {"title": "Dune", "row": "b", "seat": "4", "price": "24.00",
         "promo": "STUDENT", "level": 3, "card": "4111111111111111", "split": 2},
        {"row": "A", "seat": "1", "price": 10, "card": "5500000000000004"},
        {"title": "Alien", "row": "C", "seat": "99", "price": 12, "card": "4000"},
        {"title": "Heat", "row": "A", "seat": "two", "price": 12, "card": "4000"},
        {"title": "Solaris", "row": "A", "seat": "2", "price": 18,
         "promo": "VIP", "card": "", "split": 1},
        {"title": "Ran", "row": "A", "seat": "3", "price": 18,
         "level": "gold", "card": "4242424242424242", "split": 0},
    ]
    for line in book(orders):
        print(line)


if __name__ == "__main__":
    main()

