CROP_TABLE = {"maize": 5.8, "wheat": 3.2, "rice": 4.5, "soy": 2.7}
DEFAULT_YIELD = 2.5


def rainfall_index(weather):
    try:
        readings = weather["precipitation"]
    except KeyError as err:
        print("rainfall: no precipitation series (%s), assuming dry season" % err)
        return 0.55
    total = 0.0
    for value in readings:
        try:
            total += float(value)
        except ValueError as err:
            print("rainfall: discarding unreadable value (%s)" % err)
    try:
        peak = float(readings[5])
    except IndexError as err:
        print("rainfall: short series (%s), using average month" % err)
        peak = total / max(len(readings), 1)
    except ValueError as err:
        print("rainfall: peak month unreadable (%s)" % err)
        peak = total / max(len(readings), 1)
    return min(1.4, total / 900.0 + peak / 600.0)


def soil_quality(soil):
    minerals = soil.get("minerals", [])
    try:
        average = sum(minerals) / float(len(minerals))
    except ZeroDivisionError as err:
        print("soil: mineral array is empty (%s), using reference soil" % err)
        average = 40.0
    except TypeError as err:
        print("soil: textual mineral entry (%s), keeping numbers only" % err)
        numbers = [m for m in minerals if isinstance(m, (int, float))]
        average = sum(numbers) / float(len(numbers)) if numbers else 40.0
    try:
        ratio = float(soil.get("nitrogen", 0)) / float(soil.get("potassium", 0))
    except ZeroDivisionError as err:
        print("soil: potassium is zero (%s), ratio clamped" % err)
        ratio = 1.0
    except ValueError as err:
        print("soil: nutrient level is not numeric (%s), ratio clamped" % err)
        ratio = 1.0
    return (average / 50.0) * (0.8 + min(ratio, 2.0) / 5.0)


def seed_factor(farm):
    try:
        base = CROP_TABLE[farm.get("crop")]
    except KeyError as err:
        print("seed: unknown crop %s, falling back to generic seed" % err)
        base = DEFAULT_YIELD
    try:
        month = int(farm.get("planted")[5:7])
    except TypeError as err:
        print("seed: planting date is not a date string (%s)" % err)
        month = 4
    except ValueError as err:
        print("seed: planting month unparsable (%s)" % err)
        month = 4
    return base * (1.0 if 3 <= month <= 6 else 0.85)


def estimate(farms):
    predictions = []
    for farm in farms:
        try:
            name = farm["name"]
        except KeyError as err:
            print("orchestrator: skipping record without farm name (%s)" % err)
            continue
        tons = seed_factor(farm) * rainfall_index(farm.get("weather", {}))
        tons *= soil_quality(farm.get("soil", {}))
        predictions.append({"name": name, "crop": farm.get("crop", "unknown"),
                            "yield": round(tons, 2)})
    return predictions


if __name__ == "__main__":
    FARMS = [
        {"name": "Hillside", "crop": "maize", "planted": "2024-04-12",
         "weather": {"precipitation": [40, 60, 90, 120, 150, 180, 90]},
         "soil": {"minerals": [45, 52, 38], "nitrogen": 30, "potassium": 20}},
        {"name": "Riverbend", "crop": "rice", "planted": 20240301,
         "weather": {"precipitation": [80, "n/a", 110, 160]},
         "soil": {"minerals": [], "nitrogen": "high", "potassium": 0}},
        {"name": "Dry Acres", "crop": "quinoa", "planted": "2024-xx-09",
         "weather": {},
         "soil": {"minerals": [30, "clay", 44], "nitrogen": 18, "potassium": 0}},
        {"crop": "wheat", "planted": "2024-05-02", "weather": {}, "soil": {}},
    ]
    for row in estimate(FARMS):
        print("%-12s %-8s %6.2f t/ha" % (row["name"], row["crop"], row["yield"]))

