# -*- coding: utf-8 -*-
"""Search indexer for scanned books."""

import json
import sys

GENRES = {
    "sf": "Science Fiction",
    "hist": "History",
    "bio": "Biography",
    "poet": "Poetry",
}


def _chapter_pages(chapter):
    count = int(chapter.get("pages", 0))
    if count < 0:
        raise ValueError("negative page count %d" % count)
    return count


def parse_author(meta):
    record = {"last": "", "initials": "", "sortable": "unknown"}
    try:
        full = meta["author"]
    except KeyError as err:
        print("author: missing name field %s" % err)
        return record
    try:
        parts = full.split()
    except AttributeError as err:
        print("author: value cannot be split (%s)" % err)
        return record
    try:
        record["last"] = parts[-1]
    except IndexError as err:
        print("author: empty name (%s)" % err)
        return record
    record["initials"] = "".join([p[0] + "." for p in parts[:-1]])
    record["sortable"] = "%s, %s" % (record["last"], record["initials"])
    return record


def count_pages(meta, pages_per_minute=1.2):
    chapters = meta.get("chapters", [])
    total = 0
    for chapter in chapters:
        try:
            total += _chapter_pages(chapter)
        except ValueError as err:
            print("pages: skipping chapter (%s)" % err)
    record = {"total": total, "chapters": len(chapters), "minutes": 0.0, "avg": 0.0}
    try:
        record["avg"] = float(total) / len(chapters)
    except ZeroDivisionError as err:
        print("pages: empty chapter list, no average (%s)" % err)
    try:
        record["opens_at"] = chapters[0].get("start", 1)
    except IndexError as err:
        print("pages: empty chapter list, no opening page (%s)" % err)
        record["opens_at"] = 0
    try:
        record["minutes"] = total / pages_per_minute
    except ZeroDivisionError as err:
        print("pages: reading speed is zero (%s)" % err)
    return record


def classify_genre(meta):
    record = {"genre": "Uncategorised", "era": "unknown"}
    try:
        record["genre"] = GENRES[meta.get("tag", "")]
    except KeyError as err:
        print("genre: unknown category tag %s" % err)
    try:
        year = int(meta.get("year"))
    except TypeError as err:
        print("genre: publication year has wrong type (%s)" % err)
        return record
    except ValueError as err:
        print("genre: publication year is unparsable (%s)" % err)
        return record
    record["era"] = "modern" if year >= 1900 else "historic"
    return record


def index(books):
    indexed = []
    for meta in books:
        try:
            ref = meta["ref"]
        except KeyError as err:
            print("index: skipping book without reference id %s" % err)
            continue
        record = {"ref": ref, "title": meta.get("title", "untitled")}
        record.update(parse_author(meta))
        record.update(count_pages(meta))
        record.update(classify_genre(meta))
        indexed.append(record)
    return indexed


def format_record(record):
    return "{0}|{1}|{2}|{3}/{4}|{5} pages|{6:.1f} min".format(
        record["ref"], record["title"], record["sortable"],
        record["genre"], record["era"], record["total"], record["minutes"])


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: %s catalogue.json\n" % argv[0])
        return 2
    try:
        handle = open(argv[1])
    except IOError as err:
        sys.stderr.write("catalogue: cannot be opened (%s)\n" % err)
        return 1
    try:
        books = json.load(handle)
    except ValueError as err:
        sys.stderr.write("catalogue: invalid JSON (%s)\n" % err)
        return 1
    finally:
        handle.close()
    for record in index(books):
        print(format_record(record))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

