def solar_input(sector):
    try:
        hours = sector["sunlight_hours"]
    except KeyError, err:
        print("solar: no sunlight data for key %s" % err)
        return 0.0
    try:
        midday = float(hours[2])
    except IndexError, err:
        print("solar: sunlight series too short (%s)" % err)
        return 0.0
    except ValueError, err:
        print("solar: unreadable sunlight value (%s)" % err)
        return 0.0
    return round(midday * sector.get("panels", 0) * 0.25, 2)


def wind_power(sector):
    turbines = sector.get("turbines", [])
    try:
        peak = max(turbines)
    except ValueError, err:
        print("wind: no turbines listed (%s)" % err)
        return 0.0
    try:
        factor = math.sqrt(sector.get("efficiency", 0.0))
    except ValueError, err:
        print("wind: efficiency out of range (%s)" % err)
        return 0.0
    try:
        drop = float(sector.get("losses", 0.0)) / sector.get("span_km", 0)
    except ZeroDivisionError, err:
        print("wind: span unknown, capacity drop ignored (%s)" % err)
        drop = 0.0
    return round(peak * len(turbines) * factor * (1.0 - min(drop, 0.9)), 2)


def storage_manager(sector):
    model = sector.get("battery", "")
    try:
        retention = BATTERY_MODELS[model]
    except KeyError, err:
        print("storage: unknown battery model %s" % err)
        return 0.0
    try:
        usable = float(sector.get("discharge_rate")) * sector.get("capacity_kwh", 0)
    except TypeError, err:
        print("storage: bad discharge rate (%s)" % err)
        return 0.0
    return round(usable * retention, 2)


def parse_demand(sector):
    try:
        raw = sector["demand_kw"]
    except KeyError, err:
        print("demand: field %s absent, assuming zero load" % err)
        return 0.0
    try:
        return float(raw)
    except ValueError, err:
        print("demand: cannot read load (%s)" % err)
        return 0.0


def format_summary(name, solar, wind, storage, demand):
    supply = solar + wind + storage
    balance_kw = round(supply - demand, 2)
    state = "surplus" if balance_kw >= 0 else "deficit"
    return "%s: solar=%.2f wind=%.2f storage=%.2f demand=%.2f %s=%.2f" % (
        name, solar, wind, storage, demand, state, abs(balance_kw))


def balance(sectors):
    summaries = []
    for index, sector in enumerate(sectors):
        try:
            name = sector["name"]
        except KeyError, err:
            print("grid: sector %d has no name (%s)" % (index, err))
            name = "unnamed-%d" % index
        summaries.append(format_summary(name, solar_input(sector),
                                        wind_power(sector),
                                        storage_manager(sector),
                                        parse_demand(sector)))
    return summaries


if __name__ == "__main__":
    grid = [
        {"name": "harbour", "sunlight_hours": [1.0, 3.5, 6.2, 4.0],
         "panels": 400, "turbines": [850, 900, 780], "efficiency": 0.81,
         "losses": 4.5, "span_km": 30, "battery": "lifepo4",
         "discharge_rate": 120, "capacity_kwh": 50, "demand_kw": "9500"},
        {"name": "old town", "sunlight_hours": [0.5, 2.0], "panels": 120,
         "turbines": [], "efficiency": -0.2, "losses": 2.0, "span_km": 0,
         "battery": "flow", "discharge_rate": None, "capacity_kwh": 10,
         "demand_kw": "n/a"},
        {"panels": 90, "turbines": [400], "efficiency": 0.64, "losses": 1.2,
         "span_km": 12, "battery": "nmc", "discharge_rate": "45",
         "capacity_kwh": 20},
    ]
    for line in balance(grid):
        print(line)

