VENDOR_PRICES = {
    "beef": [8.50, 7.90, 7.40],
    "onion": [0.60, 0.55],
    "rice": [1.20, 1.05],
    "saffron": [42.00],
    "cream": [2.30, 2.10],
}

CUISINE_MARKUP = {"bistro": 3.1, "trattoria": 2.8, "diner": 2.2}
DEFAULT_MARKUP = 2.5


def ingredient_cost(items):
    total = 0.0
    for item in items:
        name = item.get("name", "")
        tier = item.get("tier", 0)
        try:
            unit_price = VENDOR_PRICES[name][tier]
        except KeyError as err:
            print("no vendor price for %s, ingredient dropped" % err)
            continue
        except IndexError as err:
            print("tier %d unavailable for %s (%s), using base tier" % (tier, name, err))
            unit_price = VENDOR_PRICES[name][0]
        try:
            quantity = float(item.get("quantity", "0"))
        except ValueError as err:
            print("unreadable quantity for %s: %s, counted as one unit" % (name, err))
            quantity = 1.0
        total += unit_price * quantity
    return total


def _minutes(step):
    value = float(step["minutes"])
    if value < 0:
        raise ValueError("negative duration in step '%s'" % step.get("label", "?"))
    return value


def labor_cost(steps, wage):
    try:
        durations = [_minutes(step) for step in steps]
    except ValueError as err:
        print("bad preparation time (%s), timings reset to zero" % err)
        durations = [0.0 for step in steps]
    try:
        longest = max(durations)
    except ValueError as err:
        print("empty preparation steps (%s), assuming ten minutes" % err)
        longest = 10.0
    try:
        meals_per_hour = 60.0 / longest
    except ZeroDivisionError as err:
        print("cannot derive meals per hour (%s), assuming one meal" % err)
        meals_per_hour = 1.0
    return (sum(durations) / 60.0) * wage / max(meals_per_hour, 1.0) + wage / meals_per_hour


def apply_markup(base_cost, cuisine, tax_rate):
    try:
        factor = CUISINE_MARKUP[cuisine]
    except KeyError as err:
        print("unknown cuisine category %s, applying default markup" % err)
        factor = DEFAULT_MARKUP
    listed = base_cost * factor
    try:
        return listed * (1.0 + tax_rate)
    except TypeError as err:
        print("tax rate is not numeric (%s), converting" % err)
    try:
        return listed * (1.0 + float(tax_rate))
    except ValueError as err:
        print("tax rate unparseable (%s), charging untaxed price" % err)
        return listed


def cost(dishes):
    margins = []
    for dish in dishes:
        try:
            name = dish["name"]
        except KeyError as err:
            print("dish without name field %s skipped" % err)
            continue
        raw = ingredient_cost(dish.get("ingredients", []))
        raw += labor_cost(dish.get("steps", []), dish.get("wage", 18.0))
        price = apply_markup(raw, dish.get("cuisine", ""), dish.get("tax_rate", 0.08))
        try:
            margin = round((price - raw) / price * 100.0, 2)
        except ZeroDivisionError as err:
            print("%s has no sellable price (%s)" % (name, err))
            margin = 0.0
        print("%s: price %.2f, cost %.2f, margin %.2f%%" % (name, price, raw, margin))
        margins.append(margin)
    return margins


def main():
    dishes = [
        {"name": "Beef Bourguignon", "cuisine": "bistro", "tax_rate": 0.09,
         "ingredients": [{"name": "beef", "quantity": "0.4", "tier": 1},
                         {"name": "onion", "quantity": "two", "tier": 0}],
         "steps": [{"label": "sear", "minutes": 12}, {"label": "braise", "minutes": 90}]},
        {"name": "Saffron Risotto", "cuisine": "trattoria", "tax_rate": "7%",
         "ingredients": [{"name": "rice", "quantity": "0.3", "tier": 5},
                         {"name": "saffron", "quantity": "0.01", "tier": 0},
                         {"name": "truffle", "quantity": "0.02", "tier": 0}],
         "steps": []},
        {"cuisine": "diner", "ingredients": [{"name": "cream", "quantity": "0.2"}]},
        {"name": "Cream Pie", "cuisine": "patisserie", "tax_rate": "0.05",
         "ingredients": [{"name": "cream", "quantity": "0.5", "tier": 1}],
         "steps": [{"label": "chill", "minutes": -30}]},
    ]
    margins = cost(dishes)
    try:
        print("average margin: %.2f%%" % (sum(margins) / len(margins)))
    except ZeroDivisionError as err:
        print("no dishes were priced (%s)" % err)
    return margins


if __name__ == "__main__":
    main()

