TERRAIN = {
    "F": "forest",
    "G": "grassland",
    "W": "wetland",
    "D": "desert",
    "T": "tundra",
}


def parse_location(record):
    points = record.get("points", [])
    try:
        raw = points[0]
    except IndexError as err:
        return None, "no fix available (%s)" % err
    try:
        lat = float(raw["lat"])
    except KeyError as err:
        return None, "missing latitude key %s" % err
    except ValueError as err:
        return None, "invalid latitude (%s)" % err
    try:
        lon = float(raw.get("lon", 0.0))
    except ValueError as err:
        return None, "invalid longitude (%s)" % err
    return (lat, lon), None


def time_span(stamps):
    start = float(stamps[0])
    end = float(stamps[-1])
    span = end - start
    if span < 0:
        raise ValueError("collar clock ran backwards by %.1f s" % -span)
    return span


def compute_speed(record):
    try:
        distance = float(record.get("distance", 0.0))
    except ValueError as err:
        return None, "invalid distance (%s)" % err
    try:
        span = time_span(record.get("timestamps", []))
    except IndexError as err:
        return None, "empty timestamp list (%s)" % err
    except ValueError as err:
        return None, "time anomaly: %s" % err
    try:
        return distance / span * 3.6, None
    except ZeroDivisionError as err:
        return None, "zero time difference (%s)" % err


def match_habitat(record):
    try:
        habitat = TERRAIN[record.get("terrain")]
    except KeyError as err:
        return "unclassified", "unknown terrain code %s" % err
    try:
        elevation = int(record.get("elevation"))
    except TypeError as err:
        return habitat, "elevation unavailable (%s)" % err
    except ValueError as err:
        return habitat, "elevation not numeric (%s)" % err
    if elevation > 2000:
        habitat = "alpine " + habitat
    return habitat, None


def track(animals):
    summaries = []
    for record in animals:
        notes = []
        try:
            tag = record["id"]
        except KeyError as err:
            summaries.append({"id": None, "notes": ["missing identifier %s" % err]})
            continue
        location, note = parse_location(record)
        if note:
            notes.append(note)
        speed, note = compute_speed(record)
        if note:
            notes.append(note)
        habitat, note = match_habitat(record)
        if note:
            notes.append(note)
        summaries.append({"id": tag, "location": location,
                          "speed_kmh": speed, "habitat": habitat,
                          "notes": notes})
    return summaries


def format_summary(summary):
    line = "%s: habitat=%s" % (summary["id"] or "<unknown>", summary.get("habitat", "n/a"))
    if summary.get("speed_kmh") is not None:
        line += " speed=%.2f km/h" % summary["speed_kmh"]
    if summary.get("location"):
        line += " at (%.4f, %.4f)" % summary["location"]
    if summary["notes"]:
        line += " | " + "; ".join(summary["notes"])
    return line


def main():
    feed = [
        {"id": "elk-01", "points": [{"lat": "45.2", "lon": "-110.4"}],
         "timestamps": [100, 3700], "distance": 5400, "terrain": "F", "elevation": 2400},
        {"id": "wolf-07", "points": [{"lon": "-111.0"}],
         "timestamps": [], "distance": 200, "terrain": "Z", "elevation": 1500},
        {"id": "hare-12", "points": [], "timestamps": [900, 900],
         "distance": 30, "terrain": "G", "elevation": None},
        {"points": [{"lat": "44.0", "lon": "-112.0"}], "timestamps": [500, 200],
         "distance": "far", "terrain": "W", "elevation": "low"},
    ]
    for summary in track(feed):
        print(format_summary(summary))


if __name__ == "__main__":
    main()

