import json
import math

TEAM_SIZE = 2

REGIONS = {
    'na': 'NA-EAST',
    'eu': 'EU-WEST',
    'ap': 'AP-SOUTH',
    'sa': 'SA-EAST',
}


def skill_score(player):
    try:
        wins = player['wins']
    except KeyError as err:
        print('no win record for entry (key %s), assuming 0 wins' % err)
        wins = 0
    try:
        placement = player.get('history', [])[-1]
    except IndexError as err:
        print('empty match history (%s), using neutral placement' % err)
        placement = 3
    try:
        matches = int(player['matches'])
    except ValueError as err:
        print('unreadable match count (%s), assuming a single match' % err)
        matches = 1
    winrate = (100 * wins) // max(matches, 1)
    return winrate + max(0, 6 - placement) * 5


def latency_score(player):
    pings = player.get('pings', [])
    try:
        peak = max(pings)
    except ValueError as err:
        print('no ping samples recorded (%s), scoring latency as poor' % err)
        return 0
    try:
        average = float(sum(pings)) / int(player.get('probes', len(pings)))
    except ZeroDivisionError as err:
        print('probe counter is zero (%s), falling back to peak ping' % err)
        average = float(peak)
    try:
        stability = math.log(average)
    except ValueError as err:
        print('negative ping anomaly in %r (%s), scoring latency as poor' % (pings, err))
        return 0
    return max(0, int(120 - average - 5 * stability))


def region_bucket(player):
    try:
        server = REGIONS[player.get('region')]
    except KeyError as err:
        print('unknown server location %s, routing to NA-EAST' % err)
        server = 'NA-EAST'
    try:
        bonus = 5 * int(player.get('premium', 0))
    except TypeError as err:
        print('invalid premium status (%s), no priority bonus' % err)
        bonus = 0
    return server, bonus


def match(players):
    queues = {}
    for player in players:
        try:
            handle = player['handle']
        except KeyError as err:
            print('dropping queue entry without a handle (key %s)' % err)
            continue
        server, bonus = region_bucket(player)
        rating = skill_score(player) + latency_score(player) + bonus
        queues.setdefault(server, []).append((rating, handle))
    teams = []
    for server in sorted(queues):
        waiting = sorted(queues[server], reverse=True)
        while len(waiting) >= TEAM_SIZE:
            squad = waiting[:TEAM_SIZE]
            waiting = waiting[TEAM_SIZE:]
            total = sum([rating for rating, handle in squad])
            teams.append({
                'server': server,
                'players': [handle for rating, handle in squad],
                'rating': total // TEAM_SIZE,
            })
    return teams


def load_queue(text):
    try:
        return json.loads(text)
    except ValueError as err:
        print('queue payload is not valid JSON (%s), starting empty' % err)
        return []


def format_report(teams):
    lines = []
    for team in teams:
        lines.append('{0}: {1} (avg rating {2})'.format(
            team['server'], ' + '.join(team['players']), team['rating']))
    return '\n'.join(lines)


def main():
    payload = """[
        {"handle": "Vex", "region": "eu", "wins": 40, "matches": "80",
         "history": [1, 2], "pings": [22, 30], "probes": 2, "premium": 1},
        {"handle": "Nova", "region": "eu", "wins": 12, "matches": "many",
         "history": [], "pings": [40, 55], "probes": 0, "premium": [true]},
