MARKERS = {
    "16S": "Escherichia coli",
    "COI": "Homo sapiens",
    "rbcL": "Zea mays",
}


def parse_limit(raw):
    limit = int(raw)
    if limit < 0:
        raise ValueError("negative mutation limit %d" % limit)
    return limit


def count_bases(sample):
    counts = {"A": 0, "C": 0, "G": 0, "T": 0}
    issues = []
    try:
        sequence = sample["sequence"]
    except KeyError as err:
        issues.append("missing sequence string for key %s" % err)
        return {"counts": counts, "text": "", "issues": issues}
    try:
        text = sequence.decode("ascii")
    except AttributeError:
        text = sequence
    except UnicodeDecodeError as err:
        issues.append("invalid character encoding: %s" % err)
        text = sequence.decode("ascii", "ignore")
    start = int(sample.get("start", 0))
    try:
        text[start]
    except IndexError as err:
        issues.append("start offset %d out of bounds: %s" % (start, err))
        start = 0
    for base in text[start:].upper():
        try:
            counts[base] += 1
        except KeyError as err:
            issues.append("unrecognised base %s" % err)
    return {"counts": counts, "text": text[start:].upper(), "issues": issues}


def detect_mutations(sample, text):
    issues = []
    result = {"mutations": [], "frequency": 0.0, "issues": issues}
    try:
        limit = parse_limit(sample.get("max_mutations", 0))
    except ValueError as err:
        issues.append("invalid mutation constraint: %s" % err)
        limit = 0
    reference = sample.get("reference", [])
    try:
        result["reference_start"] = reference[0]
    except IndexError as err:
        issues.append("empty reference array: %s" % err)
        return result
    compared = min(len(reference), len(text))
    for position in range(compared):
        if reference[position] != text[position]:
            result["mutations"].append(position)
    if limit:
        result["mutations"] = result["mutations"][:limit]
    try:
        result["frequency"] = len(result["mutations"]) / float(compared)
    except ZeroDivisionError as err:
        issues.append("cannot compute mutation frequency: %s" % err)
    return result


def match_species(sample, counts):
    issues = []
    try:
        species = MARKERS[sample.get("marker")]
    except KeyError as err:
        issues.append("unknown genetic marker %s" % err)
        species = "unclassified"
    try:
        confidence = float(sample.get("confidence"))
    except (TypeError, ValueError) as err:
        issues.append("invalid confidence score: %s" % err)
        confidence = 0.0
    total = sum(counts.values())
    if total:
        gc = (counts["G"] + counts["C"]) / float(total)
        confidence = round(confidence * (0.5 + gc / 2.0), 4)
    return {"species": species, "confidence": confidence, "issues": issues}


def align(samples):
    results = []
    for sample in samples:
        try:
            name = sample["identifier"]
        except KeyError as err:
            results.append({"identifier": None,
                            "issues": ["missing sample identifier %s" % err]})
            continue
        bases = count_bases(sample)
        mutations = detect_mutations(sample, bases["text"])
        match = match_species(sample, bases["counts"])
        results.append({
            "identifier": name,
            "counts": bases["counts"],
            "mutations": mutations["mutations"],
            "frequency": mutations["frequency"],
            "species": match["species"],
            "confidence": match["confidence"],
            "issues": bases["issues"] + mutations["issues"] + match["issues"],
        })
    return results

