import math

DEFAULT_LEVELS = [50.0, 100.0]
RESTRICTION_ZONES = {
    "downtown": [90.0, 120.0, 150.0],
    "harbor": [60.0, 80.0],
    "suburb": [110.0, 140.0, 180.0],
}
CORRIDOR_LIMITS = {"A1": 4.5, "B2": 7.0, "C3": 2.0}
FALLBACK_LIMIT = 3.0


def plan_altitude(plan):
    try:
        levels = RESTRICTION_ZONES[plan["zone"]]
    except KeyError as err:
        print("altitude: unknown restriction zone %s, using default" % err)
        levels = DEFAULT_LEVELS
    try:
        ceiling = levels[plan.get("tier", 0)]
    except IndexError as err:
        print("altitude: tier out of bounds (%s), clamping to top level" % err)
        ceiling = levels[-1]
    try:
        requested = float(plan.get("height", ceiling))
    except ValueError as err:
        print("altitude: bad height value (%s), using half ceiling" % err)
        requested = ceiling / 2.0
    return min(requested, ceiling)


def project_battery(plan, altitude):
    winds = plan.get("wind_resistance", [])
    try:
        peak = max(winds)
    except ValueError as err:
        print("battery: no wind samples (%s), assuming calm air" % err)
        peak = 0.0
    try:
        efficiency = math.sqrt(plan.get("power_draw", 0.0))
    except ValueError as err:
        print("battery: negative power anomaly (%s), ignoring draw" % err)
        efficiency = 0.0
    drain = altitude * 0.05 + peak * 1.5 + efficiency * 4.0
    try:
        rate = drain / plan.get("duration_min", 0)
    except ZeroDivisionError as err:
        print("battery: zero duration (%s), rate equals total drain" % err)
        rate = drain
    return max(0.0, 100.0 - drain), rate


def check_clearance(plan, reserve):
    try:
        limit = CORRIDOR_LIMITS[plan["corridor"]]
    except KeyError as err:
        print("clearance: unknown corridor code %s" % err)
        limit = FALLBACK_LIMIT
    try:
        margin = limit - plan.get("payload_kg", 0)
    except TypeError as err:
        print("clearance: payload weight not numeric (%s)" % err)
        margin = limit
    return margin >= 0 and reserve >= 20.0, margin


def parse_window(plan):
    text = plan.get("window", "00:00")
    try:
        hours, minutes = [int(part) for part in text.split(":")]
    except ValueError as err:
        print("window: cannot parse %r (%s), using midnight" % (text, err))
        hours, minutes = 0, 0
    return hours * 60 + minutes


def optimize(deliveries):
    cleared = []
    for plan in deliveries:
        try:
            ident = plan["id"]
        except KeyError as err:
            print("main: skipping plan with missing identifier %s" % err)
            continue
        altitude = plan_altitude(plan)
        reserve, rate = project_battery(plan, altitude)
        approved, margin = check_clearance(plan, reserve)
        if not approved:
            print("main: %s denied (reserve %.1f%%, margin %.2fkg)" % (ident, reserve, margin))
            continue
        cleared.append({
            "id": ident,
            "altitude_m": round(altitude, 1),
            "battery_reserve": round(reserve, 1),
            "drain_rate": round(rate, 3),
            "depart_minute": parse_window(plan),
        })
    return cleared


def main():
    deliveries = [
        {"id": "D1", "zone": "downtown", "tier": 1, "height": "115",
         "wind_resistance": [1.2, 0.8], "power_draw": 1.5,
         "duration_min": 18, "corridor": "A1", "payload_kg": 3.2, "window": "09:45"},
        {"id": "D2", "zone": "marina", "tier": 5, "height": "high",
         "wind_resistance": [], "power_draw": -2.0,
         "duration_min": 0, "corridor": "Z9", "payload_kg": "heavy", "window": "noon"},
        {"zone": "harbor", "height": 70, "corridor": "B2", "payload_kg": 1.0},
    ]
    for flight in optimize(deliveries):
        print("cleared %s at %.1fm, depart minute %d" % (
            flight["id"], flight["altitude_m"], flight["depart_minute"]))


if __name__ == "__main__":
    main()

