TAXONOMY = {
    "basalt": "igneous",
    "shale": "sedimentary",
    "gneiss": "metamorphic",
}


def readings(values):
    for value in values:
        yield value


def analyze(samples):
    records = []
    logs = []
    for sample in samples:
        record = {"id": sample.get("id")}
        log = []
        try:
            record["altitude_ref"] = sample["coordinates"][2]
        except IndexError as err:
            log.append("Location: %s" % err)
        try:
            record["elevation"] = int(sample["elevation"])
        except ValueError as err:
            log.append("Elevation: %s" % err)
        try:
            record["group"] = TAXONOMY[sample["category"]]
        except KeyError as err:
            log.append("Taxonomy: %s" % err)
        try:
            record["density"] = sample["mass"] / float(sample["volume"])
        except ZeroDivisionError as err:
            log.append("Density: %s" % err)
        try:
            record["reading"] = next(sample["readings"])
        except StopIteration as err:
            log.append("Sample: %s" % err)
        try:
            record["remarks"] = sample["remarks"].upper()
        except AttributeError as err:
            log.append("Remarks: %s" % err)
        try:
            record["temperature"] = float(sample["temperature"])
        except TypeError as err:
            log.append("Temperature: %s" % err)
        try:
            handle = open(sample["image"], "rb")
        except IOError as err:
            log.append("File: %s" % err)
        else:
            record["image_size"] = len(handle.read())
            handle.close()
        if log:
            logs.append({"id": sample.get("id"), "messages": log})
        else:
            records.append(record)
    return records, logs


def format_report(records, logs):
    lines = ["analyzed: %d" % (len(records) + len(logs))]
    total = sum(record["density"] for record in records)
    try:
        lines.append("mean density: %.3f" % (total / len(records)))
    except ZeroDivisionError as err:
        lines.append("mean density unavailable (%s)" % err)
    for entry in logs:
        for message in entry["messages"]:
            lines.append("%s -> %s" % (entry["id"], message))
    return "\n".join(lines)


def main():
    samples = [
        {"id": "S1", "coordinates": [10.0, 20.0, 305.0], "elevation": "305",
         "category": "basalt", "mass": 84.0, "volume": 30.0,
         "readings": readings([1.5, 1.6]), "remarks": "dry outcrop",
         "temperature": "14.2", "image": __file__},
        {"id": "S2", "coordinates": [11.0, 21.0], "elevation": "high",
         "category": "tuff", "mass": 50.0, "volume": 0,
         "readings": readings([]), "remarks": None,
         "temperature": None, "image": "missing.png"},
    ]
    records, logs = analyze(samples)
    report = format_report(records, logs)
    print(report)
    try:
        handle = open("analysis_report.txt", "w")
    except IOError as err:
        print("Report not saved: %s" % err)
    else:
        handle.write(report + "\n")
        handle.close()


if __name__ == "__main__":
    main()

