ALLERGY_DB = {
    'peanut': 'antihistamine',
    'latex': 'topical-steroid',
    'penicillin': 'macrolide',
}

ROWS = [
    'Ann Lee, 34, 70, 1.80, 2.5, A+, peanut|latex, notes/ann.txt',
    'Bob Ray, , 80, 0, high, , , notes/bob.txt',
    'Cid Fox, 51, 66, 1.70, 4.0, o-, penicillin, notes/cid.txt',
    'Dee Kim, 29, abc, 1.60, 1.0, B+, latex, notes/dee.txt',
]


def parse_row(text):
    parts = [item.strip() for item in text.split(',')]
    try:
        name, age, weight, height, severity, blood, allergies, notes = parts
    except ValueError as err:
        print('Row rejected (%s): %s' % (text, err))
        return None
    try:
        weight = float(weight)
        height = float(height)
    except ValueError as err:
        print('Row for %s has bad measurements: %s' % (name, err))
        return None
    return {
        'name': name,
        'age': age or None,
        'weight': weight,
        'height': height,
        'severity': severity,
        'blood_type': blood or None,
        'history': tuple([item for item in allergies.split('|') if item]),
        'notes': notes,
    }


def read_notes(path):
    handle = open(path)
    try:
        return handle.read().strip()
    finally:
        handle.close()


def register(patients):
    registry = []
    errors = []
    for patient in patients:
        record = {'name': patient['name']}
        try:
            record['allergy'] = patient['history'][0]
        except IndexError as err:
            errors.append('Allergy: %s' % err)
        try:
            record['age'] = int(patient['age'])
        except TypeError as err:
            errors.append('Age: %s' % err)
        try:
            record['medication'] = ALLERGY_DB[record['allergy']]
        except KeyError as err:
            errors.append('Medication: %s' % err)
        try:
            record['dosage'] = patient['weight'] / patient['height']
        except ZeroDivisionError as err:
            errors.append('Dosage: %s' % err)
        try:
            record['notes'] = read_notes(patient['notes'])
        except IOError as err:
            errors.append('Notes: %s' % err)
        try:
            record['severity'] = float(patient['severity'])
        except ValueError as err:
            errors.append('Severity: %s' % err)
        try:
            record['blood'] = patient['blood_type'].lower()
        except AttributeError as err:
            errors.append('Blood: %s' % err)
        try:
            record['doctor'] = next(patient['schedule'])
        except StopIteration as err:
            errors.append('Doctor: %s' % err)
        registry.append(record)
    return registry, errors


def format_report(registry, errors):
    lines = []
    for record in registry:
        try:
            lines.append('%s: %s, age %d, %s, dosage %.2f' % (
                record['name'], record['blood'], record['age'],
                record['doctor'], record['dosage']))
        except KeyError as err:
            lines.append('%s: incomplete record, missing %s' % (record['name'], err))
    lines.append('%d problem(s) logged' % len(errors))
    lines.extend(errors)
    return lines


def main():
    doctors = iter(['Dr. Chen', 'Dr. Patel', 'Dr. Olu'])
    patients = []
    for row in ROWS:
        patient = parse_row(row)
        if patient is None:
            continue
        patient['schedule'] = doctors
        patients.append(patient)
    registry, errors = register(patients)
    for line in format_report(registry, errors):
        print(line)


if __name__ == '__main__':
    main()

