    "lot-204": {"title": "Oak desk", "reserve": 340.0},
}


def _log(errors, prefix, err):
    errors.append("%s %s" % (prefix, err))


def bid(requests):
    bids = []
    errors = []
    for number, request in enumerate(requests, 1):
        record = {"request": number}
        try:
            record["start"] = request["amounts"][1]
        except IndexError as err:
            _log(errors, "Bid:", err)
            record["start"] = None
        try:
            max_bid = float(request["max_bid"])
        except ValueError as err:
            _log(errors, "Max:", err)
            max_bid = 0.0
        record["max_bid"] = max_bid
        try:
            record["item"] = ACTIVE_LOTS[request["item"]]["title"]
        except KeyError as err:
            _log(errors, "Item:", err)
            record["item"] = "unknown lot"
        try:
            record["increment"] = max_bid / request["remaining_time"]
        except ZeroDivisionError as err:
            _log(errors, "Increment:", err)
            record["increment"] = None
        try:
            record["bidder"] = next(request["bidders"])
        except StopIteration as err:
            _log(errors, "Bidder:", err)
            record["bidder"] = "no bidders left"
        try:
            record["token"] = request["token"].decode("ascii")
        except UnicodeDecodeError as err:
            _log(errors, "Token:", err)
            record["token"] = ""
        try:
            record["name_parts"] = request["username"].split(" ")
        except AttributeError as err:
            _log(errors, "Username:", err)
            record["name_parts"] = []
        try:
            record["duration"] = int(request["duration"])
        except TypeError as err:
            _log(errors, "Duration:", err)
            record["duration"] = 0
        bids.append(record)
    return bids, errors


def format_audit(bids, errors):
    lines = ["processed %d bid(s)" % len(bids)]
    for record in bids:
        try:
            increment = "%.2f" % record["increment"]
        except TypeError as err:
            increment = "unavailable (%s)" % err
        lines.append("#%d %s start=%s increment=%s bidder=%s duration=%d" % (
            record["request"], record["item"], record["start"],
            increment, record["bidder"], record["duration"]))
    for message in errors:
        lines.append("AUDIT " + message)
    return lines


def main():
    requests = [
        {"amounts": [100, 150, 200], "max_bid": "500.5", "item": "lot-101",
         "remaining_time": 5, "bidders": iter(["ann", "bob"]),
         "token": b"tok-9911", "username": "ann smith", "duration": "90"},
        {"amounts": [75], "max_bid": "high", "item": "lot-777",
         "remaining_time": 0, "bidders": iter([]),
         "token": b"\xffbad", "username": None, "duration": None},
    ]
    bids, errors = bid(requests)
    for line in format_audit(bids, errors):
        print(line)


if __name__ == "__main__":
    main()

