TEMPLATES = {
    'ubuntu-22.04': 'ami-0001',
    'debian-12': 'ami-0002',
    'alpine-3.19': 'ami-0003',
}


def provision(requests):
    provisions = []
    logs = []
    for req in requests:
        record = {}
        try:
            record['secondary_ip'] = req['interfaces'][1]
        except IndexError, err:
            logs.append('Network: %s' % err)
            continue
        try:
            record['memory_mb'] = int(req['memory'])
        except ValueError, err:
            logs.append('Memory: %s' % err)
            continue
        try:
            record['image_id'] = TEMPLATES[req['image']]
        except KeyError, err:
            logs.append('Image: %s' % err)
            continue
        try:
            record['cost_per_hour'] = req['monthly_rate'] / float(req['uptime'])
        except ZeroDivisionError, err:
            logs.append('Cost: %s' % err)
            continue
        try:
            record['subnet'] = next(req['subnets'])
        except StopIteration, err:
            logs.append('Subnet: %s' % err)
            continue
        try:
            record['hostname'] = req['name'].replace(' ', '-')
        except AttributeError, err:
            logs.append('Name: %s' % err)
            continue
        try:
            record['storage_gb'] = float(req['storage'])
        except TypeError, err:
            logs.append('Storage: %s' % err)
            continue
        try:
            record['script'] = req['script'].decode('utf-8')
        except UnicodeDecodeError, err:
            logs.append('Script: %s' % err)
            continue
        provisions.append(record)
    return provisions, logs


def average_cost(provisions):
    total = sum([p['cost_per_hour'] for p in provisions])
    try:
        return total / len(provisions)
    except ZeroDivisionError, err:
        print('Summary: %s' % err)
        return 0.0


def make_request(name, interfaces, memory, image, rate, uptime, subnets,
                 storage, script):
    return {'name': name, 'interfaces': interfaces, 'memory': memory,
            'image': image, 'monthly_rate': rate, 'uptime': uptime,
            'subnets': iter(subnets), 'storage': storage, 'script': script}


