KNOWN_THREATS = {
    'sig-aa11': 'Trojan.Generic',
    'sig-bb22': 'Worm.Spread',
    'sig-cc33': 'Ransom.Locker',
}


def ingest(threats):
    results = []
    for threat in threats:
        errors = []
        clean = {}
        try:
            clean['port'] = threat['packet'][2]
        except IndexError as err:
            errors.append('Port: %s' % err)
        try:
            clean['severity'] = int(threat['severity'])
        except ValueError as err:
            errors.append('Severity: %s' % err)
        try:
            clean['family'] = KNOWN_THREATS[threat['signature']]
        except KeyError as err:
            errors.append('Signature: %s' % err)
        try:
            clean['rate'] = threat['size'] / threat['duration']
        except ZeroDivisionError as err:
            errors.append('Rate: %s' % err)
        payload = None
        try:
            payload = next(threat['stream'])
        except StopIteration as err:
            errors.append('Payload: %s' % err)
        try:
            clean['text'] = payload.decode('utf-8')
        except AttributeError as err:
            errors.append('Decode: %s' % err)
        try:
            clean['time'] = float(threat['timestamp'])
        except TypeError as err:
            errors.append('Time: %s' % err)
        try:
            handle = open(threat['path'], 'rb')
        except EnvironmentError as err:
            errors.append('Cache: %s' % err)
        else:
            clean['cache_size'] = len(handle.read())
            handle.close()
        results.append((clean, errors))
    return results


def format_report(results):
    lines = []
    rates = [clean['rate'] for clean, errors in results if 'rate' in clean]
    for index, pair in enumerate(results):
        clean, errors = pair
        lines.append('threat %d: %d field(s), %d error(s)'
                     % (index, len(clean), len(errors)))
        for message in errors:
            lines.append('    ' + message)
    try:
        lines.append('mean rate: %.2f' % (sum(rates) / len(rates)))
    except ZeroDivisionError as err:
        lines.append('mean rate unavailable: %s' % err)
    return '\n'.join(lines)


def main():
    threats = [
        {'packet': ('10.0.0.1', '10.0.0.9', 443), 'severity': '4',
         'signature': 'sig-aa11', 'size': 1400.0, 'duration': 2.0,
         'stream': iter([b'GET /admin']), 'timestamp': '1699999999.5',
         'path': '/tmp/threat-cache-aa11.bin'},
        {'packet': ('10.0.0.2', '10.0.0.8'), 'severity': 'critical',
         'signature': 'sig-zz99', 'size': 900.0, 'duration': 0.0,
         'stream': iter([]), 'timestamp': None,
         'path': '/tmp/threat-cache-zz99.bin'},
        {'packet': ('10.0.0.3', '10.0.0.7', 8080), 'severity': '2',
         'signature': 'sig-cc33', 'size': 300.0, 'duration': 1.5,
         'stream': iter([12345]), 'timestamp': '17',
         'path': '/tmp/threat-cache-cc33.bin'},
    ]
    print(format_report(ingest(threats)))


if __name__ == '__main__':
    main()

