SEATING_CHART = {"A3": 2, "B12": 6, "C7": 4}


def parse_booking(raw):
    name, contact, table, deposit, details, duration, schedule, requests_path = raw
    try:
        deposit_value = float(deposit)
    except ValueError as err:
        raise ValueError("unusable deposit %r (%s)" % (deposit, err))
    return {"name": name, "contact": contact, "table": table,
            "deposit": deposit_value, "details": details, "duration": duration,
            "schedule": schedule, "requests": requests_path}


def reserve(bookings):
    report = {"confirmed": [], "errors": []}
    for booking in bookings:
        problems = []
        guests = 0
        try:
            guests = booking["details"][4]
        except IndexError as err:
            problems.append("Guests: %s" % err)
        contact = None
        try:
            contact = int(booking["contact"])
        except ValueError as err:
            problems.append("Contact: %s" % err)
        seats = None
        try:
            seats = SEATING_CHART[booking["table"]]
        except KeyError as err:
            problems.append("Table: %s" % err)
        per_guest = None
        try:
            per_guest = booking["deposit"] / guests
        except ZeroDivisionError as err:
            problems.append("Deposit: %s" % err)
        slot = None
        try:
            slot = next(booking["schedule"])
        except StopIteration as err:
            problems.append("Time: %s" % err)
        name = None
        try:
            name = booking["name"].title()
        except AttributeError as err:
            problems.append("Name: %s" % err)
        duration = None
        try:
            duration = float(booking["duration"])
        except TypeError as err:
            problems.append("Duration: %s" % err)
        requests_text = ""
        try:
            handle = open(booking["requests"])
            requests_text = handle.read().strip()
            handle.close()
        except IOError as err:
            problems.append("Requests: %s" % err)
        if problems:
            report["errors"].append((name or booking["name"], problems))
        else:
            report["confirmed"].append({"name": name, "contact": contact,
                                        "table": booking["table"], "seats": seats,
                                        "guests": guests, "per_guest": per_guest,
                                        "slot": slot, "duration": duration,
                                        "requests": requests_text})
    return report


def format_report(report):
    lines = ["Confirmed: %d" % len(report["confirmed"])]
    for row in report["confirmed"]:
        lines.append("  %s (%d) table %s/%d seats at %s, %.2f per guest, %.1fh, notes: %s"
                     % (row["name"], row["contact"], row["table"], row["seats"],
                        row["slot"], row["per_guest"], row["duration"], row["requests"]))
    lines.append("Errors: %d" % len(report["errors"]))
    for name, problems in report["errors"]:
        for problem in problems:
            lines.append("  %s -> %s" % (name, problem))
    return "\n".join(lines)


def main():
    handle = open("requests_a3.txt", "w")
    handle.write("window seat, quiet corner\n")
    handle.close()
    raws = [("ada lovelace", "5551234", "A3", "120.00", [1, 1, 1, 1, 2], 2,
             iter(["19:00"]), "requests_a3.txt"),
            (None, "call-me", "Z9", "80", [1, 1, 1], None,
             iter([]), "requests_z9.txt"),
            ("grace hopper", "5559999", "B12", "oops", [1, 1, 1, 1, 4], 3,
             iter(["20:30"]), "requests_b12.txt")]
    bookings = []
    for raw in raws:
        try:
            bookings.append(parse_booking(raw))
        except ValueError as err:
            print("Skipped booking for %s: %s" % (raw[0], err))
    print(format_report(reserve(bookings)))


if __name__ == "__main__":
    main()

