STAFF_PREFIX = 'Mechanic:'


def log(records):
    """Validate a batch of maintenance records, returning logs and errors."""
    logs = []
    errors = []
    for record in records:
        entry = {}
        problems = []
        try:
            entry['route'] = record['route'][3]
        except IndexError as err:
            problems.append('Route: %s' % err)
        try:
            entry['mileage'] = int(record['mileage'])
        except ValueError as err:
            problems.append('Mileage: %s' % err)
        try:
            entry['mechanic'] = record['staff'][record['mechanic']]
        except KeyError as err:
            problems.append('%s %s' % (STAFF_PREFIX, err))
        try:
            entry['efficiency'] = record['distance'] / record['fuel']
        except ZeroDivisionError as err:
            problems.append('Efficiency: %s' % err)
        try:
            entry['part'] = next(record['inventory'])
        except StopIteration as err:
            problems.append('Part: %s' % err)
        try:
            entry['notes'] = record['notes'].strip()
        except AttributeError as err:
            problems.append('Notes: %s' % err)
        try:
            entry['cost'] = float(record['cost'])
        except TypeError as err:
            problems.append('Cost: %s' % err)
        try:
            handle = open(record['manual'])
        except IOError as err:
            problems.append('Manual: %s' % err)
        else:
            entry['manual'] = record['manual']
            handle.close()
        logs.append(entry)
        errors.append(problems)
    return logs, errors


def format_report(logs, errors):
    lines = []
    for position, entry in enumerate(logs):
        try:
            lines.append('Vehicle %d: route %s, %d km, mechanic %s, part %s' %
                         (position + 1, entry['route'], entry['mileage'],
                          entry['mechanic'], entry['part']))
        except KeyError as err:
            lines.append('Vehicle %d: incomplete log, missing field %s' %
                         (position + 1, err))
        for message in errors[position]:
            lines.append('    ! ' + message)
    return '\n'.join(lines)


def main():
    staff = {'M-11': 'Ada Byrne', 'M-42': 'Ravi Shah'}
    records = [
        {'route': ['A1', 'B2', 'C3', 'D4'], 'mileage': '128400',
         'mechanic': 'M-11', 'staff': staff, 'distance': 480.0, 'fuel': 32.0,
         'inventory': iter(['brake pad', 'oil filter']), 'notes': '  ok  ',
         'cost': '215.50', 'manual': __file__},
        {'route': ['A1', 'B2'], 'mileage': 'n/a',
         'mechanic': 'M-99', 'staff': staff, 'distance': 300.0, 'fuel': 0.0,
         'inventory': iter([]), 'notes': None,
         'cost': None, 'manual': 'missing_service_manual.txt'},
    ]
    logs, errors = log(records)
    print(format_report(logs, errors))
    total = sum(entry['cost'] for entry in logs if 'cost' in entry)
    print('Total repair cost: %.2f' % total)


if __name__ == '__main__':
    main()

