TARIFF_TEXT = """
standard = 0.15
business = 0.11
prepaid = 0.22
"""


def load_tariffs(text):
    plans = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            name, value = line.split('=')
        except ValueError as err:
            print('Tariff: %s' % err)
            continue
        try:
            plans[name.strip()] = float(value.strip())
        except ValueError as err:
            print('Tariff: %s' % err)
    return plans


TARIFFS = load_tariffs(TARIFF_TEXT)


def bill(usage):
    bills = []
    errors = []
    for record in usage:
        try:
            detail = record['history'][2]
        except IndexError as err:
            errors.append('Call: %s' % err)
            detail = 'no detail'
        try:
            duration = int(record['duration'])
        except ValueError as err:
            errors.append('Duration: %s' % err)
            duration = 0
        try:
            plan = TARIFFS[record['plan']]
        except KeyError as err:
            errors.append('Plan: %s' % err)
            plan = 0.0
        try:
            rate = record['charge'] / record['minutes']
        except ZeroDivisionError as err:
            errors.append('Rate: %s' % err)
            rate = 0.0
        try:
            message = next(record['outbox'])
        except StopIteration as err:
            errors.append('Message: %s' % err)
            message = ''
        try:
            destination = record['country'].replace('-', ' ')
        except AttributeError as err:
            errors.append('Destination: %s' % err)
            destination = 'unknown'
        try:
            data = float(record['data'])
        except TypeError as err:
            errors.append('Data: %s' % err)
            data = 0.0
        try:
            handle = open(record['template'])
            template = handle.read().strip()
            handle.close()
        except IOError as err:
            errors.append('Invoice: %s' % err)
            template = 'plain invoice'
        bills.append({'detail': detail, 'destination': destination,
                      'message': message, 'template': template,
                      'amount': plan * duration + rate + data * 0.05})
    return bills, errors


def summarize(bills):
    total = 0.0
    for entry in bills:
        total += entry['amount']
    try:
        average = total / len(bills)
    except ZeroDivisionError as err:
        print('Summary: %s' % err)
        average = 0.0
    return total, average


def format_report(bills, errors):
    lines = []
    for entry in bills:
        lines.append('{0} -> {1} [{2}] {3}: {4:.2f}'.format(
            entry['detail'], entry['destination'], entry['message'],
            entry['template'], entry['amount']))
    total, average = summarize(bills)
    lines.append('total %.2f average %.2f' % (total, average))
    for problem in errors:
        lines.append('! ' + problem)
    return '\n'.join(lines)


def main():
    usage = [
        {'history': ['dial', 'ring'], 'duration': '12', 'plan': 'standard',
         'charge': 6.0, 'minutes': 4, 'outbox': iter(['hello']),
         'country': 'united-kingdom', 'data': '120', 'template': __file__},
        {'history': ['dial', 'ring', 'voicemail to 555'], 'duration': 'abc',
         'plan': 'gold', 'charge': 3.0, 'minutes': 0, 'outbox': iter([]),
         'country': None, 'data': None, 'template': 'missing-invoice.tpl'},
    ]
    bills, errors = bill(usage)
    print(format_report(bills, errors))


if __name__ == '__main__':
    main()

