def format_error(prefix, err):
    return "%s %s" % (prefix, err)


def load_capacity(setting):
    """Read a 'capacity=<int>' configuration entry, defaulting to 0."""
    try:
        return int(setting.split('=', 1)[1])
    except ValueError as err:
        print("bad capacity setting (%s), assuming 0" % err)
        return 0


def monitor(cameras):
    clean = []
    errors = []
    for cam in cameras:
        record = {}
        try:
            record['intersection'] = cam['nodes'][1]
        except IndexError as err:
            errors.append(format_error('Intersection:', err))
        try:
            record['speed'] = int(cam['avg_speed'])
        except ValueError as err:
            errors.append(format_error('Speed:', err))
        try:
            record['maintenance'] = cam['maintenance'][cam['camera_id']]
        except KeyError as err:
            errors.append(format_error('Camera:', err))
        try:
            record['density'] = cam['car_count'] / cam['capacity']
        except ZeroDivisionError as err:
            errors.append(format_error('Density:', err))
        try:
            record['snapshot'] = next(cam['stream'])
        except StopIteration as err:
            errors.append(format_error('Snapshot:', err))
        try:
            record['plate'] = cam['plate'].upper()
        except AttributeError as err:
            errors.append(format_error('License:', err))
        try:
            record['flow'] = float(cam['flow_rate'])
        except TypeError as err:
            errors.append(format_error('Flow:', err))
        try:
            handle = open(cam['log_path'])
        except IOError as err:
            errors.append(format_error('Log:', err))
        else:
            record['log_lines'] = len(handle.readlines())
            handle.close()
        clean.append(record)
    return clean, errors


def report(clean, errors):
    lines = []
    for index, record in enumerate(clean):
        fields = sorted(record.keys())
        values = ", ".join(["%s=%r" % (key, record[key]) for key in fields])
        lines.append("camera %d -> %s" % (index, values))
    for message in errors:
        lines.append("AUDIT " + message)
    return "\n".join(lines)


def main():
    good = {
        'nodes': ['A1', 'B2'],
        'avg_speed': '47',
        'camera_id': 'CAM-1',
        'maintenance': {'CAM-1': '2024-05-01'},
        'car_count': 120,
        'capacity': load_capacity('capacity=300'),
        'stream': iter(['frame-001']),
        'plate': 'xk 42 lp',
        'flow_rate': '18.5',
        'log_path': __file__,
    }
    broken = {
        'nodes': ['A1'],
        'avg_speed': 'fast',
        'camera_id': 'CAM-9',
        'maintenance': {'CAM-1': '2024-05-01'},
        'car_count': 88,
        'capacity': load_capacity('capacity=unknown'),
        'stream': iter([]),
        'plate': None,
        'flow_rate': ['18.5'],
        'log_path': 'traffic-daily.log',
    }
    clean, errors = monitor([good, broken])
    print(report(clean, errors))


if __name__ == '__main__':
    main()

