def parse_reading(line, telemetry):
    parts = line.split('|')
    try:
        zones, pressure, model, deviation, baseline, status, temperature, config = parts
    except ValueError as err:
        raise ValueError('bad reading layout in %r (%s)' % (line, err))
    try:
        deviation = float(deviation)
        baseline = float(baseline)
    except ValueError as err:
        raise ValueError('bad metrics in %r (%s)' % (line, err))
    return {
        'zones': zones.split(','),
        'pressure': pressure,
        'model': model,
        'deviation': deviation,
        'baseline': baseline,
        'telemetry': telemetry,
        'status': None if status == '-' else status,
        'temperature': None if temperature == '-' else temperature,
        'config': config,
    }


def calibrate(readings):
    calibrated = []
    errors = []
    for reading in readings:
        record = {}
        try:
            record['zone'] = reading['zones'][3]
        except IndexError as err:
            errors.append('Zone: %s' % err)
        try:
            record['pressure'] = int(reading['pressure'])
        except ValueError as err:
            errors.append('Pressure: %s' % err)
        try:
            record['factor'] = SPECIFICATIONS[reading['model']]
        except KeyError as err:
            errors.append('Sensor: %s' % err)
        try:
            record['variance'] = reading['deviation'] / reading['baseline']
        except ZeroDivisionError as err:
            errors.append('Variance: %s' % err)
        try:
            record['pulse'] = next(reading['telemetry'])
        except StopIteration as err:
            errors.append('Signal: %s' % err)
        try:
            record['status'] = reading['status'].split(',')
        except AttributeError as err:
            errors.append('Status: %s' % err)
        try:
            record['temperature'] = float(reading['temperature'])
        except TypeError as err:
            errors.append('Temperature: %s' % err)
        try:
            handle = open(reading['config'])
        except FileNotFoundError as err:
            errors.append('Config: %s' % err)
        else:
            try:
                record['config'] = handle.read().strip()
            finally:
                handle.close()
        calibrated.append(record)
    return calibrated, errors


def summarize(calibrated):
    values = [record['variance'] for record in calibrated if 'variance' in record]
    try:
        average = sum(values) / len(values)
    except ZeroDivisionError as err:
