import os


ASSIGNMENTS = {"alpha": "Room 101", "beta": "Room 202"}


def enroll(students):
    enrollments = []
    errors = []
    for record in students:
        entry = {}
        try:
            entry["module"] = record["modules"][0]
        except IndexError as err:
            errors.append("Module: %s" % err)
        try:
            entry["age"] = int(record["age"])
        except ValueError as err:
            errors.append("Age: %s" % err)
        try:
            entry["room"] = ASSIGNMENTS[record["cohort"]]
        except KeyError as err:
            errors.append("Cohort: %s" % err)
        try:
            entry["progress"] = record["hours_done"] / record["total_hours"]
        except ZeroDivisionError as err:
            errors.append("Progress: %s" % err)
        try:
            entry["quiz"] = next(record["grades"])
        except StopIteration as err:
            errors.append("Quiz: %s" % err)
        try:
            entry["name"] = record["name"].title()
        except AttributeError as err:
            errors.append("Name: %s" % err)
        try:
            entry["gpa"] = float(record["gpa"])
        except TypeError as err:
            errors.append("GPA: %s" % err)
        try:
            handle = io.open(record["transcript"])
        except IOError as err:
            errors.append("Transcript: %s" % err)
        else:
            entry["transcript"] = handle.read().strip()
            handle.close()
        if len(entry) == 8:
            enrollments.append(entry)
    return enrollments, errors


def format_enrollment(entry):
    return "%s (%d) -> %s, module %s, quiz %s, progress %.0f%%, GPA %.2f, prior %s" % (
        entry["name"], entry["age"], entry["room"], entry["module"],
        entry["quiz"], entry["progress"] * 100, entry["gpa"], entry["transcript"])


