import sys


def route(manifests):
    """Process each manifest, collecting partial results and error strings."""
    routed = []
    errors = []
    for manifest in manifests:
        entry = {}
        problems = []
        try:
            entry['container'] = manifest['containers'][2]
        except IndexError as err:
            problems.append('Container: %s' % err)
        try:
            entry['weight'] = int(manifest['weight'])
        except ValueError as err:
            problems.append('Weight: %s' % err)
        try:
            entry['vessel'] = manifest['registry'][manifest['vessel']]
        except KeyError as err:
            problems.append('Vessel: %s' % err)
        try:
            entry['distribution'] = manifest['total_load'] / manifest['deck_space']
        except ZeroDivisionError as err:
            problems.append('Distribution: %s' % err)
        try:
            entry['waypoint'] = next(manifest['navigation'])
        except StopIteration as err:
            problems.append('Waypoint: %s' % err)
        try:
            entry['cargo'] = manifest['description'].strip()
        except AttributeError as err:
            problems.append('Cargo: %s' % err)
        try:
            entry['draft'] = float(manifest['draft'])
        except TypeError as err:
            problems.append('Draft: %s' % err)
        try:
            handle = open(manifest['declaration'])
            entry['declaration'] = handle.read().strip()
            handle.close()
        except IOError as err:
            problems.append('Manifest: %s' % err)
        routed.append(entry)
        errors.append(problems)
    return routed, errors


def summarize(routed, errors):
    """Build a human readable report of the routing run."""
    lines = []
    failures = 0
    for index, entry in enumerate(routed):
        keys = sorted(entry.keys())
        lines.append('manifest %d: %d fields (%s)' % (index, len(keys), ', '.join(keys)))
        for message in errors[index]:
            failures += 1
            lines.append('    %s' % message)
    try:
        rate = float(failures) / len(routed)
    except ZeroDivisionError as err:
        lines.append('no manifests routed (%s)' % err)
    else:
        lines.append('%d errors over %d manifests (%.2f each)' % (failures, len(routed), rate))
    return '\n'.join(lines)


def main(argv):
    deck_space = 120
    if len(argv) > 1:
        try:
            deck_space = int(argv[1])
        except ValueError as err:
            sys.stderr.write('bad deck space, using default: %s\n' % err)
    registry = {'Nordwind': 'IMO9101112'}
    manifests = [
        {'containers': ['A1', 'B2', 'C3'], 'weight': '4200', 'vessel': 'Nordwind',
         'registry': registry, 'total_load': 9600, 'deck_space': deck_space,
         'navigation': iter(['Bergen', 'Aalborg']), 'description': '  steel coils ',
         'draft': '7.5', 'declaration': 'customs_nordwind.txt'},
        {'containers': ['D4'], 'weight': 'heavy', 'vessel': 'Seagull',
         'registry': registry, 'total_load': 500, 'deck_space': 0,
         'navigation': iter([]), 'description': None,
         'draft': None, 'declaration': 'missing_declaration.txt'},
    ]
    routed, errors = route(manifests)
    print(summarize(routed, errors))
    return 1 if any(errors) else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

