    "inverter": "Inverter:",
    "efficiency": "Efficiency:",
    "reading": "Reading:",
    "condition": "Condition:",
    "voltage": "Voltage:",
    "history": "History:",
}


def forecast(panels):
    forecasts = []
    errors = []
    for panel in panels:
        report = {"id": panel.get("id", "unknown")}
        try:
            report["array"] = panel["coordinates"][1]
        except IndexError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["array"], err))
        try:
            report["irradiance"] = int(panel["irradiance"])
        except ValueError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["irradiance"], err))
        try:
            report["derate"] = INVERTER_SPECS[panel["inverter"]]
        except KeyError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["inverter"], err))
        try:
            report["density"] = panel["power"] / panel["area"]
        except ZeroDivisionError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["efficiency"], err))
        try:
            report["next_weather"] = next(panel["weather"])
        except StopIteration as err:
            errors.append("%s %s" % (ERROR_PREFIXES["reading"], err))
        try:
            report["condition"] = panel["condition"].lower()
        except AttributeError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["condition"], err))
        try:
            report["voltage"] = float(panel["voltage"])
        except TypeError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["voltage"], err))
        try:
            handle = open(panel["history"])
        except IOError as err:
            errors.append("%s %s" % (ERROR_PREFIXES["history"], err))
