BENEFITS = {
    'bronze': 'free newsletter',
    'silver': 'free shipping',
    'gold': 'priority support',
}


def reward(purchases):
    profiles = []
    logs = []
    for purchase in purchases:
        profile = {}
        errors = []
        try:
            profile['item'] = purchase['items'][2]
        except IndexError as err:
            errors.append('Item: %s' % err)
        try:
            profile['points'] = int(purchase['bonus_points'])
        except ValueError as err:
            errors.append('Points: %s' % err)
        try:
            profile['benefit'] = BENEFITS[purchase['tier']]
        except KeyError as err:
            errors.append('Tier: %s' % err)
        try:
            profile['ratio'] = purchase['total_spent'] / purchase['visits']
        except ZeroDivisionError as err:
            errors.append('Ratio: %s' % err)
        try:
            profile['coupon'] = next(purchase['promos'])
        except StopIteration as err:
            errors.append('Coupon: %s' % err)
        try:
            profile['feedback'] = purchase['feedback'].capitalize()
        except AttributeError as err:
            errors.append('Feedback: %s' % err)
        try:
            profile['discount'] = float(purchase['discount_rate'])
        except TypeError as err:
            errors.append('Discount: %s' % err)
        try:
            handle = open(purchase['receipt'])
        except IOError as err:
            errors.append('Receipt: %s' % err)
        else:
            try:
                profile['receipt'] = handle.readline().strip()
            finally:
                handle.close()
        profiles.append(profile)
        logs.append(errors)
    return profiles, logs


def describe(profile):
    parts = []
    try:
        parts.append('item=%s' % profile['item'])
    except KeyError as err:
        parts.append('item unknown (%s)' % err)
    try:
        parts.append('points=%d' % profile['points'])
    except KeyError as err:
        parts.append('points unknown (%s)' % err)
    try:
        parts.append('spend/visit=%.2f' % profile['ratio'])
    except KeyError as err:
        parts.append('ratio unknown (%s)' % err)
    try:
        parts.append('benefit=%s, coupon=%s' % (profile['benefit'], profile['coupon']))
    except KeyError as err:
        parts.append('benefit or coupon unknown (%s)' % err)
    return ', '.join(parts)


def main():
    purchases = [
        {'items': ['mug', 'pen', 'lamp'], 'bonus_points': '120', 'tier': 'gold',
         'total_spent': 240.0, 'visits': 8, 'promos': iter(['FREESHIP']),
         'feedback': 'great service', 'discount_rate': '0.15', 'receipt': __file__},
        {'items': ['socks'], 'bonus_points': 'many', 'tier': 'platinum',
         'total_spent': 50.0, 'visits': 0, 'promos': iter([]),
         'feedback': None, 'discount_rate': None, 'receipt': 'no_such_receipt.txt'},
    ]
    profiles, logs = reward(purchases)
    for index in range(len(profiles)):
        print('profile %d: %s' % (index, describe(profiles[index])))
        for message in logs[index]:
            print('   %s' % message)


if __name__ == '__main__':
    main()

