import os
import tempfile

CROP_REQUIREMENTS = {
    'wheat': {'min_moisture': 25, 'min_ph': 5.5},
    'barley': {'min_moisture': 20, 'min_ph': 6.0},
}


def previous_yield(text):
    for line in text.splitlines():
        if line.startswith('yield:'):
            try:
                return float(line.split(':', 1)[1])
            except ValueError as err:
                raise ValueError('unreadable yield entry (%s)' % err)
    return None


def test(samples):
    report = []
    for sample in samples:
        values = {}
        errors = []
        try:
            values['grid'] = sample['field_grid'][0]
        except IndexError as err:
            errors.append('Grid: %s' % err)
        try:
            values['moisture'] = int(sample['moisture'])
        except ValueError as err:
            errors.append('Moisture: %s' % err)
        try:
            values['crop'] = CROP_REQUIREMENTS[sample['crop']]
        except KeyError as err:
            errors.append('Crop: %s' % err)
        try:
            values['acidity'] = sample['ph_buffer'] / sample['agent_volume']
        except ZeroDivisionError as err:
            errors.append('Acidity: %s' % err)
        try:
            values['core'] = next(sample['drill'])
        except StopIteration as err:
            errors.append('Sample: %s' % err)
        try:
            values['texture'] = sample['texture'].split()
        except AttributeError as err:
            errors.append('Texture: %s' % err)
        try:
            values['nitrogen'] = float(sample['nitrogen'])
        except TypeError as err:
            errors.append('Nitrogen: %s' % err)
        try:
            handle = open(sample['report'])
        except IOError as err:
            errors.append('Report: %s' % err)
        else:
            try:
                values['previous_yield'] = previous_yield(handle.read())
            except ValueError as err:
                errors.append('Report: %s' % err)
            finally:
                handle.close()
        report.append({'values': values, 'errors': errors})
    return report


def summarize(report):
    lines = []
    acidities = [item['values']['acidity'] for item in report
                 if 'acidity' in item['values']]
    try:
        lines.append('average acidity: %.2f' % (sum(acidities) / len(acidities)))
    except ZeroDivisionError as err:
        lines.append('average acidity unavailable (%s)' % err)
    for index, item in enumerate(report):
        lines.append('test %d: %d values, %d errors'
                     % (index, len(item['values']), len(item['errors'])))
        for message in item['errors']:
            lines.append('    ' + message)
    return '\n'.join(lines)


def write_report(name, body):
    path = os.path.join(tempfile.gettempdir(), name)
    handle = open(path, 'w')
    handle.write(body)
    handle.close()
    return path


def main():
    good = write_report('season_ok.txt', 'field: north\nyield: 4.2\n')
    broken = write_report('season_bad.txt', 'field: south\nyield: n/a\n')
    samples = [
        {'field_grid': [[1, 2], [3, 4]], 'moisture': '34', 'crop': 'wheat',
         'ph_buffer': 6.4, 'agent_volume': 2.0, 'drill': iter(['core-1']),
         'texture': 'sandy loam', 'nitrogen': '12.5', 'report': good},
        {'field_grid': [], 'moisture': 'wet', 'crop': 'kelp',
         'ph_buffer': 6.0, 'agent_volume': 0, 'drill': iter([]),
         'texture': None, 'nitrogen': None, 'report': 'no_such_report.txt'},
        {'field_grid': [[9]], 'moisture': '18', 'crop': 'barley',
         'ph_buffer': 5.0, 'agent_volume': 2.5, 'drill': iter(['core-7']),
         'texture': 'silty clay', 'nitrogen': '8', 'report': broken},
    ]
    print(summarize(test(samples)))


if __name__ == '__main__':
    main()

