SPACE_AGENCIES = {
    "USA": "NASA",
    "RUS": "Roscosmos",
    "CHN": "CNSA",
    "EUR": "ESA",
}


def track(debris):
    tracks = []
    errors = []
    for item in debris:
        record = {"id": item.get("id")}
        try:
            record["orbit"] = item["orbital_parameters"][1]
        except IndexError, err:
            errors.append("Orbit: %s" % err)
            continue
        try:
            record["velocity"] = int(item["relative_velocity"])
        except ValueError, err:
            errors.append("Velocity: %s" % err)
            continue
        try:
            record["origin"] = SPACE_AGENCIES[item["launch_nation"]]
        except KeyError, err:
            errors.append("Origin: %s" % err)
            continue
        try:
            record["risk"] = item["debris_mass"] / item["collision_cross_section"]
        except ZeroDivisionError, err:
            errors.append("Risk: %s" % err)
            continue
        try:
            record["ping"] = next(item["sensor_iterator"])
        except StopIteration, err:
            errors.append("Ping: %s" % err)
            continue
        try:
            record["shape"] = item["debris_shape"].upper()
        except AttributeError, err:
            errors.append("Shape: %s" % err)
            continue
        try:
            record["altitude"] = float(item["current_altitude"])
        except TypeError, err:
            errors.append("Altitude: %s" % err)
            continue
        try:
            handle = open(item["catalog_path"])
        except IOError, err:
            errors.append("Catalog: %s" % err)
            continue
        try:
            record["catalog_entries"] = len(handle.read().split())
        finally:
            handle.close()
        tracks.append(record)
    return tracks, errors


def format_track(record):
    return "%s | orbit=%s origin=%s risk=%.2f shape=%s alt=%.1f km" % (
        record["id"], record["orbit"], record["origin"],
        record["risk"], record["shape"], record["altitude"])


def load_sightings(path):
    sightings = []
    handle = open(path)
    try:
        for line in handle:
            fields = line.strip().split(",")
            try:
                sighting = {
                    "id": fields[0],
                    "orbital_parameters": fields[1].split(";"),
                    "relative_velocity": fields[2],
                    "launch_nation": fields[3],
                    "debris_mass": float(fields[4]),
                    "collision_cross_section": float(fields[5]),
                    "sensor_iterator": iter(fields[6].split(";")),
                    "debris_shape": fields[7],
                    "current_altitude": fields[8],
                    "catalog_path": fields[9],
                }
            except IndexError, err:
                print("Skipping malformed line: %s" % err)
                continue
            sightings.append(sighting)
    finally:
        handle.close()
    return sightings


def main(path):
    try:
        sightings = load_sightings(path)
    except IOError, err:
        print("Cannot read sightings: %s" % err)
        return 1
    tracks, errors = track(sightings)
    print("Valid tracks: %d" % len(tracks))
    for record in tracks:
        print(format_track(record))
    print("Errors: %d" % len(errors))
    for message in errors:
        print(message)
    return 0


if __name__ == "__main__":
    import sys
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else "sightings.csv"))

