QUANTUM_LIBRARY = {
    "grover": "amplitude amplification",
    "shor": "period finding",
    "vqe": "variational eigensolver",
}


def active_qubit(job, errors):
    try:
        return job.get("active_qubits", [])[0]
    except IndexError as err:
        errors.append("Qubit: %s" % err)
        return None


def gate_cycles(job, errors):
    try:
        return int(job.get("gate_cycles"))
    except ValueError as err:
        errors.append("Cycles: %s" % err)
        return 0


def algorithm_kind(job, errors):
    try:
        return QUANTUM_LIBRARY[job.get("algorithm")]
    except KeyError as err:
        errors.append("Algorithm: %s" % err)
        return "unknown"


def fidelity(job, errors):
    try:
        return job.get("success_rate", 0.0) / job.get("overhead", 0)
    except ZeroDivisionError as err:
        errors.append("Fidelity: %s" % err)
        return None


def next_pulse(job, errors):
    try:
        return next(job.get("controller", iter([])))
    except StopIteration as err:
        errors.append("Pulse: %s" % err)
        return None


def normalized_state(job, errors):
    try:
        return job.get("initial_state").lower()
    except AttributeError as err:
        errors.append("State: %s" % err)
        return "|0>"


def phase(job, errors):
    try:
        return float(job.get("phase_angle"))
    except TypeError as err:
        errors.append("Phase: %s" % err)
        return 0.0


def schedule(jobs):
    for job in jobs:
        errors = []
        record = {"id": job.get("id"), "qubit": active_qubit(job, errors),
                  "cycles": gate_cycles(job, errors),
                  "algorithm": algorithm_kind(job, errors),
                  "fidelity": fidelity(job, errors),
                  "pulse": next_pulse(job, errors),
                  "state": normalized_state(job, errors),
                  "phase": phase(job, errors),
                  "calibration": calibration_header(job, errors)}
        yield record, errors


def calibration_header(job, errors):
    try:
        handle = open(job.get("calibration_file", "calibration.txt"))
    except IOError as err:
        errors.append("Calibration: %s" % err)
        return None
    try:
        return handle.readline().strip()
    finally:
        handle.close()


def mean_fidelity(results):
    total = sum(r["fidelity"] for r in results if r["fidelity"] is not None)
    try:
        return total / float(len(results))
    except ZeroDivisionError as err:
        print("Summary: %s" % err)
        return 0.0


def main():
    jobs = [
        {"id": "J1", "active_qubits": [3, 7], "gate_cycles": "48",
         "algorithm": "grover", "success_rate": 0.9, "overhead": 1.5,
         "controller": iter([1.2, 3.4]), "initial_state": "|PSI>",
         "phase_angle": "0.75", "calibration_file": __file__},
        {"id": "J2", "active_qubits": [], "gate_cycles": "many",
         "algorithm": "teleport", "success_rate": 0.8, "overhead": 0,
         "controller": iter([]), "initial_state": None,
         "phase_angle": None, "calibration_file": "missing_cal.txt"},
    ]
    results = []
    for record, errors in schedule(jobs):
        print("%s: %s on qubit %s" % (record["id"], record["algorithm"], record["qubit"]))
        for message in errors:
            print("  " + message)
        results.append(record)
    print("mean fidelity: %.3f" % mean_fidelity(results))


if __name__ == "__main__":
    main()

