    "poodle": "alert",
}


def read_preference(profile):
    return profile["preferences"][1]


def parse_age(profile):
    return int(profile["age"])


def lookup_temperament(profile):
    return TEMPERAMENTS[profile["breed"]]


def space_per_energy(profile):
    return profile["yard_size"] / profile["activity_level"]


def next_appointment(calendar):
    return next(calendar)


def match(profiles):
    matches = []
    errors = []
    for profile in profiles:
        record = {"name": profile.get("name", "unknown")}

        try:
            record["preference"] = read_preference(profile)
        except IndexError as err:
            errors.append("Preference: %s" % err)
            continue

        try:
            record["age"] = parse_age(profile)
        except ValueError as err:
            errors.append("Age: %s" % err)
            continue

        try:
            record["temperament"] = lookup_temperament(profile)
        except KeyError as err:
            errors.append("Breed: %s" % err)
            continue

        try:
            record["space"] = space_per_energy(profile)
        except ZeroDivisionError as err:
            errors.append("Space: %s" % err)
            continue

        try:
            record["visit"] = next_appointment(profile["calendar"])
        except StopIteration as err:
            errors.append("Visit: %s" % err)
            continue

        try:
            record["personality"] = profile["personality"].capitalize()
        except AttributeError as err:
            errors.append("Personality: %s" % err)
            continue

        try:
            record["fee"] = float(profile["fee"])
        except TypeError as err:
            errors.append("Fee: %s" % err)
            continue

        try:
            handle = open(profile["medical_record"])
        except IOError as err:
            errors.append("Record: %s" % err)
            continue
        try:
            record["notes"] = handle.read().strip()
        finally:
            handle.close()

        matches.append(record)
    return matches, errors


def main():
