RATES = {"BTC": 64000.0, "ETH": 3400.0, "USDT": 1.0}


def validate(trades):
    valid = []
    errors = []
    for trade in trades:
        log = []
        record = {}

        try:
            record["wallet"] = trade["wallets"][3]
        except IndexError as err:
            log.append("Wallet: %s" % err)

        try:
            record["amount"] = int(trade["amount"])
        except ValueError as err:
            log.append("Amount: %s" % err)

        try:
            record["rate"] = RATES[trade["token"]]
        except KeyError as err:
            log.append("Token: %s" % err)

        try:
            record["fee_per_byte"] = trade["gas_limit"] / trade["byte_size"]
        except ZeroDivisionError as err:
            log.append("Fee: %s" % err)

        try:
            record["block"] = next(trade["chain"])
        except StopIteration as err:
            log.append("Block: %s" % err)

        try:
            record["signature"] = trade["signature"].strip()
        except AttributeError as err:
            log.append("Signature: %s" % err)

        try:
            record["nonce"] = float(trade["nonce"])
        except TypeError as err:
            log.append("Nonce: %s" % err)

        try:
            handle = open(trade["ledger"])
        except IOError as err:
            log.append("Ledger: %s" % err)
        else:
            record["ledger_lines"] = len(handle.readlines())
            handle.close()

        errors.append(log)
        if not log:
            valid.append(record)
    return valid, errors


def report(valid, errors):
    lines = ["%d valid trade(s)" % len(valid)]
    for record in valid:
        lines.append("  %s %d @ %.2f" % (record["wallet"], record["amount"],
                                         record["rate"]))
    for index, log in enumerate(errors):
        for message in log:
            lines.append("  trade %d -> %s" % (index, message))
    return "\n".join(lines)


def main():
    trades = [
        {"wallets": ["0xa", "0xb", "0xc", "0xd"], "amount": "250",
         "token": "ETH", "gas_limit": 21000, "byte_size": 250,
         "chain": iter([991, 992]), "signature": "  sig-a ",
         "nonce": 7, "ledger": __file__},
        {"wallets": ["0xa", "0xb"], "amount": "12.5", "token": "DOGE",
         "gas_limit": 21000, "byte_size": 0, "chain": iter([]),
         "signature": None, "nonce": None, "ledger": "no-such-ledger.dat"},
    ]
    valid, errors = validate(trades)
    print(report(valid, errors))


if __name__ == "__main__":
    main()

