def split_record(line):
    """Split a comma separated text record into exactly eight text fields."""
    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 8:
        raise ValueError("expected 8 fields, got %d" % len(parts))
    return parts


def analyze(record):
    """Convert the eight text fields of a planetary record into typed values."""
    values = []
    errors = []

    try:
        values.append(float(record[0]))
    except ValueError as err:
        values.append(0.0)
        errors.append("surface temperature: %s" % err)

    try:
        values.append(int(record[1]))
    except ValueError as err:
        values.append(0)
        errors.append("moon count: %s" % err)

    try:
        values.append(float(record[2]))
    except ValueError as err:
        values.append(1.0)
        errors.append("atmospheric pressure: %s" % err)

    try:
        values.append(float(record[3]))
    except ValueError as err:
        values.append(365.25)
        errors.append("orbital period: %s" % err)

    try:
        values.append(float(record[4]))
    except ValueError as err:
        values.append(23.5)
        errors.append("axial tilt: %s" % err)

    try:
        values.append(bool(int(record[5])))
    except ValueError as err:
        values.append(False)
        errors.append("ring presence: %s" % err)

    try:
        values.append(float(record[6]))
    except ValueError as err:
        values.append(0.5)
        errors.append("magnetic field strength: %s" % err)

    try:
        values.append(float(record[7]))
    except ValueError as err:
        values.append(5.5)
        errors.append("core density: %s" % err)

    return (values, errors)


def format_report(values, errors):
    lines = ["values: %r" % (values,)]
    if errors:
        lines.append("errors (%d):" % len(errors))
        for message in errors:
            lines.append("  - %s" % message)
    else:
        lines.append("errors: none")
    return "\n".join(lines)


def main():
    raw_records = [
        "a, a, a, a, a, a, a, a",
        "288.0, 1, 1.0, 365.25, 23.44, 0, 0.31, 5.51",
        "165.0, 14, 1.5, 60190.0, 28.3, 1",
    ]
    for line in raw_records:
        print("record: %s" % line)
        try:
            record = split_record(line)
        except ValueError as err:
            print("malformed record: %s\n" % err)
            continue
        values, errors = analyze(record)
        print(format_report(values, errors) + "\n")


if __name__ == "__main__":
    main()

