    except (ValueError, TypeError, IndexError) as err:
        values.append(2.0)
        issues.append("ping delay: %s" % err)
    try:
        values.append(float(telemetry[6]))
    except (ValueError, TypeError, IndexError) as err:
        values.append(0.0)
        issues.append("hull stress: %s" % err)
    try:
        values.append(int(telemetry[7]))
    except (ValueError, TypeError, IndexError) as err:
        values.append(0)
        issues.append("particle count: %s" % err)
    return values, issues


def format_report(values, issues, depth_limit):
    lines = []
    for name, value in zip(FIELD_NAMES, values):
        lines.append("  %-20s %s" % (name, value))
    try:
        ratio = "%.3f" % (values[6] / float(values[4]))
    except ZeroDivisionError as err:
        ratio = "unavailable (%s)" % err
    lines.append("  stress per battery percent: %s" % ratio)
    if values[0] > depth_limit:
        lines.append("  ALERT: depth %.1f exceeds limit %.1f" % (values[0], depth_limit))
    if issues:
        lines.append("  %d conversion issue(s):" % len(issues))
        for issue in issues:
            lines.append("    - %s" % issue)
    return "\n".join(lines) + "\n"


def main(argv):
    depth_limit = 6000.0
    if len(argv) > 1:
        try:
            depth_limit = float(argv[1])
        except ValueError as err:
            sys.stderr.write("bad depth limit, keeping %.1f (%s)\n" % (depth_limit, err))
    stream = sys.stdin
    if len(argv) > 2:
        try:
            stream = open(argv[2])
        except IOError as err:
            sys.stderr.write("cannot read telemetry log: %s\n" % err)
            return 1
    count = 0
    for line in stream:
        line = line.strip()
        if not line:
            continue
        count += 1
        values, issues = parse([field.strip() for field in line.split(",")])
        sys.stdout.write("entry %d\n" % count)
        sys.stdout.write(format_report(values, issues, depth_limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

