import sys


def _density(raw, failures):
    try:
        return float(raw) * 3.14
    except ValueError as err:
        failures.append("dragon scale density: %s" % err)
        return 10.0


def _tears(raw, failures):
    try:
        return int(raw.replace("drops", "").strip())
    except ValueError as err:
        failures.append("mermaid tear volume: %s" % err)
        return 1


def _ash(raw, failures):
    try:
        return float(raw.split(" ")[0]) / 2
    except ValueError as err:
        failures.append("phoenix ash weight: %s" % err)
        return 5.0


def _purity(raw, failures):
    try:
        return float(raw.replace("%", "")) / 100
    except ValueError as err:
        failures.append("goblin gold purity: %s" % err)
        return 0.9


def _hair(raw, failures):
    try:
        return int(raw) - 5
    except ValueError as err:
        failures.append("troll hair length: %s" % err)
        return 0


def _glow(raw, failures):
    try:
        return int(raw, 16)
    except ValueError as err:
        failures.append("fairy dust glow: %s" % err)
        return 255


def _speed(raw, failures):
    try:
        return float(raw) * 60
    except ValueError as err:
        failures.append("stirring speed: %s" % err)
        return 30.0


def _time(raw, failures):
    try:
        return int(raw[-1]) ** 2
    except IndexError as err:
        failures.append("brewing time: %s" % err)
    except ValueError as err:
        failures.append("brewing time: %s" % err)
    return 16


def brew(ingredients):
    failures = []
    try:
        scale, tear, ash, gold, hair, dust, stir, clock = ingredients[:8]
    except ValueError as err:
        failures.append("ingredient list: %s" % err)
        return ([10.0, 1, 5.0, 0.9, 0, 255, 30.0, 16], failures)
    stats = [_density(scale, failures), _tears(tear, failures),
             _ash(ash, failures), _purity(gold, failures),
             _hair(hair, failures), _glow(dust, failures),
             _speed(stir, failures), _time(clock, failures)]
    return (stats, failures)


def report(stats, failures):
    labels = ["density", "tears", "ash", "purity", "hair", "glow", "rpm", "time"]
    lines = []
    for index in range(len(labels)):
        lines.append("%s = %s" % (labels[index], stats[index]))
    for message in failures:
        lines.append("failed: " + message)
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        ingredients = argv[1:]
    else:
        ingredients = ["bad"] * 8
    stats, failures = brew(ingredients)
    print(report(stats, failures))


if __name__ == "__main__":
    main(sys.argv)

