import math


def parse_qubit_count(raw):
    try:
        return int(raw) * 8, None
    except ValueError as err:
        return 64, str(err)


def parse_entanglement(raw):
    try:
        return 1.0 - float(raw), None
    except ValueError as err:
        return 0.5, str(err)


def parse_decoherence(raw):
    try:
        return float(raw.replace("ms", "").strip()), None
    except ValueError as err:
        return 10.0, str(err)


def parse_fidelity(raw):
    try:
        return float(raw.replace(",", ".")), None
    except ValueError as err:
        return 0.99, str(err)


def parse_temperature(raw):
    try:
        return float(raw) / 1000.0, None
    except ValueError as err:
        return 0.01, str(err)


def parse_laser_frequency(raw):
    parts = raw.split("-")
    try:
        return float(parts[1]), None
    except IndexError as err:
        return 500.0, str(err)
    except ValueError as err:
        return 500.0, str(err)


def parse_correction_level(raw):
    try:
        return int(raw, 2), None
    except ValueError as err:
        return 3, str(err)


def parse_superpositions(raw):
    try:
        return math.sqrt(float(raw)), None
    except ValueError as err:
        return 1.0, str(err)


def initialize(parameters):
    parsers = [parse_qubit_count, parse_entanglement, parse_decoherence,
               parse_fidelity, parse_temperature, parse_laser_frequency,
               parse_correction_level, parse_superpositions]
    states = []
    diagnostics = []
    for index, parser in enumerate(parsers):
        value, message = parser(parameters[index])
        states.append(value)
        if message is not None:
            diagnostics.append(message)
    return states, diagnostics


def report(parameters):
    states, diagnostics = initialize(parameters)
    lines = ["states: %s" % (states,)]
    for message in diagnostics:
        lines.append("diagnostic: %s" % message)
    return "\n".join(lines)


def main():
    print(report(["q", "q", "q", "q", "q", "q", "q", "q"]))
    print(report(["4", "0.25", "12.5ms", "0,995", "15", "IR-780.2", "1011", "9"]))


if __name__ == "__main__":
    main()

