def parse_mutation_rate(raw, log):
    try:
        return float(raw) * 100.0
    except (ValueError, TypeError) as err:
        log.append("mutation rate: %s" % err)
        return 5.0


def parse_base_pairs(raw, log):
    try:
        return int(raw.replace(",", ""))
    except AttributeError as err:
        log.append("base pairs: %s" % err)
    except ValueError as err:
        log.append("base pairs: %s" % err)
    return 1000000


def parse_helix_stability(raw, log):
    try:
        left, right = raw.split("/")
        return float(left) / float(right)
    except ValueError as err:
        log.append("helix stability: %s" % err)
    except ZeroDivisionError as err:
        log.append("helix stability: %s" % err)
    except AttributeError as err:
        log.append("helix stability: %s" % err)
    return 1.0


def parse_radiation_resistance(raw, log):
    try:
        return int(raw.lower().replace("rads", "").strip())
    except AttributeError as err:
        log.append("radiation resistance: %s" % err)
    except ValueError as err:
        log.append("radiation resistance: %s" % err)
    return 10


def parse_regeneration_speed(raw, log):
    try:
        return float(raw) + 2.5
    except (ValueError, TypeError) as err:
        log.append("regeneration speed: %s" % err)
        return 0.0


def parse_telomere_length(raw, log):
    try:
        return int(raw, 16)
    except (ValueError, TypeError) as err:
        log.append("telomere length: %s" % err)
        return 4000


def parse_aggression_factor(raw, log):
    try:
        return float(raw[:3])
    except TypeError as err:
        log.append("aggression factor: %s" % err)
    except ValueError as err:
        log.append("aggression factor: %s" % err)
    return 1.0


def parse_adaptation_index(raw, log):
    try:
        value = float(raw)
    except (ValueError, TypeError) as err:
        log.append("adaptation index: %s" % err)
        return 4.0
    return value * value


def sequence(markers):
    log = []
    parsers = [parse_mutation_rate, parse_base_pairs, parse_helix_stability,
               parse_radiation_resistance, parse_regeneration_speed,
               parse_telomere_length, parse_aggression_factor,
               parse_adaptation_index]
    processed = []
    for index, parser in enumerate(parsers):
        try:
            raw = markers[index]
        except IndexError as err:
            log.append("marker %d missing: %s" % (index, err))
            raw = None
        processed.append(parser(raw, log))
    return processed, log


def report(markers):
    values, log = sequence(markers)
    names = ["mutation rate", "base pairs", "helix stability",
             "radiation resistance", "regeneration speed", "telomere length",
             "aggression factor", "adaptation index"]
    lines = []
    for name, value in zip(names, values):
        lines.append("%-22s %s" % (name, value))
    lines.append("errors logged: %d" % len(log))
    return "\n".join(lines)


def main():
    print(report(["m", "m", "m", "m", "m", "m", "m", "m"]))
    print(report(["0.031", "3,200,000", "7.5/2.5", "480 rads", "1.25", "1f40",
                  "0.85x", "1.5"]))


if __name__ == "__main__":
    main()

