        return 5.0


def parse_healing(text, errors):
    try:
        return int(text, 2)
    except ValueError as err:
        errors.append(str(err))
        return 1


def parse_telepathy(text, errors):
    try:
        return int(text.replace(",", ""))
    except ValueError as err:
        errors.append(str(err))
        return 100


def parse_elemental(text, errors):
    try:
        return math.sqrt(float(text))
    except ValueError as err:
        errors.append(str(err))
        return 1.0


def parse_sidekicks(text, errors):
    try:
