        return [], errors
    levels = [parse_lifting(lift, errors),
              parse_flight(flight, errors),
              parse_laser(laser, errors),
              parse_armor(armor, errors),
              parse_healing(heal, errors),
              parse_telepathy(tele, errors),
              parse_elemental(elem, errors),
              parse_sidekicks(side, errors)]
    return levels, errors


def format_report(levels, errors):
