def parse_tip_wear(text):
    try:
        return 100 - float(text), None
    except ValueError as err:
        return 50.0, "diamond tip wear: %s" % err


def parse_temperature(text):
    try:
        readings = [float(part) for part in text.split("-")]
    except ValueError as err:
        return 100.0, "subterranean temperature: %s" % err
    return max(readings), None


def parse_seismic(text):
    try:
        return int(text, 16), None
    except ValueError as err:
        return 0, "seismic activity: %s" % err


def parse_coolant(text):
    try:
        return float(text.replace("p", "")), None
    except ValueError as err:
        return 30.0, "coolant pressure: %s" % err


def parse_gold(text):
    try:
        return float(text) * 31.1, None
    except ValueError as err:
        return 0.0, "gold detected: %s" % err


def parse_depth(text):
    try:
        return int(text[-3:]), None
    except ValueError as err:
        return 1000, "shaft depth: %s" % err


