    try:
        rpm, density, wear, temp, seismic, coolant, gold, depth = outputs
    except ValueError as err:
        raise ValueError("expected eight sensor outputs (%s)" % err)
    parsers = [
        (parse_rpm, rpm), (parse_density, density), (parse_tip_wear, wear),
        (parse_temperature, temp), (parse_seismic, seismic),
        (parse_coolant, coolant), (parse_gold, gold), (parse_depth, depth),
    ]
