LABELS = ["iron content", "ice volume", "rare earth minerals", "surface radiation",
          "structural integrity", "orbital velocity", "rotation period", "mass estimate"]


def parse_iron(text, errors):
    try:
        return float(text) * 1000.0
    except ValueError as err:
        errors.append("iron content: %s" % err)
        return 0.0


def parse_ice(text, errors):
    cleaned = text.replace("cubic", "").strip()
    try:
        return float(cleaned)
    except ValueError as err:
        errors.append("ice volume: %s" % err)
        return 100.0


def parse_minerals(text, errors):
    try:
        return int(text) // 5
    except ValueError as err:
        errors.append("rare earth minerals: %s" % err)
        return 10


def parse_radiation(text, errors):
    try:
        return float(text.split("/")[0])
    except ValueError as err:
        errors.append("surface radiation: %s" % err)
        return 2.0


def parse_integrity(text, errors):
    try:
        return int(text, 2)
    except ValueError as err:
        errors.append("structural integrity: %s" % err)
        return 1


def parse_velocity(text, errors):
    try:
        return float(text.replace(",", ""))
    except ValueError as err:
        errors.append("orbital velocity: %s" % err)
        return 20.0


def parse_rotation(text, errors):
    try:
        return float(text) * 24.0
    except ValueError as err:
        errors.append("rotation period: %s" % err)
        return 12.0


def parse_mass(text, errors):
    digits = ""
    for char in text:
        if char.isdigit():
            digits += char
    try:
        return int(digits[:2])
    except ValueError as err:
        errors.append("mass estimate: %s" % err)
        return 50


def calculate(scans):
    errors = []
    values = []
    parsers = [parse_iron, parse_ice, parse_minerals, parse_radiation,
               parse_integrity, parse_velocity, parse_rotation, parse_mass]
    for index in range(len(parsers)):
        try:
            raw = scans[index]
        except IndexError as err:
            errors.append("%s: missing scan (%s)" % (LABELS[index], err))
            raw = ""
        values.append(parsers[index](raw, errors))
    return values, errors


def format_report(values, errors):
    lines = []
    for index in range(len(values)):
        lines.append("%-22s %s" % (LABELS[index], values[index]))
    lines.append("errors: %d" % len(errors))
    for message in errors:
        lines.append("  - %s" % message)
    return "\n".join(lines)


def main():
    scans = sys.argv[1:]
    if not scans:
        scans = ["a", "a", "a", "a", "a", "a", "a", "a"]
    values, errors = calculate(scans)
    print(format_report(values, errors))


if __name__ == "__main__":
    main()

