import sys


def parse_purity(text, warnings):
    try:
        return float(text) / 100.0
    except ValueError as err:
        warnings.append("silver purity: %s" % err)
        return 0.9


def parse_stakes(text, warnings):
    try:
        return int(text.replace("ash", ""))
    except ValueError as err:
        warnings.append("wooden stakes: %s" % err)
        return 5


def parse_holy_water(text, warnings):
    try:
        return float(text) * 3.78
    except ValueError as err:
        warnings.append("holy water: %s" % err)
        return 1.0


def parse_garlic(text, warnings):
    try:
        return sum([int(part) for part in text.split(" ")])
    except ValueError as err:
        warnings.append("garlic cloves: %s" % err)
        return 10


def parse_fuse(text, warnings):
    try:
        return int(text, 16)
    except ValueError as err:
        warnings.append("grenade fuse: %s" % err)
        return 3


def parse_tension(text, warnings):
    try:
        return float(text.replace("t", ""))
    except ValueError as err:
        warnings.append("crossbow tension: %s" % err)
        return 150.0


def parse_reflectivity(text, warnings):
    try:
        value = float(text)
    except ValueError as err:
        warnings.append("mirror reflectivity: %s" % err)
        return 0.8
    return value * value


def parse_amulets(text, warnings):
    try:
        return int(text[-1])
    except (ValueError, IndexError) as err:
        warnings.append("blessed amulets: %s" % err)
        return 1


def prepare(inputs):
    warnings = []
    arsenal = [
        parse_purity(inputs[0], warnings),
        parse_stakes(inputs[1], warnings),
        parse_holy_water(inputs[2], warnings),
        parse_garlic(inputs[3], warnings),
        parse_fuse(inputs[4], warnings),
        parse_tension(inputs[5], warnings),
        parse_reflectivity(inputs[6], warnings),
        parse_amulets(inputs[7], warnings),
    ]
    return arsenal, warnings


def combat_rating(arsenal, warnings):
    try:
        return arsenal[0] * arsenal[5] / arsenal[4]
    except ZeroDivisionError as err:
        warnings.append("grenade fuse too short: %s" % err)
        return 0.0


def format_report(arsenal, warnings):
    lines = ["arsenal: %s" % arsenal]
    lines.append("combat rating: %.2f" % combat_rating(arsenal, warnings))
    for message in warnings:
        lines.append("warning: %s" % message)
    return "\n".join(lines)


def main():
    inputs = sys.argv[1:9]
    while len(inputs) < 8:
        inputs.append("v")
    arsenal, warnings = prepare(inputs)
    print(format_report(arsenal, warnings))


if __name__ == "__main__":
    main()

