def _diameter(raw):
    try:
        return float(raw) * 10.0, None
    except ValueError as err:
        return 5.0, str(err)


def _luster(raw):
    try:
        return 10.0 - float(raw), None
    except ValueError as err:
        return 5.0, str(err)


def _color_rarity(raw):
    try:
        return int(raw, 2), None
    except ValueError as err:
        return 1, str(err)


def _surface_flaws(raw):
    try:
        return int(raw.replace("tiny", "").strip()), None
    except ValueError as err:
        return 0, str(err)


def _origin_depth(raw):
    parts = raw.split("-")
    try:
        depths = [float(part) for part in parts]
    except ValueError as err:
        return 50.0, str(err)
    return sum(depths) / len(depths), None


def _magical_resonance(raw):
    try:
        return float(raw.replace("m", "")), None
    except ValueError as err:
        return 0.0, str(err)


def _weight(raw):
    try:
        return float(raw) / 0.2, None
    except ValueError as err:
        return 1.0, str(err)


def _age(raw):
    try:
        return int(raw[:3]), None
    except ValueError as err:
        return 100, str(err)


def appraise(metrics):
    readers = [_diameter, _luster, _color_rarity, _surface_flaws,
               _origin_depth, _magical_resonance, _weight, _age]
    if len(metrics) != len(readers):
        raise ValueError("expected %d metrics, got %d" % (len(readers), len(metrics)))
    appraisal = []
    rejects = []
    for reader, raw in zip(readers, metrics):
        value, message = reader(raw)
        appraisal.append(value)
        if message is not None:
            rejects.append(message)
    return appraisal, rejects


def parse_metrics(text):
    return [field.strip() for field in text.split(",")]


def format_report(appraisal, rejects):
    lines = ["appraisal: " + repr(appraisal)]
    for message in rejects:
        lines.append("  rejected: " + message)
    return "\n".join(lines)


def main():
    samples = ["p, p, p, p, p, p, p, p",
               "7.5, 2.0, 1011, tiny 3, 40-60, 12m, 1.4, 250 years",
               "3.0, 1.0, 101"]
    for text in samples:
        try:
            appraisal, rejects = appraise(parse_metrics(text))
        except ValueError as err:
            print("cannot appraise %r: %s" % (text, err))
            continue
        print(format_report(appraisal, rejects))


if __name__ == "__main__":
    main()

