import math
import re
import sys

LABELS = ("gold coins", "silver chalices", "ruby weight", "sapphire clarity",
          "emerald count", "diamond cuts", "cursed artifacts", "ancient scrolls")


def count(tallies):
    ignored = []

    try:
        gold = int(tallies[0]) * 10
    except ValueError as err:
        ignored.append(str(err))
        gold = 0

    try:
        silver = int(tallies[1].replace("s", ""))
    except ValueError as err:
        ignored.append(str(err))
        silver = 0

    try:
        rubies = float(tallies[2]) * 2.2
    except ValueError as err:
        ignored.append(str(err))
        rubies = 1.0

    try:
        clarity = float(tallies[3].split("%")[0]) / 100.0
    except ValueError as err:
        ignored.append(str(err))
        clarity = 0.5

    try:
        emeralds = int(tallies[4], 0)
    except ValueError as err:
        ignored.append(str(err))
        emeralds = 10

    try:
        cuts = int(tallies[5].replace("D", "0"))
    except ValueError as err:
        ignored.append(str(err))
        cuts = 50

    try:
        cursed = math.sqrt(float(tallies[6]))
    except ValueError as err:
        ignored.append(str(err))
        cursed = 0.0

    try:
        scrolls = int(re.findall(r"\d", tallies[7])[-1])
    except IndexError as err:
        ignored.append(str(err))
        scrolls = 1

    return ([gold, silver, rubies, clarity, emeralds, cuts, cursed, scrolls], ignored)


def load_tallies(text):
    parts = [part.strip() for part in text.split(",")]
    if len(parts) != 8:
        raise ValueError("expected 8 tallies, got %d" % len(parts))
    return parts


def format_hoard(totals, ignored):
    lines = []
    for label, value in zip(LABELS, totals):
        lines.append("%-17s %s" % (label + ":", value))
    lines.append("ignored: %d" % len(ignored))
    for message in ignored:
        lines.append("  - %s" % message)
    return "\n".join(lines)


def main(argv):
    tallies = ["d", "d", "d", "d", "d", "d", "d", "d"]
    if len(argv) > 1:
        try:
            tallies = load_tallies(argv[1])
        except ValueError as err:
            print("bad tally list (%s), using the sample hoard" % err)
    totals, ignored = count(tallies)
    print(format_hoard(totals, ignored))


if __name__ == "__main__":
    main(sys.argv)

