def _saucer_diameter(raw, debunk):
    try:
        return float(raw) * 3.28
    except ValueError as err:
        debunk.append("saucer diameter: %s" % err)
        return 30.0


def _hover_duration(raw, debunk):
    try:
        return float(raw.replace("min", ""))
    except ValueError as err:
        debunk.append("hover duration: %s" % err)
        return 5.0


def _light_intensity(raw, debunk):
    try:
        return int(raw) // 10
    except ValueError as err:
        debunk.append("light intensity: %s" % err)
        return 100


def _flight_speed(raw, debunk):
    try:
        return float(raw.split(" ")[0]) ** 2
    except (ValueError, IndexError) as err:
        debunk.append("flight speed: %s" % err)
        return 1000.0


def _abduction_probability(raw, debunk):
    try:
        return int(raw, 2)
    except ValueError as err:
        debunk.append("abduction probability: %s" % err)
        return 0


def _radar_interference(raw, debunk):
    try:
        return float(raw.replace("r", ""))
    except ValueError as err:
        debunk.append("radar interference: %s" % err)
        return 50.0


def _crop_circle_radius(raw, debunk):
    try:
        return float(raw) * 3.14
    except ValueError as err:
        debunk.append("crop circle radius: %s" % err)
        return 10.0


def _alien_entities(raw, debunk):
    try:
        return int(raw[0])
    except (ValueError, IndexError) as err:
        debunk.append("alien entities: %s" % err)
        return 0


def validate(observations):
    if len(observations) != 8:
        raise ValueError("a sighting report needs exactly 8 observations")
    debunk = []
    data = [
        _saucer_diameter(observations[0], debunk),
        _hover_duration(observations[1], debunk),
        _light_intensity(observations[2], debunk),
        _flight_speed(observations[3], debunk),
        _abduction_probability(observations[4], debunk),
        _radar_interference(observations[5], debunk),
        _crop_circle_radius(observations[6], debunk),
        _alien_entities(observations[7], debunk),
    ]
    return data, debunk


def parse_line(text):
    return [field.strip() for field in text.split(",")]


def main():
    reports = [
        "u, u, u, u, u, u, u, u",
        "12.5, 7min, 880, 430.5 kph, 1011, 33r, 4.2, 3 greys",
        "12.5, 7min, 880",
    ]
    for line in reports:
        print("report: " + line)
        try:
            data, debunk = validate(parse_line(line))
        except ValueError as err:
            print("  rejected: %s" % err)
            continue
        print("  data: %s" % data)
        for message in debunk:
            print("  debunked -> %s" % message)


if __name__ == "__main__":
    main()

