    try:
        return float(clue.replace("q", "")), None
    except ValueError as err:
        return 5.0, "quicksand depth unreadable: %s" % err


def buried_depth(clue):
    try:
        return float(clue) / 3.0, None
    except ValueError as err:
        return 2.0, "buried depth unreadable: %s" % err


def pirate_skeletons(clue):
    digits = "".join([ch for ch in clue if ch.isdigit()])
    try:
        return int(digits[-1:]), None
    except ValueError as err:
        return 1, "pirate skeletons unreadable: %s" % err


def decipher(clues):
    readers = [paces_north, degrees_east, island_longitude, parrot_squawks,
               monkey_traps, quicksand_depth, buried_depth, pirate_skeletons]
    directions = []
    unreadable = []
    for reader, clue in zip(readers, clues):
        value, problem = reader(clue)
        directions.append(value)
        if problem is not None:
            unreadable.append(problem)
    return directions, unreadable


def report(clues):
    directions, unreadable = decipher(clues)
    lines = ["directions: " + repr(directions)]
    for problem in unreadable:
        lines.append("  ! " + problem)
    return "\n".join(lines)


