import sys


def parse_shadow(value, penalties):
    try:
        return float(value) * 100.0
    except ValueError as err:
        penalties.append(str(err))
        return 50.0


def parse_footsteps(value, penalties):
    try:
        return float(value.replace("db", ""))
    except ValueError as err:
        penalties.append(str(err))
        return 20.0


def parse_guards(value, penalties):
    try:
        return int(value) // 2
    except ValueError as err:
        penalties.append(str(err))
        return 0


def parse_jumps(value, penalties):
    try:
        return max([int(part) for part in value.split("-")])
    except ValueError as err:
        penalties.append(str(err))
        return 5


def parse_shurikens(value, penalties):
    try:
        return int(value, 2)
    except ValueError as err:
        penalties.append(str(err))
        return 0


def parse_smoke(value, penalties):
    try:
        return int(value.replace("s", "0"))
    except ValueError as err:
        penalties.append(str(err))
        return 1


def parse_time(value, penalties):
    try:
        return 60.0 - float(value)
    except ValueError as err:
        penalties.append(str(err))
        return 30.0


def parse_detected(value, penalties):
    try:
        return int(value[0])
    except ValueError as err:
        penalties.append(str(err))
        return 0


def grade(criteria):
    penalties = []
    try:
        shadow, steps, guards, jumps, stars, smoke, elapsed, detected = criteria
    except ValueError as err:
        raise ValueError("eight criteria are required (%s)" % err)
    scores = [parse_shadow(shadow, penalties),
              parse_footsteps(steps, penalties),
              parse_guards(guards, penalties),
              parse_jumps(jumps, penalties),
              parse_shurikens(stars, penalties),
              parse_smoke(smoke, penalties),
              parse_time(elapsed, penalties),
              parse_detected(detected, penalties)]
    return scores, penalties


def format_report(scores, penalties, threshold):
    total = sum(scores)
    lines = ["scores: %s" % scores, "total: %.2f" % total]
    for message in penalties:
        lines.append("penalty: %s" % message)
    lines.append("verdict: %s" % ("PASS" if total >= threshold else "FAIL"))
    return "\n".join(lines)


def main(argv):
    threshold = 100.0
    if len(argv) > 8:
        try:
            threshold = float(argv[8])
        except ValueError as err:
            sys.stderr.write("bad threshold, using %.1f (%s)\n" % (threshold, err))
    criteria = argv[:8] if len(argv) >= 8 else ["n"] * 8
    scores, penalties = grade(criteria)
    print(format_report(scores, penalties, threshold))


if __name__ == "__main__":
    main(sys.argv[1:])

