def parse_swish_angle(rune, fizzle):
    try:
        return float(rune) * 3.14
    except ValueError as err:
        fizzle.append(str(err))
        return 3.14

def parse_volume(rune, fizzle):
    try:
        return float(rune.replace("loud", "").strip())
    except ValueError as err:
        fizzle.append(str(err))
        return 10.0

def parse_mana(rune, fizzle):
    try:
        return int(rune) // 5
    except ValueError as err:
        fizzle.append(str(err))
        return 50

def parse_affinity(rune, fizzle):
    try:
        words = rune.split(" ")
        if len(words) < 2:
            raise ValueError("affinity rune %r names no element and intensity" % rune)
        return len(words[0])
    except ValueError as err:
        fizzle.append(str(err))
        return 4

def parse_spark_color(rune, fizzle):
    try:
        return int(rune, 16)
    except ValueError as err:
        fizzle.append(str(err))
        return 255

def parse_height(rune, fizzle):
    try:
        return float(rune.replace("m", ""))
    except ValueError as err:
        fizzle.append(str(err))
        return 1.0

def parse_duration(rune, fizzle):
    try:
        return float(rune) ** 2
    except ValueError as err:
        fizzle.append(str(err))
        return 10.0

def parse_collateral(rune, fizzle):
    try:
        return int(rune.strip()[-1:])
    except ValueError as err:
        fizzle.append(str(err))
        return 0

def check(runes):
    if len(runes) != 8:
        raise ValueError("a cast spell needs exactly eight runes, got %d" % len(runes))
    fizzle = []
    parsers = [parse_swish_angle, parse_volume, parse_mana, parse_affinity,
               parse_spark_color, parse_height, parse_duration, parse_collateral]
    stats = [parse(rune, fizzle) for parse, rune in zip(parsers, runes)]
    return stats, fizzle

def main():
    spells = [["w"] * 8, ["45", "loud 30", "500", "fire 3", "ff", "12m", "4", "damage7"],
              ["10", "loud 5", "200"]]
    for runes in spells:
        try:
            stats, fizzle = check(runes)
        except ValueError as err:
            print("spell rejected: %s" % err)
            continue
        print("stats: %s fizzles: %s" % (stats, fizzle))

if __name__ == "__main__":
    main()

