BRACKETS = {
    "CA": 0.093,
    "NY": 0.0685,
    "TX": 0.0,
}


def parse_income(record, errors):
    try:
        return float(record.get("income", ""))
    except ValueError as err:
        errors.append("income: %s" % err)
        return None


def tax_ratio(record, errors):
    try:
        return float(record.get("tax_paid", 0)) / float(record.get("deductions", 0))
    except ZeroDivisionError as err:
        errors.append("ratio: %s" % err)
        return None


def third_dependent(record, errors):
    dependents = record.get("dependents", [])
    try:
        return dependents[2]
    except IndexError as err:
        errors.append("dependents: %s" % err)
        return None


def lookup_bracket(record, errors):
    try:
        return BRACKETS[record.get("state_code")]
    except KeyError as err:
        errors.append("state: %s" % err)
        return None


def identifier_length(record, errors):
    try:
        return len(record.get("taxpayer_id"))
    except TypeError as err:
        errors.append("taxpayer_id: %s" % err)
        return None


def decode_signature(record, errors):
    try:
        return record.get("signature", b"").decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("signature: %s" % err)
        return None


def check_positive(income, errors):
    try:
        assert income > 0, "declared income must be positive"
        return True
    except AssertionError as err:
        errors.append("assertion: %s" % err)
        return False


def read_document(record, errors):
    try:
        handle = open(record.get("supporting_document", ""), "rb")
    except OSError as err:
        errors.append("document: %s" % err)
        return None
    try:
        return len(handle.read())
    finally:
        handle.close()


def process_tax_returns(records):
    valid = []
    errors = []
    for record in records:
        income = parse_income(record, errors)
        if income is None:
            continue
        parsed = {
            "income": income,
            "positive": check_positive(income, errors),
            "ratio": tax_ratio(record, errors),
            "third_dependent": third_dependent(record, errors),
            "bracket": lookup_bracket(record, errors),
            "id_length": identifier_length(record, errors),
            "signature": decode_signature(record, errors),
            "document_bytes": read_document(record, errors),
        }
        valid.append(parsed)
    return valid, errors


def main():
    records = [{
        "income": "invalid",
        "tax_paid": 1200,
        "deductions": 0,
        "dependents": ["Ann"],
        "state_code": "ZZ",
        "taxpayer_id": 123456789,
        "signature": b"\xff\xfe",
        "supporting_document": "missing_form.pdf",
    }]
    valid, errors = process_tax_returns(records)
    print("valid returns: %r" % (valid,))
    print("errors: %r" % (errors,))


if __name__ == "__main__":
    main()

