MATERIAL_CODES = {
    "asphalt": 0x01,
    "concrete": 0x02,
    "gravel": 0x03,
    "metal": 0x04,
}


def parse_lidar_distance(raw, errors):
    try:
        return float(raw)
    except ValueError as err:
        errors.append("lidar distance: %s" % err)
        return None


def relative_velocity(speed_delta, time_delta, errors):
    try:
        return speed_delta / time_delta
    except ZeroDivisionError as err:
        errors.append("relative velocity: %s" % err)
        return None


def fourth_reflection(radar, errors):
    try:
        return radar[3]
    except IndexError as err:
        errors.append("radar reflection: %s" % err)
        return None


def material_code(material, errors):
    try:
        return MATERIAL_CODES[material]
    except KeyError as err:
        errors.append("material code: %s" % err)
        return None


def timestamp_length(timestamp, errors):
    try:
        return len(timestamp)
    except TypeError as err:
        errors.append("timestamp length: %s" % err)
        return None


def decode_camera(payload, errors):
    try:
        return payload.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("camera payload: %s" % err)
        return None


def check_confidence(score, errors):
    try:
        assert 0.0 <= score <= 1.0, "confidence %r out of range" % (score,)
        return score
    except AssertionError as err:
        errors.append("confidence: %s" % err)
        return None


def read_cache(path, errors):
    try:
        handle = open(path, "rb")
    except OSError as err:
        errors.append("cache file: %s" % err)
        return None
    try:
        return len(handle.read())
    finally:
        handle.close()


def merge_sensor_readings(readings):
    merged = []
    errors = []
    for reading in readings:
        record = {
            "distance": parse_lidar_distance(reading.get("lidar_distance"), errors),
            "velocity": relative_velocity(reading.get("speed_delta"),
                                          reading.get("time_delta"), errors),
            "reflection": fourth_reflection(reading.get("radar_points", []), errors),
            "material": material_code(reading.get("material"), errors),
            "stamp_length": timestamp_length(reading.get("timestamp"), errors),
            "camera": decode_camera(reading.get("camera_payload", b""), errors),
            "confidence": check_confidence(reading.get("confidence", 0.0), errors),
            "cache_bytes": read_cache(reading.get("cache_path", ""), errors),
        }
        if None not in record.values():
            merged.append(record)
    return merged, errors


def main():
    readings = [{
        "lidar_distance": "12.5",
        "speed_delta": 4.0,
        "time_delta": 0,
        "radar_points": [1.0, 2.0, 3.0, 4.0],
        "material": "asphalt",
        "timestamp": "2026-09-18T10:00:00",
        "camera_payload": b"frame-ok",
        "confidence": 0.93,
        "cache_path": __file__,
    }]
    merged, errors = merge_sensor_readings(readings)
    print("merged: %r" % (merged,))
    print("errors: %r" % (errors,))


if __name__ == "__main__":
    main()

