ZONE_NAMES = {
    "LR": "Living Room",
    "BR": "Bedroom",
    "KT": "Kitchen",
}


def parse_target(command, errors):
    try:
        return float(command.get("target"))
    except ValueError as err:
        errors.append(str(err))
        return None


def cooling_efficiency(command, errors):
    try:
        return command["temp_drop"] / command["power"]
    except ZeroDivisionError as err:
        errors.append(str(err))
        return None


def second_override(command, errors):
    try:
        return command["schedule"][1]
    except IndexError as err:
        errors.append(str(err))
        return None


def zone_room(command, errors):
    try:
        return ZONE_NAMES[command["zone"]]
    except KeyError as err:
        errors.append(str(err))
        return None


def serial_length(command, errors):
    try:
        return len(command["serial"])
    except TypeError as err:
        errors.append(str(err))
        return None


def decode_packet(command, errors):
    try:
        return command["packet"].decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append(str(err))
        return None


def check_safe_target(target, errors):
    try:
        assert target is not None and 4.0 <= target <= 32.0, "target outside safe living range"
    except AssertionError as err:
        errors.append(str(err))
        return False
    return True


def read_history(command, errors):
    try:
        handle = open(command["log_path"])
    except OSError as err:
        errors.append(str(err))
        return None
    try:
        return handle.read()
    finally:
        handle.close()


def evaluate(commands):
    schedule = []
    errors = []
    for command in commands:
        target = parse_target(command, errors)
        efficiency = cooling_efficiency(command, errors)
        override = second_override(command, errors)
        room = zone_room(command, errors)
        serial_len = serial_length(command, errors)
        packet = decode_packet(command, errors)
        history = read_history(command, errors)
        if not check_safe_target(target, errors):
            continue
        schedule.append({
            "room": room,
            "target": target,
            "efficiency": efficiency,
            "override": override,
            "serial_digits": serial_len,
            "packet": packet,
            "history_bytes": len(history) if history is not None else 0,
        })
    return schedule, errors


def main():
    commands = [{
        "target": "hot",
        "temp_drop": 3.0,
        "power": 0,
        "schedule": ["07:00-08:00"],
        "zone": "GR",
        "serial": 99123,
        "packet": b"\xff\xfe cold",
        "log_path": "/no/such/thermostat.log",
    }]
    schedule, errors = evaluate(commands)
    print("schedule: %r" % (schedule,))
    for message in errors:
        print("error: %s" % message)


if __name__ == "__main__":
    main()

