CODON_TABLE = {
    "AUG": "Met",
    "GCU": "Ala",
    "UUU": "Phe",
    "GGC": "Gly",
    "UGG": "Trp",
}


def parse_length(raw_length, errors):
    try:
        return int(raw_length)
    except ValueError as err:
        errors.append(str(err))
        return None


def folding_density(mass, volume, errors):
    try:
        return mass / volume
    except ZeroDivisionError as err:
        errors.append(err)
        return None


def fourth_fold_angle(geometry, errors):
    try:
        return geometry[3]
    except IndexError as err:
        errors.append(str(err))
        return None


def translate_codon(codon, table, errors):
    try:
        return table[codon]
    except KeyError as err:
        errors.append(err)
        return None


def marker_length(marker, errors):
    try:
        return len(marker)
    except TypeError as err:
        errors.append(str(err))
        return None


def decode_assay(blob, errors):
    try:
        return blob.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append(str(err))
        return None


def check_energy(energy, errors):
    try:
        assert energy < 0, "folding energy %r is not negative" % (energy,)
        return True
    except AssertionError as err:
        errors.append(str(err))
        return False


def read_data_file(path, errors):
    try:
        handle = open(path, "rb")
    except OSError as err:
        errors.append(err)
        return None
    try:
        return handle.read()
    finally:
        handle.close()


def model_proteins(sequences):
    proteins = []
    errors = []
    for seq in sequences:
        length = parse_length(seq.get("length"), errors)
        if length is None:
            continue
        protein = {"name": seq.get("name"), "length": length}
        protein["density"] = folding_density(seq.get("mass", 0.0), seq.get("volume", 0.0), errors)
        protein["fold_angle"] = fourth_fold_angle(seq.get("geometry", []), errors)
        protein["amino_acid"] = translate_codon(seq.get("codon"), CODON_TABLE, errors)
        protein["marker_length"] = marker_length(seq.get("marker"), errors)
        protein["assay_text"] = decode_assay(seq.get("assay", b""), errors)
        protein["energy_negative"] = check_energy(seq.get("energy", 0.0), errors)
        protein["raw_data"] = read_data_file(seq.get("data_path", ""), errors)
        proteins.append(protein)
    return proteins, errors


def format_report(proteins, errors):
    lines = ["proteins modelled: %d" % len(proteins)]
    for protein in proteins:
        lines.append("  %s len=%d density=%s aa=%s" % (
            protein["name"], protein["length"], protein["density"], protein["amino_acid"]))
    for message in errors:
        lines.append("  error: %s" % (message,))
    return "\n".join(lines)


def main():
    sequences = [{"name": "PRT-1", "length": "long"}]
    proteins, errors = model_proteins(sequences)
    print(format_report(proteins, errors))


if __name__ == "__main__":
    main()

