import json
import sys

DISTRICTS = {
    'D1': 'Riverside',
    'D2': 'Old Town',
    'D3': 'Harbour',
}

DEFAULT_BATCH = [
    {'id': 'L-001', 'intensity': '18.5', 'power': 96.0, 'target_dimming': 0,
     'network': ['L-002', 'L-003'], 'district_code': 'D1',
     'diagnostic_code': 'E-1042', 'hardware': b'lamp-a',
     'voltage': 231.0, 'grid_config': __file__},
    {'id': 'L-004', 'intensity': '42.0', 'power': 110.0, 'target_dimming': 4,
     'network': ['L-005', 'L-006', 'L-007'], 'district_code': 'D3',
     'diagnostic_code': 'E-0007', 'hardware': b'lamp-d',
     'voltage': 228.5, 'grid_config': __file__},
]


def load_batch(path):
    try:
        handle = open(path, 'r')
    except OSError as err:
        sys.stderr.write('cannot open batch file: %s\n' % err)
        return None
    try:
        return json.load(handle)
    except ValueError as err:
        sys.stderr.write('malformed batch file: %s\n' % err)
        return None
    finally:
        handle.close()


def process_sensor(sensor, districts):
    actions = []
    errors = []
    try:
        intensity = float(sensor['intensity'])
    except ValueError as err:
        errors.append(str(err))
        return actions, errors
    try:
        ratio = sensor['power'] / sensor['target_dimming']
    except ZeroDivisionError as err:
        errors.append(str(err))
        return actions, errors
    try:
        neighbor = sensor['network'][1]
    except IndexError as err:
        errors.append(str(err))
        return actions, errors
    try:
        district = districts[sensor['district_code']]
    except KeyError as err:
        errors.append(str(err))
        return actions, errors
    try:
        code_length = len(sensor['diagnostic_code'])
    except TypeError as err:
        errors.append(str(err))
        return actions, errors
    try:
        hardware_label = sensor['hardware'].decode('utf-8')
    except UnicodeDecodeError as err:
        errors.append(str(err))
        return actions, errors
    try:
        assert 200.0 <= sensor['voltage'] <= 250.0, \
            'voltage draw %.1f outside safe band' % sensor['voltage']
    except AssertionError as err:
        errors.append(str(err))
        return actions, errors
    try:
        handle = open(sensor['grid_config'], 'r')
        grid_size = len(handle.read())
        handle.close()
    except OSError as err:
        errors.append(str(err))
        return actions, errors
    actions.append({'id': sensor['id'], 'intensity': intensity,
                    'dim_ratio': ratio, 'neighbor': neighbor,
                    'district': district, 'code_length': code_length,
                    'hardware': hardware_label, 'grid_bytes': grid_size})
    return actions, errors


def process_batch(sensors, districts):
    all_actions = []
    all_errors = []
    for sensor in sensors:
        actions, errors = process_sensor(sensor, districts)
        all_actions.extend(actions)
        all_errors.extend(errors)
    return all_actions, all_errors


def format_report(actions, errors):
    lines = []
    for action in actions:
        lines.append('%s: dim %.2f in %s via %s (%d bytes of grid config)'
                     % (action['id'], action['dim_ratio'], action['district'],
                        action['neighbor'], action['grid_bytes']))
    for message in errors:
        lines.append('ERROR: %s' % message)
    return '\n'.join(lines)


def main(argv):
    if len(argv) > 1:
        sensors = load_batch(argv[1])
        if sensors is None:
            return 1
    else:
        sensors = DEFAULT_BATCH
    actions, errors = process_batch(sensors, DISTRICTS)
    print(format_report(actions, errors))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

