import os

PRIVACY_CODES = {0: "public", 1: "friends-only", 2: "private"}


def analyze_profile(profile):
    metrics = []
    errors = []

    try:
        followers = int(profile.get("followers"))
    except ValueError as err:
        errors.append("follower parse: %s" % err)
    else:
        metrics.append(("followers", followers))

    try:
        rate = profile.get("interactions", 0) / profile.get("posts", 0)
    except ZeroDivisionError as err:
        errors.append("engagement rate: %s" % err)
    else:
        metrics.append(("engagement_rate", rate))

    try:
        mutual = profile.get("friends", [])[3]
    except IndexError as err:
        errors.append("mutual connection: %s" % err)
    else:
        metrics.append(("fourth_mutual", mutual))

    try:
        privacy = PRIVACY_CODES[profile.get("privacy_code")]
    except KeyError as err:
        errors.append("privacy code: %s" % err)
    else:
        metrics.append(("privacy", privacy))

    try:
        token_length = len(profile.get("token"))
    except TypeError as err:
        errors.append("token length: %s" % err)
    else:
        metrics.append(("token_length", token_length))

    try:
        bio = profile.get("bio", b"").decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("bio decode: %s" % err)
    else:
        metrics.append(("bio", bio))

    try:
        assert profile.get("account_age", 0) > 0, "account age must be positive"
    except AssertionError as err:
        errors.append("account age: %s" % err)
    else:
        metrics.append(("account_age", profile.get("account_age")))

    try:
        handle = open(profile.get("avatar_path", ""), "rb")
    except OSError as err:
        errors.append("avatar: %s" % err)
    else:
        metrics.append(("avatar_bytes", len(handle.read())))
        handle.close()

    return metrics, errors


def format_report(profile, metrics, errors):
    lines = ["report for %s" % profile.get("name", "unknown")]
    for name, value in metrics:
        lines.append("  %s = %s" % (name, value))
    for message in errors:
        lines.append("  ERROR %s" % message)
    return "\n".join(lines)


def main():
    profiles = [
        {
            "name": "ana",
            "followers": "1200",
            "interactions": 480,
            "posts": 24,
            "friends": ["bo", "cy", "di", "ed"],
            "privacy_code": 1,
            "token": "abc-123-xyz",
            "bio": b"hello \xff world",
            "account_age": 5,
            "avatar_path": os.path.join(os.path.dirname(__file__) or ".", "ana.png"),
        },
        {
            "name": "bruno",
            "followers": "many",
            "interactions": 10,
            "posts": 0,
            "friends": ["ana"],
            "privacy_code": 9,
            "token": 99887766,
            "bio": b"traveler",
            "account_age": -1,
            "avatar_path": "",
        },
    ]
    for profile in profiles:
        metrics, errors = analyze_profile(profile)
        print(format_report(profile, metrics, errors))


if __name__ == "__main__":
    main()

