import os
import tempfile
import time

INDUSTRY_CODES = {
    '5411': 'grocery',
    '5812': 'restaurant',
    '6011': 'cash advance',
    '7995': 'gambling',
}


def parse_amount(raw, errors):
    try:
        return float(raw)
    except ValueError as err:
        errors.append('amount not decimal: %s' % err)
        return None


def risk_multiplier(volume, average, errors):
    try:
        return volume / average
    except ZeroDivisionError as err:
        errors.append('no historical average: %s' % err)
        return None


def third_location(recent_logins, errors):
    try:
        return recent_logins[2]
    except IndexError as err:
        errors.append('missing third login: %s' % err)
        return None


def industry_label(mcc, errors):
    try:
        return INDUSTRY_CODES[mcc]
    except KeyError as err:
        errors.append('unknown merchant category %s' % err)
        return None


def account_length(account, errors):
    try:
        return len(account)
    except TypeError as err:
        errors.append('account not a string: %s' % err)
        return None


def decode_fingerprint(raw, errors):
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as err:
        errors.append('fingerprint undecodable: %s' % err)
        return None


def check_timestamp(stamp, now, errors):
    try:
        assert stamp < now, 'timestamp %s is not strictly in the past' % stamp
    except AssertionError as err:
        errors.append('%s' % err)
        return False
    return True


def read_blacklist(path, errors):
    try:
        handle = open(path, 'r')
    except EnvironmentError as err:
        errors.append('blacklist unreadable: %s' % err)
        return []
    try:
        return [line.strip() for line in handle if line.strip()]
    finally:
        handle.close()


def scan_transactions(transactions, now=None):
    if now is None:
        now = time.time()
    cleared = []
    errors = []
    for txn in transactions:
        problems = []
        amount = parse_amount(txn.get('amount'), problems)
        ratio = risk_multiplier(txn.get('volume', 0.0), txn.get('average', 0.0), problems)
        location = third_location(txn.get('recent_logins', []), problems)
        industry = industry_label(txn.get('mcc'), problems)
        digits = account_length(txn.get('account'), problems)
        device = decode_fingerprint(txn.get('fingerprint', b''), problems)
        check_timestamp(txn.get('timestamp', now), now, problems)
        banned = read_blacklist(txn.get('blacklist_path'), problems)
        if txn.get('account') in banned:
            problems.append('account %s is blacklisted' % txn.get('account'))
        if problems:
            errors.extend(problems)
        else:
            cleared.append({'amount': amount, 'risk': ratio, 'location': location,
                            'industry': industry, 'account_digits': digits,
                            'device': device})
    return cleared, errors


def main():
    folder = tempfile.mkdtemp()
    path = os.path.join(folder, 'blacklist.txt')
    handle = open(path, 'w')
    handle.write('999999999\n')
    handle.close()
    now = time.time()
    future = [{'amount': '250.75', 'volume': 4000.0, 'average': 500.0,
               'recent_logins': ['oslo', 'paris', 'rome'], 'mcc': '5411',
               'account': '123456789', 'fingerprint': b'abc-device',
               'timestamp': now + 3600.0, 'blacklist_path': path}]
    cleared, errors = scan_transactions(future, now)
    print('cleared: %r' % (cleared,))
    print('errors: %r' % (errors,))


if __name__ == '__main__':
    main()

