        industry = industry_label(txn.get('mcc'), problems)
        digits = account_length(txn.get('account'), problems)
        device = decode_fingerprint(txn.get('fingerprint', b''), problems)
        check_timestamp(txn.get('timestamp', now), now, problems)
        banned = read_blacklist(txn.get('blacklist_path'), problems)
        if txn.get('account') in banned:
