def evaluate_trades(trades, exchange_directory):
    metrics = []
    errors = []
    for trade in trades:
        price = margin = indicator = exchange = None
        id_length = sentiment = None
        try:
            price = float(trade.get("price"))
        except ValueError as err:
            errors.append("price parse failed: %s" % err)
        try:
            margin = trade.get("net_return") / trade.get("capital_risked")
        except ZeroDivisionError as err:
            errors.append(err)
        try:
            indicator = trade.get("momentum", [])[1]
        except IndexError as err:
            errors.append("momentum unavailable: %s" % err)
        try:
            exchange = exchange_directory[trade.get("symbol")]
        except KeyError as err:
            errors.append(err)
        try:
            id_length = len(trade.get("order_id"))
        except TypeError as err:
            errors.append("order id unusable: %s" % err)
        try:
            sentiment = trade.get("sentiment_feed", b"").decode("utf-8")
        except UnicodeDecodeError as err:
            errors.append("sentiment decode failed: %s" % err)
        slippage = trade.get("slippage", 0.0)
        within_bounds = True
        try:
            assert abs(slippage) <= 0.05, "slippage %.4f above limit" % slippage
        except AssertionError as err:
            errors.append("slippage rejected: %s" % err)
            within_bounds = False
        handle = None
        try:
            handle = open(trade.get("tick_file", ""), "rb")
        except OSError as err:
            errors.append(err)
        if handle is None:
            continue
        tick_rows = len(handle.read().splitlines())
        handle.close()
        fields = (price, margin, indicator, exchange, id_length, sentiment)
        if within_bounds and all(value is not None for value in fields):
            metrics.append({"symbol": trade.get("symbol"), "exchange": exchange,
                            "price": price, "margin": margin,
                            "indicator": indicator, "order_id_length": id_length,
                            "sentiment": sentiment, "tick_rows": tick_rows})
    return (metrics, errors)


def format_report(metrics, errors):
    lines = []
    for metric in metrics:
        lines.append("%s@%s price=%.2f margin=%.4f ind=%.3f rows=%d" %
                     (metric["symbol"], metric["exchange"], metric["price"],
                      metric["margin"], metric["indicator"], metric["tick_rows"]))
    for problem in errors:
        lines.append("ERROR %s" % problem)
    return lines


