import os

STATION_COORDS = {
    "KJFK": (40.64, -73.78),
    "KSEA": (47.45, -122.31),
    "KDEN": (39.86, -104.67),
}


def parse_pressure(raw, errors):
    try:
        return float(raw)
    except ValueError as err:
        errors.append("pressure: %s" % err)
        return None


def humidity_gradient(moisture, altitude_change, errors):
    try:
        return moisture / float(altitude_change)
    except ZeroDivisionError as err:
        errors.append("gradient: %s" % err)
        return None


def fifth_temperature(history, errors):
    try:
        return history[4]
    except IndexError as err:
        errors.append("temperature: %s" % err)
        return None


def locate_station(station_id, errors):
    try:
        return STATION_COORDS[station_id]
    except KeyError as err:
        errors.append("station: unknown id %s" % err)
        return None


def timestamp_length(timestamp, errors):
    try:
        return len(timestamp)
    except TypeError as err:
        errors.append("timestamp: %s" % err)
        return None


def decode_satellite(raw_bytes, errors):
    try:
        return raw_bytes.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("satellite: %s" % err)
        return None


def validate_wind(wind_speed, errors):
    try:
        assert wind_speed >= 0, "wind speed %r is negative" % (wind_speed,)
        return True
    except AssertionError as err:
        errors.append("wind: %s" % err)
        return False


def read_baseline(path, errors):
    try:
        handle = open(path, "rb")
    except EnvironmentError as err:
        errors.append("baseline: %s (%s)" % (err.strerror, os.path.basename(path)))
        return None
    try:
        return handle.read().decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("baseline decode: %s" % err)
        return None
    finally:
        handle.close()


def predict_weather(batch):
    forecast = []
    errors = []
    for reading in batch:
        pressure = parse_pressure(reading.get("barometric_pressure"), errors)
        gradient = humidity_gradient(reading.get("moisture_level", 0.0),
                                     reading.get("altitude_change", 0), errors)
        temp = fifth_temperature(reading.get("temperature_history", []), errors)
        coords = locate_station(reading.get("station_id"), errors)
        stamp_len = timestamp_length(reading.get("observation_timestamp"), errors)
        decode_satellite(reading.get("satellite_feed", b""), errors)
        calm = validate_wind(reading.get("wind_speed", 0.0), errors)
        read_baseline(reading.get("baseline_path", ""), errors)
        if pressure is None or coords is None or stamp_len is None:
            continue
        trend = "stormy" if pressure < 1000.0 else "fair"
        if gradient is not None and gradient > 0.5:
            trend = trend + ", rising humidity"
        if temp is not None and temp < 0:
            trend = trend + ", freezing"
        if not calm:
            trend = trend + ", wind data suspect"
        forecast.append("%s at %.2f/%.2f: %s" % (reading["station_id"],
                                                 coords[0], coords[1], trend))
    return forecast, errors


def main():
    batch = [{
        "station_id": "KJFK",
        "barometric_pressure": "low",
        "moisture_level": 12.0,
        "altitude_change": 0,
        "temperature_history": [3, 2, 1],
        "observation_timestamp": 1723459200,
        "satellite_feed": b"\xff\xfe raw",
        "wind_speed": -4.5,
        "baseline_path": "/nonexistent/climate/baseline.txt",
    }]
    forecast, errors = predict_weather(batch)
    print("Forecast: %r" % (forecast,))
    print("Errors: %r" % (errors,))


if __name__ == "__main__":
    main()

