FAULT_LINES = {
    "SAF": "San Andreas Fault",
    "HAY": "Hayward Fault",
    "CAS": "Cascadia Subduction Zone",
}


def parse_magnitude(raw):
    try:
        return float(raw), None
    except ValueError as err:
        return None, str(err)


def wave_speed(distance_km, arrival_s):
    try:
        return distance_km / arrival_s, None
    except ZeroDivisionError as err:
        return None, err


def third_phase(waveform):
    try:
        return waveform[2], None
    except IndexError as err:
        return None, str(err)


def fault_name(code):
    try:
        return FAULT_LINES[code], None
    except KeyError as err:
        return None, err


def serial_length(serial):
    try:
        return len(serial), None
    except TypeError as err:
        return None, str(err)


def decode_alert(raw_bytes):
    try:
        return raw_bytes.decode("utf-8"), None
    except UnicodeDecodeError as err:
        return None, str(err)


def check_depth(depth_km):
    try:
        assert depth_km > 0, "depth must be greater than zero"
        return True, None
    except AssertionError as err:
        return False, str(err)


def read_calibration(path):
    try:
        handle = open(path, "rb")
        try:
            return handle.read().decode("ascii", "replace"), None
        finally:
            handle.close()
    except OSError as err:
        return None, err


def build_record(event, errors):
    steps = [
        ("magnitude", parse_magnitude(event["magnitude"])),
        ("wave_speed", wave_speed(event["distance_km"], event["arrival_s"])),
        ("phase", third_phase(event["waveform"])),
        ("fault", fault_name(event["fault_code"])),
        ("serial_length", serial_length(event["serial"])),
        ("alert", decode_alert(event["alert_raw"])),
        ("depth_ok", check_depth(event["depth_km"])),
        ("calibration", read_calibration(event["calibration_path"])),
    ]
    record = {"sensor_id": event["sensor_id"]}
    for name, outcome in steps:
        value, problem = outcome
        if problem is not None:
            errors.append(problem)
            return None
        record[name] = value
    return record


def process_events(events):
    processed = []
    errors = []
    for event in events:
        record = build_record(event, errors)
        if record is not None:
            processed.append(record)
    return processed, errors


def main():
    events = [{
        "sensor_id": "S-11",
        "magnitude": "4.7",
        "distance_km": 88.0,
        "arrival_s": 0,
        "waveform": ["P", "S", "Love", "Rayleigh"],
        "fault_code": "SAF",
        "serial": "SN-0099",
        "alert_raw": b"moderate tremor",
        "depth_km": 12.5,
        "calibration_path": "calib/s11.bin",
    }]
    processed, errors = process_events(events)
    print("processed: %r" % (processed,))
    print("errors: %s" % ([str(item) for item in errors],))


if __name__ == "__main__":
    main()

