MATERIAL_INVENTORY = {
    "AL7075": "Aluminium 7075-T6",
    "TI64": "Titanium Ti-6Al-4V",
    "SS316": "Stainless Steel 316L",
}

MIN_PACKAGE_WEIGHT = 0.5


def inspect_record(record, inventory):
    errors = []
    item = {}

    try:
        item["integrity"] = float(record.get("structural_integrity"))
    except ValueError as err:
        errors.append(str(err))
    except TypeError as err:
        errors.append(str(err))

    try:
        item["defect_ratio"] = record.get("flaw_count") / record.get("surface_area")
    except ZeroDivisionError as err:
        errors.append(str(err))

    try:
        item["second_photo"] = record["camera_array"][1]
    except IndexError as err:
        errors.append(str(err))

    try:
        item["material"] = inventory[record.get("material_code")]
    except KeyError as err:
        errors.append(str(err))

    try:
        item["batch_digits"] = len(record.get("batch_number"))
    except TypeError as err:
        errors.append(str(err))

    try:
        item["scanner_text"] = record["scanner_bytes"].decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append(str(err))

    try:
        assert record.get("package_weight") >= MIN_PACKAGE_WEIGHT, \
            "package weight %s below regulatory minimum" % record.get("package_weight")
    except AssertionError as err:
        errors.append(str(err))

    try:
        handle = open(record["blueprint_path"], "rb")
        try:
            item["blueprint_size"] = len(handle.read())
        finally:
            handle.close()
    except OSError as err:
        errors.append(str(err))

    return item, errors


def analyze_quality_data(records, inventory=None):
    if inventory is None:
        inventory = MATERIAL_INVENTORY
    approved = []
    all_errors = []
    for record in records:
        item, errors = inspect_record(record, inventory)
        all_errors.extend(errors)
        if not errors:
            approved.append(item)
    return approved, all_errors


def format_report(approved, errors):
    lines = ["approved items: %d" % len(approved)]
    for item in approved:
        lines.append("  %s batch=%s ratio=%.4f" % (
            item["material"], item["scanner_text"], item["defect_ratio"]))
    for message in errors:
        lines.append("  error: %s" % message)
    return "\n".join(lines)


def main():
    records = [{
        "structural_integrity": "97.5",
        "flaw_count": 3,
        "surface_area": 120.0,
        "camera_array": ["front.png"],
        "material_code": "AL7075",
        "batch_number": "B-2291",
        "scanner_bytes": b"B-2291",
        "package_weight": 1.25,
        "blueprint_path": __file__,
    }]
    approved, errors = analyze_quality_data(records)
    print(format_report(approved, errors))
    print("%r %r" % (approved, errors))


if __name__ == "__main__":
    main()

