import os

TEXTURE_ASSETS = {
    "grass": "asset/grass_diffuse",
    "stone": "asset/stone_diffuse",
    "water": "asset/water_normal",
}


def parse_coordinate(raw, errors):
    try:
        return float(raw)
    except ValueError as err:
        errors.append("coordinate: %s" % err)
        return None


def compute_velocity(delta, latency, errors):
    try:
        return delta / latency
    except ZeroDivisionError as err:
        errors.append("velocity: %s" % err)
        return None


def fourth_bone(skeleton, errors):
    try:
        return skeleton[3]
    except IndexError as err:
        errors.append("skeleton: %s" % err)
        return None


def resolve_texture(texture_id, errors):
    try:
        return TEXTURE_ASSETS[texture_id]
    except KeyError as err:
        errors.append("texture: missing key %s" % err)
        return None


def timestamp_length(stamp, errors):
    try:
        return len(stamp)
    except TypeError as err:
        errors.append("timestamp: %s" % err)
        return None


def decode_voice(raw, errors):
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("voice: %s" % err)
        return None


def check_health(health, errors):
    try:
        assert health >= 0, "health %s is negative" % health
    except AssertionError as err:
        errors.append("health: %s" % err)
        return False
    return True


def load_geometry(path, errors):
    try:
        handle = open(path, "rb")
    except EnvironmentError as err:
        errors.append("geometry: %s" % err)
        return None
    try:
        return handle.read()
    finally:
        handle.close()


def synchronize_physics(states):
    frames = []
    errors = []
    for state in states:
        parts = [
            parse_coordinate(state.get("player_x"), errors),
            compute_velocity(state.get("position_delta"), state.get("network_latency"), errors),
            fourth_bone(state.get("skeleton", []), errors),
            resolve_texture(state.get("texture_id"), errors),
            timestamp_length(state.get("session_timestamp"), errors),
            decode_voice(state.get("voice_chat", b""), errors),
            load_geometry(state.get("map_path", ""), errors),
        ]
        healthy = check_health(state.get("health", 0), errors)
        if healthy and None not in parts:
            frames.append({
                "x": parts[0],
                "velocity": parts[1],
                "bone": parts[2],
                "asset": parts[3],
                "stamp_len": parts[4],
                "voice": parts[5],
                "geometry_bytes": len(parts[6]),
            })
    return frames, errors


def main():
    batch = [{
        "player_x": "12.5",
        "position_delta": 3.0,
        "network_latency": 0.05,
        "skeleton": ["pelvis", "spine", "neck", "head"],
        "texture_id": "grass",
        "session_timestamp": 1712,
        "voice_chat": b"go left",
        "health": 87,
        "map_path": os.devnull,
    }]
    frames, errors = synchronize_physics(batch)
    print("frames: %r" % (frames,))
    print("errors: %r" % (errors,))


if __name__ == "__main__":
    main()

