import os
import tempfile

SUPPORTED_FORMATS = {
    "h264": "AVC/H.264",
    "hevc": "HEVC/H.265",
    "vp9": "VP9",
    "av1": "AV1",
}

STANDARD_FRAME_RATES = (23.976, 24.0, 25.0, 29.97, 30.0, 50.0, 59.94, 60.0)


def assess_segment(chunk, formats=SUPPORTED_FORMATS):
    metrics = {}
    errors = []
    try:
        metrics["bitrate_bps"] = int(chunk["bitrate"])
    except ValueError as err:
        errors.append(str(err))
    try:
        metrics["buffering_ratio"] = chunk["stall_duration"] / float(chunk["playtime"])
    except ZeroDivisionError as err:
        errors.append(err)
    try:
        metrics["second_audio_track"] = chunk["streams"][1]
    except IndexError as err:
        errors.append(str(err))
    try:
        metrics["codec_label"] = formats[chunk["codec"]]
    except KeyError as err:
        errors.append(err)
    try:
        metrics["resolution_tag_length"] = len(chunk["resolution"])
    except TypeError as err:
        errors.append(str(err))
    try:
        metrics["captions"] = chunk["closed_captioning"].decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append(str(err))
    try:
        assert chunk["frame_rate"] in STANDARD_FRAME_RATES, \
            "non-standard frame rate %r" % (chunk["frame_rate"],)
        metrics["frame_rate"] = chunk["frame_rate"]
    except AssertionError as err:
        errors.append(str(err))
    try:
        handle = open(chunk["subtitle_path"], "rb")
        try:
            metrics["subtitle_bytes"] = len(handle.read())
        finally:
            handle.close()
    except EnvironmentError as err:
        errors.append(err)
    if errors:
        return [], errors
    return [metrics], errors


def assess_stream(segments):
    quality_metrics = []
    error_log = []
    for chunk in segments:
        metrics, errors = assess_segment(chunk)
        quality_metrics.extend(metrics)
        error_log.extend(errors)
    return quality_metrics, error_log


def format_report(quality_metrics, error_log):
    lines = ["healthy segments: %d" % len(quality_metrics)]
    for metrics in quality_metrics:
        lines.append("  %s %s @ %d bps, buffering %.3f, subtitles %d bytes" % (
            metrics["codec_label"], metrics["resolution_tag_length"],
            metrics["bitrate_bps"], metrics["buffering_ratio"],
            metrics["subtitle_bytes"]))
    for entry in error_log:
        lines.append("  error: %s" % (entry,))
    return "\n".join(lines)


def main():
    fd, path = tempfile.mkstemp(suffix=".vtt")
    os.write(fd, "WEBVTT\n\n00:00.000 --> 00:02.000\nhello\n".encode("utf-8"))
    os.close(fd)
    segments = [
        {"bitrate": "4500000", "stall_duration": 0.4, "playtime": 120.0,
         "streams": ["video", "audio_en", "audio_fr"], "codec": "h264",
         "resolution": "1920x1080", "closed_captioning": "CC1".encode("utf-8"),
         "frame_rate": 25.0, "subtitle_path": path},
        {"bitrate": "3000000", "stall_duration": 1.0, "playtime": 90.0,
         "streams": ["video", "audio_en"], "codec": "vp9",
         "resolution": "1280x720", "closed_captioning": b"\xff\xfe bad",
         "frame_rate": 30.0, "subtitle_path": path},
    ]
    quality_metrics, error_log = assess_stream(segments)
    print(format_report(quality_metrics, error_log))
    os.remove(path)


if __name__ == "__main__":
    main()

