THREAT_INTEL = {
    "B001": "process hollowing",
    "B002": "registry persistence",
    "B003": "credential dumping",
    "B004": "keylogging",
}

SANDBOX_TIME_LIMIT = 30.0


def parse_offset(sample, errors):
    try:
        return int(str(sample.get("offset")), 16)
    except ValueError as err:
        errors.append(str(err))
        return None


def entropy_ratio(sample, errors):
    try:
        return float(sample.get("compressed_size")) / sample.get("uncompressed_size")
    except ZeroDivisionError as err:
        errors.append(str(err))
        return None


def third_import(sample, errors):
    try:
        return sample.get("imports", [])[2]
    except IndexError as err:
        errors.append(str(err))
        return None


def translate_behavior(sample, errors):
    try:
        return THREAT_INTEL[sample.get("behavior")]
    except KeyError as err:
        errors.append(str(err))
        return None


def checksum_length(sample, errors):
    try:
        return len(sample.get("checksum"))
    except TypeError as err:
        errors.append(str(err))
        return None


def decode_payload(sample, errors):
    try:
        return sample.get("payload", b"").decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append(str(err))
        return None


def verify_runtime(sample, errors):
    try:
        assert sample.get("runtime") < SANDBOX_TIME_LIMIT, \
            "runtime %.1fs exceeds sandbox limit %.1fs" % (sample.get("runtime"), SANDBOX_TIME_LIMIT)
        return True
    except AssertionError as err:
        errors.append(str(err))
        return False


def read_log(sample, errors):
    try:
        handle = open(sample.get("log_path"))
    except EnvironmentError as err:
        errors.append(str(err))
        return None
    try:
        return handle.read().strip()
    finally:
        handle.close()


def analyze_payloads(samples):
    signatures = []
    errors = []
    for sample in samples:
        faults = len(errors)
        signature = {
            "name": sample.get("name"),
            "offset": parse_offset(sample, errors),
            "entropy": entropy_ratio(sample, errors),
            "library": third_import(sample, errors),
            "threat": translate_behavior(sample, errors),
            "checksum_len": checksum_length(sample, errors),
            "payload": decode_payload(sample, errors),
        }
        verify_runtime(sample, errors)
        signature["log"] = read_log(sample, errors)
        if len(errors) == faults:
            signatures.append(signature)
    return signatures, errors


def main():
    import os
    import tempfile
    descriptor, path = tempfile.mkstemp(suffix=".relog")
    os.write(descriptor, "unpacked at stage two".encode("utf-8"))
    os.close(descriptor)
    samples = [{
        "name": "sample_slowloris",
        "offset": "0x00401000",
        "compressed_size": 4096,
        "uncompressed_size": 8192,
        "imports": ["kernel32.dll", "user32.dll", "ws2_32.dll"],
        "behavior": "B002",
        "checksum": "9f2c4e1a",
        "payload": b"CreateRemoteThread",
        "runtime": 42.5,
        "log_path": path,
    }]
    signatures, errors = analyze_payloads(samples)
    print("signatures: %r" % (signatures,))
    print("errors: %r" % (errors,))
    os.remove(path)


if __name__ == "__main__":
    main()

