    except TypeError as err:
        errors.append("identifier: %s" % err)
        return None


def decode_feed(feed, errors):
    try:
        return feed.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("camera: %s" % err)
        return None


def check_cycle(cycle, errors):
    try:
