        return True
    except AssertionError as err:
        errors.append("cycle: %s" % err)
        return False


def read_report(path, errors):
    try:
        handle = open(path, "rb")
    except EnvironmentError as err:
        errors.append("report: %s" % err)
        return None
    try:
        return handle.read()
    finally:
        handle.close()


def configure_traffic_lights(nodes, planning):
    timings = []
    errors = []
    for node in nodes:
        local = []
        flow = parse_throughput(node.get("throughput"), local)
        index = congestion_index(node.get("waiting_cars"), node.get("green"), local)
        crosswalk = fourth_crosswalk(node.get("pedestrians", []), local)
        priority = district_priority(planning, node.get("district"), local)
        tag_length = identifier_length(node.get("id"), local)
        feed = decode_feed(node.get("camera_feed", b""), local)
        check_cycle(node.get("cycle_time"), local)
        report = read_report(node.get("accident_report"), local)
        if local:
            errors.extend(local)
            continue
        timings.append({
            "id": node["id"],
            "green": round(node["green"] * (1.0 + index / (priority + 1.0)), 1),
            "flow": flow,
            "crosswalk": crosswalk,
            "tag_length": tag_length,
            "feed": feed,
            "report_bytes": len(report),
        })
    return timings, errors


