import io

GROWTH_PROFILES = {
    "FIC": {"name": "ficus", "min_humidity": 50.0},
    "CAC": {"name": "cactus", "min_humidity": 20.0},
}


def parse_ph(raw, errors):
    try:
        return float(raw)
    except ValueError as err:
        errors.append("soil pH: %s" % err)
        return None


def absorption_rate(fertilizer, water, errors):
    try:
        return fertilizer / float(water)
    except ZeroDivisionError as err:
        errors.append("absorption: %s" % err)
        return None


def second_light_cycle(schedule, errors):
    try:
        return schedule[1]
    except IndexError as err:
        errors.append("light cycle: %s" % err)
        return None


def growth_profile(code, errors):
    try:
        return GROWTH_PROFILES[code]
    except KeyError as err:
        errors.append("species: %s" % err)
        return None


def timestamp_length(stamp, errors):
    try:
        return len(stamp)
    except TypeError as err:
        errors.append("timestamp: %s" % err)
        return None


def decode_humidity(raw, errors):
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as err:
        errors.append("humidity feed: %s" % err)
        return None


def humidity_level(text, errors):
    try:
        return float(text.split("%")[0])
    except ValueError as err:
        errors.append("humidity value: %s" % err)
        return None


def check_temperature(temp, errors):
    try:
        assert 5.0 <= temp <= 35.0, "%.1fC outside safe crop range" % temp
        return True
    except AssertionError as err:
        errors.append("temperature: %s" % err)
        return False


def load_lighting_plan(path, errors):
    try:
        handle = io.open(path, "r", encoding="utf-8")
    except EnvironmentError as err:
        errors.append("lighting file: %s" % err)
        return None
    try:
        return handle.read().splitlines()
    finally:
        handle.close()


def adjust_climate(reading):
    errors = []
    adjustments = []
    ph = parse_ph(reading.get("soil_ph"), errors)
    if ph is not None and ph < 6.0:
        adjustments.append("apply lime to raise soil pH")
    rate = absorption_rate(reading.get("fertilizer"), reading.get("water"), errors)
    if rate is not None and rate > 0.05:
        adjustments.append("reduce fertilizer feed")
    cycle = second_light_cycle(reading.get("schedule", []), errors)
    if cycle is not None and cycle > 12:
        adjustments.append("shorten second light cycle")
    profile = growth_profile(reading.get("species"), errors)
    text = decode_humidity(reading.get("humidity_feed"), errors)
    if text is not None:
        level = humidity_level(text, errors)
        if profile is not None and level is not None and level < profile["min_humidity"]:
            adjustments.append("increase misting for %s" % profile["name"])
    stamp_len = timestamp_length(reading.get("timestamp"), errors)
    if stamp_len is not None and stamp_len != 14:
        adjustments.append("resync hardware clock")
    if not check_temperature(reading.get("temperature"), errors):
        adjustments.append("vent greenhouse")
    plan = load_lighting_plan(reading.get("lighting_file"), errors)
    if plan is not None and len(plan) < 4:
        adjustments.append("extend seasonal lighting plan")
    return adjustments, errors


def main():
    plan_path = "seasonal_lighting.txt"
    handle = io.open(plan_path, "w", encoding="utf-8")
    handle.write(u"spring 14h\nsummer 16h\nautumn 12h\nwinter 9h\n")
    handle.close()
    readings = [
        {"soil_ph": "acidic", "fertilizer": 2.0, "water": 100.0,
         "schedule": [6, 10], "species": "FIC", "timestamp": "20240518093015",
         "humidity_feed": b"58.4% RH", "temperature": 22.5,
         "lighting_file": plan_path},
        {"soil_ph": "5.4", "fertilizer": 8.0, "water": 0.0,
         "schedule": [7], "species": "XXX", "timestamp": 20240518,
         "humidity_feed": b"\xff\xfe RH", "temperature": 41.0,
         "lighting_file": "missing_plan.txt"},
    ]
    for reading in readings:
        adjustments, errors = adjust_climate(reading)
        print("adjustments: %r" % (adjustments,))
        print("errors: %r" % (errors,))


if __name__ == "__main__":
    main()

