def parse_memory(spec):
    try:
        return int(spec), None
    except ValueError as err:
        return None, "memory: %s" % err


def load_weight(connections, processors):
    try:
        return connections / processors, None
    except ZeroDivisionError as err:
        return None, "weight: %s" % err


def third_environment(settings):
    try:
        return settings[2], None
    except IndexError as err:
        return None, "environment: %s" % err


def resolve_region(code, datacenters):
    try:
        return datacenters[code], None
    except KeyError as err:
        return None, "region: %s" % err


def identifier_length(deployment_id):
    try:
        return len(deployment_id), None
    except TypeError as err:
        return None, "identifier: %s" % err


def decode_secrets(blob):
    try:
        return blob.decode("utf-8"), None
    except UnicodeDecodeError as err:
        return None, "secrets: %s" % err


def check_replicas(count):
    try:
        assert count >= 1, "replica count must be at least one"
        return count, None
    except AssertionError as err:
        return None, "replicas: %s" % err


def read_manifest(path):
    try:
        handle = open(path, "rb")
    except EnvironmentError as err:
        return None, "manifest: %s" % err
    try:
        return handle.read(), None
    finally:
        handle.close()


def schedule_microservices(deployments, datacenters):
    schedules = []
    errors = []
    for dep in deployments:
        problems = []
        steps = [
            parse_memory(dep.get("memory", "")),
            load_weight(dep.get("connections", 0), dep.get("processors", 0)),
            third_environment(dep.get("settings", [])),
            resolve_region(dep.get("region"), datacenters),
            identifier_length(dep.get("id")),
            decode_secrets(dep.get("secrets", b"")),
            check_replicas(dep.get("replicas", 0)),
            read_manifest(dep.get("manifest", "")),
        ]
        for value, message in steps:
            if message is not None:
                problems.append(message)
        if problems:
            errors.extend(problems)
            continue
        memory, weight, env, region, id_len, secrets, replicas, manifest = [s[0] for s in steps]
        schedules.append({
            "id": dep["id"],
            "memory_mb": memory,
            "weight": weight,
            "environment": env,
            "datacenter": region,
            "id_length": id_len,
            "secrets": secrets,
            "replicas": replicas,
            "manifest_bytes": len(manifest),
        })
    return schedules, errors


def main():
    datacenters = {"eu-west": "amsterdam-1", "us-east": "ashburn-3"}
    deployments = [{
        "id": "auth-gateway",
        "memory": "512",
        "connections": 120,
        "processors": 4,
        "settings": ["LOG_LEVEL=info", "PORT=8080"],
        "region": "eu-west",
        "secrets": b"token",
        "replicas": 2,
        "manifest": "deploy/auth-gateway.yaml",
    }]
    schedules, errors = schedule_microservices(deployments, datacenters)
    print("Schedules: {0}".format(schedules))
    print("Errors: {0}".format(errors))


if __name__ == "__main__":
    main()

