BASE_MONTHLY_RATE = 25.0
STORAGE_RATE = 0.10
BANDWIDTH_RATE = 0.05


def to_bool(value):
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("true", "yes", "y", "1", "on"):
        return True
    if text in ("false", "no", "n", "0", "off"):
        return False
    raise ValueError("invalid boolean value: %s" % (value,))


def process(subscription):
    fields = {}
    errors = []
    try:
        fields["duration_months"] = int(subscription["duration_months"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["monthly_discount"] = float(subscription["monthly_discount"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["max_users"] = int(subscription["max_users"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["storage_limit_gb"] = float(subscription["storage_limit_gb"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["extra_bandwidth_gb"] = float(subscription["extra_bandwidth_gb"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["auto_renew"] = to_bool(subscription["auto_renew"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["trial_days"] = int(subscription["trial_days"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    try:
        fields["loyalty_points"] = int(subscription["loyalty_points"])
    except (KeyError, ValueError) as err:
        errors.append(str(err))
    return fields, errors


def estimate_billing(fields):
    notes = []
    try:
        months = fields["duration_months"]
        discount = fields["monthly_discount"]
    except KeyError as err:
        return None, ["billing skipped, missing %s" % err]
    total = months * BASE_MONTHLY_RATE * (1.0 - discount)
    try:
        total += fields["storage_limit_gb"] * STORAGE_RATE * months
        total += fields["extra_bandwidth_gb"] * BANDWIDTH_RATE * months
    except KeyError as err:
        notes.append("usage charges omitted, missing %s" % err)
    return total, notes


def format_report(name, fields, errors):
    lines = ["subscription: %s" % name]
    for key in sorted(fields):
        lines.append("  %s = %s" % (key, fields[key]))
    total, notes = estimate_billing(fields)
    if total is None:
        lines.extend("  " + note for note in notes)
    else:
        lines.append("  estimated total = %.2f" % total)
        lines.extend("  " + note for note in notes)
    for message in errors:
        lines.append("  error: %s" % message)
    return "\n".join(lines)


def main():
    samples = [
        ("acme", {"duration_months": 12, "monthly_discount": "0.15", "max_users": "40",
                  "storage_limit_gb": "500", "extra_bandwidth_gb": 120, "auto_renew": "yes",
                  "trial_days": "14", "loyalty_points": "3200"}),
        ("globex", {"duration_months": "twelve", "max_users": 5, "storage_limit_gb": "abc",
                    "extra_bandwidth_gb": "0", "auto_renew": "maybe", "trial_days": 7,
                    "loyalty_points": "10"}),
    ]
    for name, subscription in samples:
        fields, errors = process(subscription)
        print(format_report(name, fields, errors))


if __name__ == "__main__":
    main()

