import sys


def parse_float(report, key, warnings):
    try:
        raw = report[key]
    except KeyError as err:
        warnings.append("missing key: %s" % err)
        return None
    try:
        return float(raw)
    except ValueError as err:
        warnings.append("%s: %s" % (key, err))
        return None
    except TypeError as err:
        warnings.append("%s: %s" % (key, err))
        return None


def parse_int(report, key, warnings):
    try:
        raw = report[key]
    except KeyError as err:
        warnings.append("missing key: %s" % err)
        return None
    try:
        return int(raw)
    except ValueError as err:
        warnings.append("%s: %s" % (key, err))
        return None
    except TypeError as err:
        warnings.append("%s: %s" % (key, err))
        return None


def diagnose(report):
    warnings = []
    data = {}
    data["cpu_temp"] = parse_float(report, "cpu_temp", warnings)
    data["memory_usage"] = parse_float(report, "memory_usage", warnings)
    data["fan_speed"] = parse_int(report, "fan_speed", warnings)
    data["uptime"] = parse_int(report, "uptime", warnings)
    data["disk_free"] = parse_float(report, "disk_free", warnings)
    data["battery_cycles"] = parse_int(report, "battery_cycles", warnings)
    data["brightness"] = parse_float(report, "brightness", warnings)
    data["latency"] = parse_int(report, "latency", warnings)
    return (data, warnings)


def format_uptime(seconds):
    try:
        total = int(seconds)
    except TypeError as err:
        return "unknown (%s)" % err
    hours = total // 3600
    minutes = (total % 3600) // 60
    return "%dh%02dm" % (hours, minutes)


def report_lines(data, warnings):
    lines = []
    order = ["cpu_temp", "memory_usage", "fan_speed", "disk_free",
             "battery_cycles", "brightness", "latency"]
    for key in order:
        value = data[key]
        if value is None:
            lines.append("%-15s unavailable" % key)
        else:
            lines.append("%-15s %s" % (key, value))
    lines.append("%-15s %s" % ("uptime", format_uptime(data["uptime"])))
    for message in warnings:
        lines.append("WARNING: %s" % message)
    return lines


def main(argv):
    report = {"cpu_temp": "hot", "memory_usage": "62.5", "fan_speed": "2400",
              "uptime": "98000", "disk_free": "120.75", "brightness": "0.8",
              "latency": "not measured"}
