import json
import sys


def parse_float(value):
    if isinstance(value, bool):
        raise ValueError("boolean %r is not numeric" % value)
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace(",", "")
    if "/" in text:
        numerator, _, denominator = text.partition("/")
        try:
            return float(numerator) / float(denominator)
        except ZeroDivisionError as err:
            raise ValueError("bad ratio %r: %s" % (text, err))
    return float(text)


def parse_int(value):
    try:
        return int(str(value).strip().replace(",", ""))
    except ValueError as err:
        number = parse_float(value)
        if number != int(number):
            raise ValueError("%s (not a whole number)" % err)
        return int(number)


def parse_size_mb(value):
    text = str(value).strip()
    units = (("gb", 1024.0), ("mb", 1.0), ("kb", 1.0 / 1024.0), ("b", 1.0 / (1024.0 * 1024.0)))
    for suffix, factor in units:
        if text.lower().endswith(suffix):
            try:
                return parse_float(text[:-len(suffix)]) * factor
            except ValueError as err:
                raise ValueError("bad size %r: %s" % (text, err))
    return parse_float(value)


def count_items(value):
    if isinstance(value, (list, tuple, dict)):
        return len(value)
    text = str(value).strip()
    try:
        return parse_int(text)
    except ValueError as err:
        if [ch for ch in text if ch.isalpha()]:
            return len([part for part in text.split(",") if part.strip()])
        raise ValueError("uncountable %r: %s" % (text, err))


def dimension(metadata, key, index):
    try:
        return parse_int(metadata[key])
    except KeyError as err:
        if "resolution" not in metadata:
            raise KeyError("neither %s nor 'resolution'" % err)
        return parse_int(str(metadata["resolution"]).lower().split("x")[index])


def extract(metadata):
    data = {}
    faults = []
    try:
        data["duration_seconds"] = parse_float(metadata["duration"])
    except Exception as err:
        faults.append("duration: %s" % err)
    try:
        data["frame_rate"] = parse_float(metadata["frame_rate"])
    except Exception as err:
        faults.append("frame_rate: %s" % err)
    try:
        data["width"] = dimension(metadata, "width", 0)
    except Exception as err:
        faults.append("width: %s" % err)
    try:
        data["height"] = dimension(metadata, "height", 1)
    except Exception as err:
        faults.append("height: %s" % err)
    try:
        data["audio_bitrate"] = parse_int(metadata["audio_bitrate"])
    except Exception as err:
        faults.append("audio_bitrate: %s" % err)
    try:
        data["subtitle_languages"] = count_items(metadata["subtitles"])
    except Exception as err:
        faults.append("subtitles: %s" % err)
    try:
        data["file_size_mb"] = parse_size_mb(metadata["file_size"])
    except Exception as err:
        faults.append("file_size: %s" % err)
    try:
        data["chapter_count"] = count_items(metadata["chapters"])
    except Exception as err:
        faults.append("chapters: %s" % err)
    return data, faults


def main(argv):
    if len(argv) < 2:
        print("usage: %s metadata.json" % argv[0])
        return 2
    try:
        handle = open(argv[1])
    except IOError as err:
        print("cannot open input: %s" % err)
        return 1
    try:
        raw = json.load(handle)
    except ValueError as err:
        print("invalid JSON in %s: %s" % (argv[1], err))
        return 1
    finally:
        handle.close()
    data, faults = extract(raw)
    for key in sorted(data):
        print("%-20s %s" % (key, data[key]))
    for fault in faults:
        print("FAULT %s" % fault)
    return 1 if faults else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

