TRUE_WORDS = ('true', 'yes', 'y', '1', 'fasted')
FALSE_WORDS = ('false', 'no', 'n', '0', 'not fasted')


def to_bool(value):
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in TRUE_WORDS:
        return True
    if text in FALSE_WORDS:
        return False
    raise ValueError("invalid fasting status: %r" % (value,))


def body_mass_index(height_cm, weight_kg):
    metres = height_cm / 100.0
    if metres <= 0:
        raise ValueError("height must be positive, got %r" % (height_cm,))
    return weight_kg / (metres * metres)


def blood_pressure_category(systolic, diastolic):
    if systolic <= diastolic:
        raise ValueError("systolic %d must exceed diastolic %d" % (systolic, diastolic))
    if systolic >= 140 or diastolic >= 90:
        return "hypertensive"
    if systolic >= 130 or diastolic >= 85:
        return "elevated"
    return "normal"


def oxygen_status(saturation):
    if saturation < 0 or saturation > 100:
        raise ValueError("oxygen saturation out of range: %r" % (saturation,))
    return "low" if saturation < 92 else "normal"


def validate(record):
    readings = {}
    errors = []
    try:
        readings['age'] = int(record['age'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['height_cm'] = float(record['height_cm'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['weight_kg'] = float(record['weight_kg'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['heart_rate'] = int(record['heart_rate'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['systolic'] = int(record['systolic'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['diastolic'] = int(record['diastolic'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['oxygen_saturation'] = float(record['oxygen_saturation'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['fasting'] = to_bool(record['fasting'])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        readings['bmi'] = round(body_mass_index(readings['height_cm'], readings['weight_kg']), 1)
    except (KeyError, ValueError, ZeroDivisionError) as err:
        errors.append(str(err))
    return readings, errors


def format_report(readings, errors):
    lines = []
    try:
        lines.append("age %d years, heart rate %d bpm" % (readings['age'], readings['heart_rate']))
    except KeyError as err:
        lines.append("basic vitals unavailable: missing %s" % err)
    try:
        lines.append("BMI %.1f, fasting=%s" % (readings['bmi'], readings['fasting']))
    except KeyError as err:
        lines.append("BMI unavailable: missing %s" % err)
    try:
        lines.append("blood pressure %d/%d (%s)" % (readings['systolic'], readings['diastolic'],
                                                    blood_pressure_category(readings['systolic'],
                                                                            readings['diastolic'])))
    except (KeyError, ValueError) as err:
        lines.append("blood pressure unavailable: %s" % err)
    try:
        saturation = readings['oxygen_saturation']
        lines.append("SpO2 %.1f%% (%s)" % (saturation, oxygen_status(saturation)))
    except (KeyError, ValueError) as err:
        lines.append("SpO2 unavailable: %s" % err)
    for message in errors:
        lines.append("error: %s" % message)
    return "\n".join(lines)


def main():
    records = [
        {'age': '41', 'height_cm': '178', 'weight_kg': '81.5', 'heart_rate': '68',
         'systolic': '128', 'diastolic': '82', 'oxygen_saturation': '97.5', 'fasting': 'yes'},
        {'height_cm': 'tall', 'weight_kg': '64', 'heart_rate': '72', 'systolic': '118',
         'diastolic': '76', 'oxygen_saturation': '91', 'fasting': 'maybe'},
    ]
    for index, record in enumerate(records):
        readings, errors = validate(record)
        print("patient %d" % (index + 1))
        print(format_report(readings, errors))


if __name__ == '__main__':
    main()

