import sys

def parse_float(sample, key):
    return float(sample[key])

def parse_int(sample, key):
    return int(sample[key])

def parse_bool(sample, key):
    value = sample[key]
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("true", "yes", "1"):
        return True
    if text in ("false", "no", "0"):
        return False
    raise ValueError("invalid catalyst flag: %s" % (value,))

def analyze(sample):
    properties = {}
    anomalies = []

    try:
        properties["acidity"] = parse_float(sample, "acidity")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["temperature_c"] = parse_float(sample, "temperature_c")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["pressure_pa"] = parse_float(sample, "pressure_pa")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["mass_g"] = parse_float(sample, "mass_g")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["volume_ml"] = parse_float(sample, "volume_ml")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["concentration"] = parse_float(sample, "concentration")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["reaction_time_s"] = parse_int(sample, "reaction_time_s")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    try:
        properties["catalyst"] = parse_bool(sample, "catalyst")
    except (KeyError, ValueError, TypeError) as err:
        anomalies.append(str(err))

    return properties, anomalies

def report(properties, anomalies):
    lines = []
    for key in sorted(properties):
        lines.append("%-16s %s" % (key, properties[key]))
    try:
        density = properties["mass_g"] / properties["volume_ml"]
    except KeyError as err:
        lines.append("density unavailable, missing %s" % (err,))
    except ZeroDivisionError as err:
        lines.append("density unavailable (%s)" % (err,))
    else:
        lines.append("%-16s %.4f" % ("density_g_per_ml", density))
    for message in anomalies:
        lines.append("ANOMALY: %s" % (message,))
    return "\n".join(lines)

def main():
    sample = {
        "acidity": "7.2",
        "temperature_c": "21.5",
        "pressure_pa": "101325",
        "mass_g": "48.6",
        "volume_ml": "empty",
        "concentration": "0.35",
        "reaction_time_s": "120",
        "catalyst": "yes",
    }
    properties, anomalies = analyze(sample)
    sys.stdout.write(report(properties, anomalies) + "\n")

if __name__ == "__main__":
    main()

