        properties["reaction_time_s"] = parse_int(sample, "reaction_time_s")
    except (KeyError, ValueError, TypeError), err:
        anomalies.append(str(err))

    try:
        properties["catalyst"] = parse_bool(sample, "catalyst")
    except (KeyError, ValueError, TypeError), err:
