text_nat:
LABOR_RATE = 85.0

FIELDS = (
    ("serial_number", "serial number"),
    ("months_since_purchase", "months since purchase"),
    ("repair_cost", "estimated repair cost"),
    ("deductible", "customer deductible"),
    ("parts_required", "parts required count"),
    ("labor_hours", "labor hours estimated"),
    ("approved", "approved status"),
    ("prior_claims", "prior claim count"),
)

TRUE_WORDS = ("true", "yes", "y", "1", "approved")
FALSE_WORDS = ("false", "no", "n", "0", "denied")


def parse_int(value):
    if isinstance(value, bool):
        raise ValueError("expected an integer, got the boolean %r" % value)
    return int(str(value).strip())


def parse_float(value):
    if isinstance(value, bool):
        raise ValueError("expected a number, got the boolean %r" % value)
    return float(str(value).strip())


def parse_bool(value):
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in TRUE_WORDS:
        return True
    if text in FALSE_WORDS:
        return False
    raise ValueError("could not interpret %r as an approval status" % value)


def process(claim):
    processed = {}
    defects = []
    try:
        processed["serial_number"] = parse_int(claim.get("serial_number"))
    except ValueError as err:
        defects.append("serial number: %s" % err)
    try:
        processed["months_since_purchase"] = parse_int(claim.get("months_since_purchase"))
    except ValueError as err:
        defects.append("months since purchase: %s" % err)
    try:
        processed["repair_cost"] = parse_float(claim.get("repair_cost"))
    except ValueError as err:
        defects.append("estimated repair cost: %s" % err)
    try:
        processed["deductible"] = parse_float(claim.get("deductible"))
    except ValueError as err:
        defects.append("customer deductible: %s" % err)
    try:
        processed["parts_required"] = parse_int(claim.get("parts_required"))
    except ValueError as err:
        defects.append("parts required count: %s" % err)
    try:
        processed["labor_hours"] = parse_float(claim.get("labor_hours"))
    except ValueError as err:
        defects.append("labor hours estimated: %s" % err)
    try:
        processed["approved"] = parse_bool(claim.get("approved"))
    except ValueError as err:
        defects.append("approved status: %s" % err)
    try:
        processed["prior_claims"] = parse_int(claim.get("prior_claims"))
    except ValueError as err:
        defects.append("prior claim count: %s" % err)
    return processed, defects


def estimate_payout(processed):
    payout = processed["repair_cost"] - processed["deductible"]
    if processed["prior_claims"] > 2:
        payout = payout * 0.5
    if not processed["approved"]:
        payout = 0.0
    return max(payout, 0.0)


def labor_share(processed):
    return 100.0 * processed["labor_hours"] * LABOR_RATE / processed["repair_cost"]


def summarize(processed, defects):
    lines = []
    for key, label in FIELDS:
        if key in processed:
            lines.append("  %-24s %s" % (label + ":", processed[key]))
    try:
        lines.append("  payout estimate:         %.2f" % estimate_payout(processed))
    except KeyError as err:
        lines.append("  payout estimate:         unavailable (missing %s)" % err)
    try:
        lines.append("  labor share of cost:     %.1f%%" % labor_share(processed))
    except ZeroDivisionError as err:
        lines.append("  labor share of cost:     undefined (%s)" % err)
    except KeyError as err:
        lines.append("  labor share of cost:     unavailable (missing %s)" % err)
    for defect in defects:
        lines.append("  DEFECT: %s" % defect)
    return "\n".join(lines)


def main():
    claims = [
        {"serial_number": "884213", "months_since_purchase": "14",
         "repair_cost": "420.50", "deductible": "75", "parts_required": "3",
         "labor_hours": "2.5", "approved": "yes", "prior_claims": "1"},
        {"serial_number": "77-A", "months_since_purchase": 30,
         "repair_cost": "unknown", "deductible": None, "parts_required": 1.5,
         "labor_hours": "four", "approved": "maybe", "prior_claims": 4},
    ]
    for index, claim in enumerate(claims, 1):
        processed, defects = process(claim)
        print("Claim %d" % index)
        print(summarize(processed, defects))


if __name__ == "__main__":
    main()

