        defects.append("labor hours estimated: %s" % err)
    try:
        processed["approved"] = parse_bool(claim.get("approved"))
    except ValueError, err:
        defects.append("approved status: %s" % err)
    try:
        processed["prior_claims"] = parse_int(claim.get("prior_claims"))
    except ValueError, err:
        defects.append("prior claim count: %s" % err)
    return processed, defects


def estimate_payout(processed):
    payout = processed["repair_cost"] - processed["deductible"]
    if processed["prior_claims"] > 2:
        payout = payout * 0.5
    if not processed["approved"]:
        payout = 0.0
    return max(payout, 0.0)


def labor_share(processed):
    return 100.0 * processed["labor_hours"] * LABOR_RATE / processed["repair_cost"]


def summarize(processed, defects):
    lines = []
    for key, label in FIELDS:
        if key in processed:
            lines.append("  %-24s %s" % (label + ":", processed[key]))
    try:
        lines.append("  payout estimate:         %.2f" % estimate_payout(processed))
    except KeyError, err:
        lines.append("  payout estimate:         unavailable (missing %s)" % err)
    try:
        lines.append("  labor share of cost:     %.1f%%" % labor_share(processed))
    except ZeroDivisionError, err:
        lines.append("  labor share of cost:     undefined (%s)" % err)
    except KeyError, err:
        lines.append("  labor share of cost:     unavailable (missing %s)" % err)
    for defect in defects:
        lines.append("  DEFECT: %s" % defect)
    return "\n".join(lines)


def main():
    claims = [
        {"serial_number": "884213", "months_since_purchase": "14",
         "repair_cost": "420.50", "deductible": "75", "parts_required": "3",
         "labor_hours": "2.5", "approved": "yes", "prior_claims": "1"},
        {"serial_number": "77-A", "months_since_purchase": 30,
         "repair_cost": "unknown", "deductible": None, "parts_required": 1.5,
         "labor_hours": "four", "approved": "maybe", "prior_claims": 4},
    ]
    for index, claim in enumerate(claims, 1):
        processed, defects = process(claim)
        print("Claim %d" % index)
        print(summarize(processed, defects))


if __name__ == "__main__":
    main()

