def fetch(order, field, issues):
    try:
        return order[field]
    except KeyError as err:
        issues.append("%s: missing field %s" % (field, err))
    except TypeError as err:
        issues.append("%s: order is not indexable (%s)" % (field, err))
    return None


def parse_int(order, field, issues):
    raw = fetch(order, field, issues)
    if raw is None:
        return None
    try:
        return int(raw)
    except ValueError as err:
        issues.append("%s: %s" % (field, err))
    except TypeError as err:
        issues.append("%s: %s" % (field, err))
    return None


def parse_float(order, field, issues):
    raw = fetch(order, field, issues)
    if raw is None:
        return None
    try:
        return float(raw)
    except ValueError as err:
        issues.append("%s: %s" % (field, err))
    except TypeError as err:
        issues.append("%s: %s" % (field, err))
    return None


def parse_bool(order, field, issues):
    raw = fetch(order, field, issues)
    if raw is None:
        return None
    if isinstance(raw, bool):
        return raw
    try:
        return BOOL_WORDS[str(raw).strip().lower()]
    except KeyError as err:
        issues.append("%s: %s is not a boolean word" % (field, err))
    return None


def analyze(order):
    issues = []
    data = {
        "table": parse_int(order, "table", issues),
        "patrons": parse_int(order, "patrons", issues),
        "food_cost": parse_float(order, "food_cost", issues),
        "beverage_cost": parse_float(order, "beverage_cost", issues),
        "gratuity_pct": parse_float(order, "gratuity_pct", issues),
        "prep_minutes": parse_int(order, "prep_minutes", issues),
        "takeout": parse_bool(order, "takeout", issues),
        "loyalty_points": parse_int(order, "loyalty_points", issues),
    }
    try:
        data["subtotal"] = round(data["food_cost"] + data["beverage_cost"], 2)
    except TypeError as err:
        issues.append("subtotal: %s" % err)
    try:
        data["gratuity"] = round(data["subtotal"] * data["gratuity_pct"] / 100.0, 2)
    except KeyError as err:
        issues.append("gratuity: depends on %s" % err)
    except TypeError as err:
        issues.append("gratuity: %s" % err)
    try:
        due = data["subtotal"] + data["gratuity"] - data["loyalty_points"] / 100.0
        data["amount_due"] = round(due, 2)
    except KeyError as err:
        issues.append("amount_due: depends on %s" % err)
    except TypeError as err:
        issues.append("amount_due: %s" % err)
    return data, issues


def format_report(data, issues):
    lines = ["Table {0} / {1} patron(s)".format(data["table"], data["patrons"])]
    try:
        lines.append("Amount due: %.2f" % data["amount_due"])
        lines.append("Per patron: %.2f" % (data["amount_due"] / data["patrons"]))
    except KeyError as err:
        lines.append("Amount due unavailable (missing %s)" % err)
    except TypeError as err:
        lines.append("Amount due unavailable (%s)" % err)
    except ZeroDivisionError as err:
        lines.append("Cannot split the bill: %s" % err)
    for issue in issues:
        lines.append("  discrepancy: %s" % issue)
    return "\n".join(lines)


def main():
    orders = [
        {"table": "12", "patrons": "4", "food_cost": "88.50",
