    if text in ('true', 'yes', 'y', '1'):
        return True
    if text in ('false', 'no', 'n', '0'):
        return False
    raise ValueError("cannot interpret %r as a first time bidder flag" % (value,))


def validate(bid):
    details = {}
    warnings = []
    try:
        details['lot_number'] = int(bid['lot_number'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['bidder_id'] = int(bid['bidder_id'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['amount'] = float(bid['amount'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['max_proxy'] = float(bid['max_proxy'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['increment'] = float(bid['increment'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['shipping_zip'] = int(bid['shipping_zip'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['reputation'] = int(bid['reputation'])
    except Exception as err:
        warnings.append(str(err))
    try:
        details['first_time'] = _as_bool(bid['first_time'])
    except Exception as err:
        warnings.append(str(err))
    return details, warnings


def summarize(details, warnings):
    lines = []
    try:
        lines.append("lot %d: bidder %d offers %.2f" % (details['lot_number'],
                                                        details['bidder_id'],
                                                        details['amount']))
    except KeyError as err:
        lines.append("bid header incomplete, missing %s" % err)
    try:
        steps = int((details['max_proxy'] - details['amount']) / details['increment'])
        lines.append("proxy allows %d further raise(s)" % steps)
    except (KeyError, ZeroDivisionError) as err:
        lines.append("proxy schedule unavailable (%s)" % err)
    try:
        lines.append("ships to %05d, reputation %d, first time bidder: %s"
                     % (details['shipping_zip'], details['reputation'],
                        details['first_time']))
    except KeyError as err:
        lines.append("profile incomplete, missing %s" % err)
    for warning in warnings:
        lines.append("warning: %s" % warning)
    return "\n".join(lines)


def main():
    try:
        payload = json.loads(sys.stdin.read())
    except ValueError as err:
        sys.stderr.write("could not read bid feed: %s\n" % err)
        return 1
    bids = payload if isinstance(payload, list) else [payload]
    for bid in bids:
        details, warnings = validate(bid)
        print(summarize(details, warnings))
        print("-" * 40)
    return 0


if __name__ == '__main__':
    sys.exit(main())

