TRUE_WORDS = ("yes", "true", "y", "vegan")
FALSE_WORDS = ("no", "false", "n", "non-vegan")
FIELD_ORDER = ("calories", "total_fat", "saturated_fat", "protein",
               "carbohydrates", "sodium", "serving_size", "vegan")


def _as_int(raw):
    """Integer fields may arrive as '450' or as '450.0'."""
    try:
        return int(raw)
    except ValueError as err:
        try:
            return int(round(float(raw)))
        except ValueError as inner:
            raise ValueError("%s; %s" % (err, inner))


def _as_float(raw):
    """Float fields may carry a unit suffix such as '12.5 g'."""
    try:
        return float(raw)
    except ValueError as err:
        text = str(raw).strip().rstrip("gG").strip()
        try:
            return float(text)
        except ValueError as inner:
            raise ValueError("%s; %s" % (err, inner))


def _as_bool(raw):
    if isinstance(raw, bool):
        return raw
    text = str(raw).strip().lower()
    if text in TRUE_WORDS:
        return True
    if text in FALSE_WORDS:
        return False
    try:
        return bool(int(text))
    except ValueError as err:
        raise ValueError("unreadable vegan flag %r (%s)" % (raw, err))


def extract(menu):
    props = {}
    faults = []
