def parse_flag(value):
    """Convert a theater flag field into a real boolean."""
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ("true", "yes", "y", "1"):
        return True
    if text in ("false", "no", "n", "0"):
        return False
    raise ValueError("invalid flag value: %r" % (value,))


def parse(admission):
    """Extract the eight admission fields, collecting conversion errors."""
    data = {}
    errors = []
    try:
        data["screen"] = int(admission["screen"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["seat"] = int(admission["seat"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["price"] = float(admission["price"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["discount"] = float(admission["discount"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["age"] = int(admission["age"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["runtime"] = int(admission["runtime"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["matinee"] = parse_flag(admission["matinee"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    try:
        data["three_d"] = parse_flag(admission["three_d"])
    except (KeyError, ValueError, TypeError) as err:
        errors.append(str(err))
    return data, errors


def net_price(data):
    try:
        value = data["price"] * (1.0 - data["discount"])
    except KeyError as err:
        print("cannot compute net price, missing field %s" % err)
        return None
    return round(value, 2)


def format_runtime(data):
    try:
        minutes = data["runtime"]
    except KeyError as err:
        return "runtime unknown (missing %s)" % err
    return "%dh%02dm" % (minutes // 60, minutes % 60)


def admission_summary(data):
    parts = []
    try:
        parts.append("screen %d seat %d" % (data["screen"], data["seat"]))
    except KeyError as err:
        parts.append("location unknown (missing %s)" % err)
    try:
        parts.append("viewer age %d" % data["age"])
    except KeyError as err:
        parts.append("viewer age unknown (missing %s)" % err)
    if data.get("matinee"):
        parts.append("matinee")
    if data.get("three_d"):
        parts.append("3D")
    return ", ".join(parts)


def main():
    tickets = [
        {"screen": "4", "seat": "112", "price": "14.50", "discount": "0.10",
         "age": "adult", "runtime": "142", "matinee": "no", "three_d": "yes"},
        {"screen": "1", "seat": "7", "price": "9.00", "discount": "0",
         "age": "31", "runtime": "96", "matinee": "true", "three_d": "false"},
    ]
    for index, ticket in enumerate(tickets, 1):
        data, errors = parse(ticket)
        print("ticket %d: %s" % (index, admission_summary(data)))
        print("  runtime: %s" % format_runtime(data))
        print("  net price: %s" % net_price(data))
        for message in errors:
            print("  error: %s" % message)


if __name__ == "__main__":
    main()

