    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    try:
        data["unpaid_balance"] = float(membership["unpaid_balance"])
    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    try:
        data["locker_number"] = int(membership["locker_number"])
    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    try:
        data["guest_passes"] = int(membership["guest_passes"])
    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    try:
        data["pool_tier"] = int(membership["pool_tier"])
    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    try:
        data["lifetime_member"] = parse_bool(membership["lifetime_member"])
    except (KeyError, TypeError, ValueError) as err:
        issues.append(str(err))

    return data, issues


def report(data, issues):
    lines = []
    for key in sorted(data):
        lines.append("%-16s %s" % (key, data[key]))
    for message in issues:
        lines.append("ISSUE: %s" % message)
    return "\n".join(lines)


def main(argv):
    record = {
        "member_id": "4471",
        "join_year": "1998",
        "monthly_dues": "185.50",
        "unpaid_balance": "active",
        "locker_number": "204",
        "guest_passes": "3",
        "pool_tier": "2",
        "lifetime_member": "yes",
