LABELS = [
    "roast_time", "target_temp", "heating_rate", "primary_origin",
    "secondary_origin", "roaster", "operator", "batch_number",
]


def extract_batch(batch):
    details = []
    roast_time = None
    target_temp = None
    try:
        roast_time = int(batch["roast_time"])
        details.append(roast_time)
    except (KeyError, TypeError, ValueError) as err:
        details.append(str(err))
    try:
        target_temp = float(batch["target_temp"])
        details.append(target_temp)
    except (KeyError, TypeError, ValueError) as err:
        details.append(str(err))
    try:
        details.append(target_temp / roast_time)
    except (TypeError, ZeroDivisionError) as err:
        details.append(str(err))
    try:
        details.append(batch["origins"][0])
    except (KeyError, IndexError, TypeError) as err:
        details.append(str(err))
    try:
        details.append(batch["origins"][1])
    except (KeyError, IndexError, TypeError) as err:
        details.append(str(err))
    try:
        details.append(batch["roaster"]["machine"])
    except (KeyError, TypeError) as err:
        details.append(str(err))
    try:
        details.append(batch["operator"]["name"])
    except (KeyError, TypeError) as err:
        details.append(str(err))
    try:
        details.append(int(batch["batch_number"]))
    except (KeyError, TypeError, ValueError) as err:
        details.append(str(err))
    return details


def control(batches):
    return [extract_batch(batch) for batch in batches]


def average_heating_rate(rows):
    total = 0.0
    count = 0
    notes = []
    for position, row in enumerate(rows):
        try:
            total += row[2]
            count += 1
        except TypeError as err:
            notes.append("row %d skipped: %s" % (position, err))
    try:
        average = total / count
    except ZeroDivisionError as err:
        average = str(err)
    return average, notes


def describe_average(average):
    try:
        return "average heating rate: %.2f C/min" % average
    except TypeError as err:
        return "average heating rate unavailable (%s)" % err


def format_report(rows):
    lines = []
    for row in rows:
        parts = ["%s=%s" % (label, value) for label, value in zip(LABELS, row)]
        lines.append(" | ".join(parts))
    return lines


def main():
    batches = [
        {"roast_time": 12, "target_temp": "215.5",
         "origins": ["Ethiopia", "Colombia"],
         "roaster": {"machine": "Probat P12"},
         "operator": {"name": "Dana"}, "batch_number": "1041"},
        {"roast_time": 0, "target_temp": 198,
         "origins": ["Kenya"], "roaster": {},
         "operator": {"name": "Miguel"}, "batch_number": "1042"},
        {"roast_time": "fast", "target_temp": None,
         "origins": "Brazil", "roaster": {"machine": "Loring S15"},
         "operator": None, "batch_number": 1043},
    ]
    rows = control(batches)
    for line in format_report(rows):
        print(line)
    average, notes = average_heating_rate(rows)
    for note in notes:
        print(note)
    print(describe_average(average))


if __name__ == "__main__":
    main()

