import json
import sys


def compile(tricks):
    """Turn raw trick submissions into rows of eight judged data points."""
    rows = []
    for trick in tricks:
        row = []
        try:
            row.append(int(trick["air_time"]))
        except Exception as err:
            row.append(str(err))
        try:
            row.append(float(trick["rotation_degrees"]))
        except Exception as err:
            row.append(str(err))
        try:
            row.append(float(trick["rotation_degrees"]) / float(trick["air_time"]))
        except Exception as err:
            row.append(str(err))
        try:
            row.append(trick["stances"][0])
        except Exception as err:
            row.append(str(err))
        try:
            row.append(trick["stances"][1])
        except Exception as err:
            row.append(str(err))
        try:
            row.append(trick["obstacle"])
        except Exception as err:
            row.append(str(err))
        try:
            row.append(trick["location"])
        except Exception as err:
            row.append(str(err))
        try:
            row.append(int(trick["attempt"]))
        except Exception as err:
            row.append(str(err))
        rows.append(row)
    return rows


def average_spin(rows):
    """Average the spin rate column, reporting the rows that could not be used."""
    total = 0.0
    counted = 0
    problems = []
    for index, row in enumerate(rows):
        try:
            total += float(row[2])
            counted += 1
        except (ValueError, TypeError) as err:
            problems.append("row %d skipped: %s" % (index, err))
    if counted == 0:
        return None, problems
    return total / counted, problems


def format_report(rows):
    lines = []
    for index, row in enumerate(rows):
        cells = [str(item) for item in row]
        lines.append("trick %d: %s" % (index, " | ".join(cells)))
    return lines


def load_submissions(path):
    handle = open(path)
    try:
        return json.load(handle)
    finally:
        handle.close()


def main(argv):
    if len(argv) > 1:
        try:
            tricks = load_submissions(argv[1])
        except IOError as err:
            print("cannot read submissions: %s" % err)
            return 1
        except ValueError as err:
            print("malformed submission file: %s" % err)
            return 1
    else:
        tricks = [{"air_time": "not a number", "rotation_degrees": 540,
                   "stances": ["regular"], "obstacle": "handrail",
                   "location": "clip_07.mp4", "attempt": "3"}]
    rows = compile(tricks)
    for line in format_report(rows):
        print(line)
    average, problems = average_spin(rows)
    for problem in problems:
        print(problem)
    if average is None:
        print("no usable spin rates")
    else:
        print("average spin rate: %.2f" % average)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

