import json
import sys

LABELS = ("age", "height", "growth", "species", "subspecies",
          "soil", "fertilizer", "pruning")


def process(logs):
    results = []
    for log in logs:
        metrics = []
        age = None
        height = None
        try:
            age = int(log["age"])
        except (KeyError, TypeError, ValueError) as err:
            metrics.append(str(err))
        else:
            metrics.append(age)
        try:
            height = float(log["height"])
        except (KeyError, TypeError, ValueError) as err:
            metrics.append(str(err))
        else:
            metrics.append(height)
        try:
            metrics.append(height / age)
        except (TypeError, ZeroDivisionError) as err:
            metrics.append(str(err))
        try:
            metrics.append(log["species"][0])
        except (KeyError, IndexError, TypeError) as err:
            metrics.append(str(err))
        try:
            metrics.append(log["species"][1])
        except (KeyError, IndexError, TypeError) as err:
            metrics.append(str(err))
        try:
            metrics.append(log["soil"])
        except (KeyError, TypeError) as err:
            metrics.append(str(err))
        try:
            metrics.append(log["fertilizer"])
        except (KeyError, TypeError) as err:
            metrics.append(str(err))
        try:
            metrics.append(int(log["pruning"]))
        except (KeyError, TypeError, ValueError) as err:
            metrics.append(str(err))
        results.append(metrics)
    return results


def load_logs(path):
    try:
        handle = open(path)
    except IOError as err:
        sys.stderr.write("cannot read %s: %s\n" % (path, err))
        return []
    try:
        return json.load(handle)
    except ValueError as err:
        sys.stderr.write("malformed JSON in %s: %s\n" % (path, err))
        return []
    finally:
        handle.close()


def format_metric(value):
    try:
        return "%.2f" % value
    except TypeError as err:
        del err
        return str(value)


def report(rows):
    lines = []
    for index, row in enumerate(rows):
        for label, value in zip(LABELS, row):
            lines.append("log %d %s: %s" % (index, label, format_metric(value)))
    return "\n".join(lines)


def main():
    if len(sys.argv) > 1:
        logs = load_logs(sys.argv[1])
    else:
        try:
            logs = json.load(sys.stdin)
        except ValueError as err:
            sys.stderr.write("malformed JSON on stdin: %s\n" % err)
            return 1
    print(report(process(logs)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

