import json
import sys

LABELS = ["fuse delay", "radius", "expansion rate", "initial color",
          "fade color", "shell type", "launcher id", "sequence"]

DEFAULT_CONFIG = '[{"fuse_delay": "3", "explosion_radius": "12.5", "colors": []}]'


def choreograph(shows):
    results = []
    for show in shows:
        values = []
        try:
            values.append(int(show["fuse_delay"]))
        except (KeyError, TypeError, ValueError) as err:
            values.append(str(err))
        try:
            values.append(float(show["explosion_radius"]))
        except (KeyError, TypeError, ValueError) as err:
            values.append(str(err))
        try:
            values.append(float(show["explosion_radius"]) / int(show["fuse_delay"]))
        except (KeyError, TypeError, ValueError, ZeroDivisionError) as err:
            values.append(str(err))
        try:
            values.append(show["colors"][0])
        except (KeyError, TypeError, IndexError) as err:
            values.append(str(err))
        try:
            values.append(show["colors"][1])
        except (KeyError, TypeError, IndexError) as err:
            values.append(str(err))
        try:
            values.append(show["shell"])
        except (KeyError, TypeError) as err:
            values.append(str(err))
        try:
            values.append(show["launcher"])
        except (KeyError, TypeError) as err:
            values.append(str(err))
        try:
            values.append(int(show["sequence"]))
        except (KeyError, TypeError, ValueError) as err:
            values.append(str(err))
        results.append(values)
    return results


def format_report(results):
    lines = []
    for index, values in enumerate(results):
        lines.append("Show %d" % (index + 1))
        for label, value in zip(LABELS, values):
            if isinstance(value, str):
                lines.append("  %-15s ERROR %s" % (label, value))
            else:
                lines.append("  %-15s %s" % (label, value))
    return "\n".join(lines)


def load_shows(text):
    try:
        data = json.loads(text)
    except ValueError as err:
        print("unreadable configuration: %s" % err)
        return []
    if not isinstance(data, list):
        print("configuration must be a list of shows")
        return []
    return data


def main(argv):
    text = DEFAULT_CONFIG
    if len(argv) > 1:
        try:
            handle = open(argv[1])
        except IOError as err:
            print("cannot open %s: %s" % (argv[1], err))
            return 1
        try:
            text = handle.read()
        finally:
            handle.close()
    results = choreograph(load_shows(text))
    print(format_report(results))
    broken = sum(1 for values in results for value in values if isinstance(value, str))
    print("{0} show(s), {1} faulty value(s)".format(len(results), broken))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

