# -*- coding: utf-8 -*-
"""Ingest origami design instructions into flat records."""

from decimal import Decimal, InvalidOperation


def parse_one(instruction):
    """Parse a single instruction dictionary into a list of eight values."""
    record = []

    try:
        folds = int(instruction["folds"])
    except KeyError as err:
        folds = None
        record.append(str(err))
    except (ValueError, TypeError) as err:
        folds = None
        record.append(str(err))
    else:
        record.append(folds)

    try:
        size = Decimal(str(instruction["size"]))
    except KeyError as err:
        size = None
        record.append(str(err))
    except InvalidOperation as err:
        size = None
        record.append(str(err))
    else:
        record.append(size)

    try:
        record.append(Decimal(folds) / size)
    except ZeroDivisionError as err:
        record.append(str(err))
    except (TypeError, InvalidOperation) as err:
        record.append(str(err))

    try:
        record.append(instruction["shapes"][0])
    except KeyError as err:
        record.append(str(err))
    except IndexError as err:
        record.append(str(err))

    try:
        record.append(instruction["shapes"][1])
    except KeyError as err:
        record.append(str(err))
    except IndexError as err:
        record.append(str(err))

    try:
        record.append(instruction["texture"])
    except KeyError as err:
        record.append(str(err))

    try:
        record.append(instruction["creator"])
    except KeyError as err:
        record.append(str(err))

    try:
        record.append(int(instruction["difficulty"]))
    except KeyError as err:
        record.append(str(err))
    except (ValueError, TypeError) as err:
        record.append(str(err))

    return record


def parse(instructions):
    """Parse a list of instruction dictionaries into a list of records."""
    return [parse_one(instruction) for instruction in instructions]


def main():
    designs = [{"folds": 24, "size": 0, "shapes": ["square"],
                "texture": "washi", "difficulty": "hard"}]
    for record in parse(designs):
        for value in record:
            print("  %s" % (value,))


if __name__ == "__main__":
    main()

