def plan(firings):
    report = []
    for firing in firings:
        row = []
        try:
            row.append(int(firing['soak']))
        except KeyError as err:
            row.append(str(err))
        except ValueError as err:
            row.append(str(err))
        try:
            row.append(float(firing['peak']))
        except KeyError as err:
            row.append(str(err))
        except ValueError as err:
            row.append(str(err))
        try:
            row.append(float(firing['peak']) / int(firing['soak']))
        except KeyError as err:
            row.append(str(err))
        except ValueError as err:
            row.append(str(err))
        except ZeroDivisionError as err:
            row.append(str(err))
        try:
            row.append(firing['materials'][0])
        except KeyError as err:
            row.append(str(err))
        except IndexError as err:
            row.append(str(err))
        try:
            row.append(firing['materials'][1])
        except KeyError as err:
