        except KeyError as err:
            row.append(str(err))
        try:
            row.append(firing['operator'])
        except KeyError as err:
            row.append(str(err))
        try:
            row.append(int(firing['batch']))
        except KeyError as err:
            row.append(str(err))
        except ValueError as err:
            row.append(str(err))
        report.append(row)
    return report


def parse_firing(text):
    firing = {}
    for chunk in text.split(';'):
        chunk = chunk.strip()
        if not chunk:
            continue
        try:
            key, value = chunk.split('=')
        except ValueError as err:
            print('ignoring field %r: %s' % (chunk, err))
            continue
        if key == 'materials':
            firing[key] = value.split(',')
        else:
            firing[key] = value
    return firing


def average_rate(report):
    rates = []
    for row in report:
        try:
            rates.append(float(row[2]))
        except ValueError as err:
            print('no usable heating rate: %s' % err)
    if not rates:
        return None
    return sum(rates) / len(rates)


def main():
    sources = [
        'soak=90;peak=1250.5;materials=stoneware,celadon;shelf=middle;operator=Rin;batch=17',
        'soak=0;peak=1010;materials=porcelain;shelf top;operator=Ada;batch=x9',
    ]
    firings = [parse_firing(line) for line in sources]
    firings.append({})
    report = plan(firings)
    for row in report:
        print('; '.join([str(field) for field in row]))
    mean = average_rate(report)
    if mean is None:
        print('mean heating rate: unavailable')
    else:
        print('mean heating rate: %.3f degrees per minute' % mean)


if __name__ == '__main__':
    main()

