import sys

def parse_hours(record):
    try:
        return int(record["hours"])
    except KeyError as err:
        return "missing key: %s" % err
    except (ValueError, TypeError) as err:
        return str(err)


def parse_price(record):
    try:
        return float(record["price"])
    except KeyError as err:
        return "missing key: %s" % err
    except (ValueError, TypeError) as err:
        return str(err)


def hourly_rate(price, hours):
    try:
        return price / hours
    except ZeroDivisionError as err:
        return str(err)
    except TypeError as err:
        return str(err)


def pick_color(record, index):
    try:
        return record["colors"][index]
    except KeyError as err:
        return "missing key: %s" % err
    except IndexError as err:
        return str(err)
    except TypeError as err:
        return str(err)


def pick_field(record, name):
    try:
        return record[name]
    except KeyError as err:
        return "missing key: %s" % err
    except TypeError as err:
        return str(err)


def parse_age(record):
    try:
        return int(record["age"])
    except KeyError as err:
        return "missing key: %s" % err
    except (ValueError, TypeError) as err:
        return str(err)


def book(appointments):
    rows = []
    for record in appointments:
        hours = parse_hours(record)
        price = parse_price(record)
        rows.append([
            hours,
            price,
