    except Exception as err:
        row.append(str(err))
    try:
        row.append(routine["patterns"][0])
    except Exception as err:
        row.append(str(err))
    try:
        row.append(routine["patterns"][1])
    except Exception as err:
        row.append(str(err))
    try:
        row.append(routine["prop"])
    except Exception as err:
        row.append(str(err))
    try:
        row.append(routine["stage"])
    except Exception as err:
        row.append(str(err))
    try:
        row.append(int(routine["score"]))
    except Exception as err:
        row.append(str(err))
    return row


def evaluate(routines):
    rows = []
    for routine in routines:
        rows.append(extract_row(routine))
    return rows


def format_cell(value):
    try:
        return "%.2f" % value
    except TypeError as err:
        return "%s (%s)" % (value, err)


def format_row(row):
    return " | ".join([format_cell(cell) for cell in row])


def summarize(rows):
    rates = []
    problems = []
    for row in rows:
        try:
            rates.append(float(row[2]))
        except ValueError as err:
            problems.append(str(err))
    average = sum(rates) / len(rates) if rates else 0.0
    return {"average_drop_rate": average, "problems": problems}


def main():
    routines = [
        {"props": "5", "duration": "3.5", "patterns": ["cascade", "mills mess"],
