import json
import sys

DEFAULT_RECIPES = '[{"water_drops": "12", "pigment_grams": "4.5"}]'


def describe(element, err):
    return "%s unavailable (%s: %s)" % (element, type(err).__name__, err)


def calculate(mixtures):
    results = []
    for mixture in mixtures:
        row = []
        try:
            row.append(int(mixture["water_drops"]))
        except (KeyError, ValueError) as err:
            row.append(describe("water drops", err))
        try:
            row.append(float(mixture["pigment_grams"]))
        except (KeyError, ValueError) as err:
            row.append(describe("pigment grams", err))
        try:
            row.append(float(mixture["pigment_grams"]) / int(mixture["water_drops"]))
        except (KeyError, ValueError, ZeroDivisionError) as err:
            row.append(describe("concentration", err))
        try:
            row.append(mixture["tones"][0])
        except (KeyError, IndexError) as err:
            row.append(describe("base tone", err))
        try:
            row.append(mixture["tones"][1])
        except (KeyError, IndexError) as err:
            row.append(describe("highlight tone", err))
        try:
            row.append(mixture["binder"]["type"])
        except KeyError as err:
            row.append(describe("binder type", err))
        try:
            row.append(mixture["paper"]["match"])
        except KeyError as err:
            row.append(describe("paper match", err))
        try:
            row.append(int(mixture["age_days"]))
        except (KeyError, ValueError) as err:
            row.append(describe("mixture age", err))
        results.append(row)
    return results


def load_mixtures(path):
    try:
        handle = open(path)
    except IOError as err:
        sys.stderr.write("cannot open %s: %s\n" % (path, err))
        return None
    try:
        return handle.read()
    finally:
        handle.close()


def format_row(index, row):
    lines = ["mixture %d:" % (index + 1)]
    for value in row:
        if isinstance(value, float):
            lines.append("    %.4f" % value)
        else:
            lines.append("    %s" % value)
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        text = load_mixtures(argv[1])
        if text is None:
            return 1
    else:
        text = DEFAULT_RECIPES
    try:
        mixtures = json.loads(text)
    except ValueError as err:
        sys.stderr.write("invalid recipe data: %s\n" % err)
        return 1
    for index, row in enumerate(calculate(mixtures)):
        print(format_row(index, row))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

