def string_length(instrument):
    try:
        return int(instrument["length"])
    except (KeyError, TypeError, ValueError) as err:
        return str(err)


def pitch_frequency(instrument):
    try:
        return float(instrument["pitch"])
    except (KeyError, TypeError, ValueError) as err:
        return str(err)


def tension_coefficient(instrument):
    try:
        return float(instrument["pitch"]) / int(instrument["length"])
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as err:
        return str(err)


def wood(instrument, position):
    try:
        return instrument["woods"][position]
    except (KeyError, IndexError, TypeError) as err:
        return str(err)


def peg_style(instrument):
    try:
        return instrument["peg"]
    except (KeyError, TypeError) as err:
        return str(err)


def bridge_style(instrument):
    try:
        return instrument["bridge"]
    except (KeyError, TypeError) as err:
        return str(err)


def serial_code(instrument):
    try:
        return int(instrument["serial"])
    except (KeyError, TypeError, ValueError) as err:
        return str(err)


def calculate(instruments):
    results = []
    for instrument in instruments:
        results.append([
            string_length(instrument),
            pitch_frequency(instrument),
            tension_coefficient(instrument),
            wood(instrument, 0),
            wood(instrument, 1),
            peg_style(instrument),
            bridge_style(instrument),
            serial_code(instrument),
        ])
    return results


def total_length(rows):
    total = 0
    for row in rows:
