def evaluate(matches):
    report = []
    for match in matches:
        row = []
        try:
            row.append(int(match["duration"]))
        except (KeyError, ValueError, TypeError) as err:
            row.append(str(err))
        try:
            row.append(float(match["touches"]))
        except (KeyError, ValueError, TypeError) as err:
            row.append(str(err))
        try:
            row.append(float(match["touches"]) / int(match["duration"]))
        except (KeyError, ValueError, TypeError, ZeroDivisionError) as err:
            row.append(str(err))
        try:
            row.append(match["warnings"][0])
        except (KeyError, IndexError, TypeError) as err:
            row.append(str(err))
        try:
            row.append(match["warnings"][1])
        except (KeyError, IndexError, TypeError) as err:
            row.append(str(err))
        try:
            row.append(match["weapon"])
        except KeyError as err:
            row.append(str(err))
        try:
            row.append(match["referee"])
        except KeyError as err:
            row.append(str(err))
        try:
            row.append(int(match["yellow_cards"]))
        except (KeyError, ValueError, TypeError) as err:
            row.append(str(err))
        report.append(row)
    return report


def format_cell(value):
    try:
        return "%.2f" % value
    except TypeError as err:
        if isinstance(value, str):
            return value
        return "%s (%s)" % (value, err)


def format_row(row):
    return " | ".join([format_cell(cell) for cell in row])


def average_rate(report):
    total = 0.0
    counted = 0
    for row in report:
        try:
            total += float(row[2])
        except (ValueError, TypeError) as err:
            print("skipping rate: %s" % err)
            continue
        counted += 1
    try:
        return total / counted
    except ZeroDivisionError as err:
        print("no usable rates: %s" % err)
        return 0.0


def main():
    matches = [{
        "duration": 3,
        "touches": "15",
        "warnings": ["corps a corps", "turning back"],
        "weapon": "sabre",
        "referee": "M. Dubois",
        "yellow_cards": 1,
    }]
    report = evaluate(matches)
    for row in report:
        print(format_row(row))
    print("average touches per minute: %.2f" % average_rate(report))


if __name__ == "__main__":
    main()

