from decimal import Decimal, InvalidOperation

BEARINGS = {"c": "concave", "d": "flat", "k": "ko", "g": "grooved"}
PADS = {"slim": "slim silicone", "flow": "flowable", "cbc": "cbc pad", "none": "bare"}


def parse_combo(combo):
    fields = []
    try:
        fields.append(int(combo["string_length"]))
    except (KeyError, ValueError) as err:
        fields.append(str(err))
    try:
        fields.append(Decimal(combo["spin_time"]))
    except (KeyError, InvalidOperation) as err:
        fields.append(str(err))
    try:
        fields.append(Decimal(combo["spin_time"]) / int(combo["string_length"]))
    except (KeyError, ValueError, InvalidOperation, ZeroDivisionError) as err:
        fields.append(str(err))
    try:
        fields.append(combo["mounts"][0])
    except (KeyError, IndexError) as err:
        fields.append(str(err))
    try:
        fields.append(combo["mounts"][1])
    except (KeyError, IndexError) as err:
        fields.append(str(err))
    try:
        fields.append(BEARINGS[combo["bearing"]])
    except KeyError as err:
        fields.append(str(err))
    try:
        fields.append(PADS[combo["pad"]])
    except KeyError as err:
        fields.append(str(err))
    try:
        fields.append(int(combo["tricks"]))
    except (KeyError, ValueError) as err:
        fields.append(str(err))
    return fields


def score(combos):
    return [parse_combo(combo) for combo in combos]


def summarize(rows):
    tricks = 0
    efficiency = Decimal("0")
    counted = 0
    for position, row in enumerate(rows):
        try:
            tricks += int(row[7])
        except ValueError as err:
            print("combo %d trick count unusable: %s" % (position, err))
        try:
            efficiency += Decimal(row[2])
            counted += 1
        except InvalidOperation as err:
            print("combo %d efficiency unusable: %s" % (position, err))
    try:
        average = efficiency / counted
    except ZeroDivisionError as err:
        print("no measurable efficiency: %s" % err)
        average = Decimal("0")
    return tricks, average


def main():
