import sys


def parse_int(value):
    return int(value)


def parse_decimal(value):
    return float(value)


def extract_gem(gem):
    row = []

    try:
        facets = parse_int(gem["facets"])
        row.append(facets)
    except KeyError as err:
        facets = None
        row.append(str(err))
    except ValueError as err:
        facets = None
        row.append(str(err))

    try:
        carat = parse_decimal(gem["carat"])
        row.append(carat)
    except KeyError as err:
        carat = None
        row.append(str(err))
    except ValueError as err:
        carat = None
        row.append(str(err))

    try:
        row.append(carat / facets)
    except ZeroDivisionError as err:
        row.append(str(err))
    except TypeError as err:
        row.append(str(err))

    try:
        row.append(gem["angles"][0])
    except KeyError as err:
        row.append(str(err))
    except IndexError as err:
        row.append(str(err))

    try:
        row.append(gem["angles"][1])
    except KeyError as err:
        row.append(str(err))
    except IndexError as err:
        row.append(str(err))

    try:
        row.append(gem["cut"])
    except KeyError as err:
        row.append(str(err))

    try:
        row.append(gem["inclusion"])
    except KeyError as err:
        row.append(str(err))

    try:
        row.append(parse_int(gem["clarity"]))
    except KeyError as err:
        row.append(str(err))
    except ValueError as err:
        row.append(str(err))

    return row


def calculate(gems):
    return [extract_gem(gem) for gem in gems]


def format_report(rows):
    labels = ["facets", "carat", "carat/facet", "crown", "pavilion",
              "cut", "inclusion", "clarity"]
    lines = []
    for index, row in enumerate(rows):
        lines.append("Gem %d:" % (index + 1))
        for label, value in zip(labels, row):
            lines.append("  %-12s %s" % (label, value))
    return "\n".join(lines)


def main():
    stones = [{"facets": 0, "carat": "1.25", "angles": [34.5],
               "cut": "brilliant", "clarity": "not-a-number"}]
    report = format_report(calculate(stones))
    sys.stdout.write(report + "\n")


if __name__ == "__main__":
    main()

