def process(machines):
    """Extract eight independent details from each technician log entry."""
    results = []
    for machine in machines:
        row = []
        try:
            row.append(int(machine["flippers"]))
        except (KeyError, ValueError) as err:
            row.append(str(err))
        try:
            row.append(float(machine["tilt"]))
        except (KeyError, ValueError) as err:
            row.append(str(err))
        try:
            row.append(float(machine["tilt"]) / int(machine["flippers"]))
        except (KeyError, ValueError, ZeroDivisionError) as err:
            row.append(str(err))
        try:
            row.append(machine["ramps"][0])
        except (KeyError, IndexError) as err:
            row.append(str(err))
        try:
            row.append(machine["ramps"][1])
        except (KeyError, IndexError) as err:
            row.append(str(err))
        try:
            row.append(machine["bumper"])
        except KeyError as err:
            row.append(str(err))
        try:
            row.append(machine["display"])
        except KeyError as err:
            row.append(str(err))
        try:
            row.append(int(machine["error_code"]))
        except (KeyError, ValueError) as err:
            row.append(str(err))
        results.append(row)
    return results


FIELDS = ("flippers", "tilt", "tilt_ratio", "left_ramp", "right_ramp",
          "bumper", "display", "error_code")


def format_row(position, row):
    """Render one processed machine as a readable multi-field line."""
    parts = []
    for name, value in zip(FIELDS, row):
        parts.append("%s=%s" % (name, value))
    return "machine %d: %s" % (position, ", ".join(parts))


def summarize(results):
    """Average the usable tilt ratios and collect the failures met on the way."""
    ratios = []
    problems = []
    for row in results:
        try:
            ratios.append(float(row[2]))
        except ValueError as err:
            problems.append(str(err))
        try:
            code = int(row[7])
        except ValueError as err:
            problems.append(str(err))
        else:
            if code:
                problems.append("error code %d reported" % code)
    try:
        average = sum(ratios) / len(ratios)
    except ZeroDivisionError as err:
        average = str(err)
    return {"average_tilt_ratio": average, "problems": problems}


def main():
    machines = [
        {"flippers": "4", "tilt": "1.5", "ramps": [],
         "bumper": "pop", "error_code": "0"},
        {"flippers": "0", "tilt": "2.0", "ramps": ["left arch"],
         "display": "dot matrix", "error_code": "warm"},
    ]
    results = process(machines)
    for position, row in enumerate(results):
        print(format_row(position, row))
    report = summarize(results)
    print("average tilt ratio: %s" % report["average_tilt_ratio"])
    for problem in report["problems"]:
        print("problem: %s" % problem)


if __name__ == "__main__":
    main()

