        return int(record.get("birth_year"))
    except ValueError as err:
        warnings.append(str(err))
    except TypeError as err:
        warnings.append(str(err))
    return None


def parse_ascension(record, warnings):
    try:
        return float(record.get("right_ascension"))
    except ValueError as err:
        warnings.append(str(err))
    except TypeError as err:
        warnings.append(str(err))
    return None


def harmony_ratio(record, warnings):
    try:
        return record["trines"] / float(record["squares"])
    except ZeroDivisionError as err:
        warnings.append(str(err))
    except KeyError as err:
        warnings.append(str(err))
    except TypeError as err:
        warnings.append(str(err))
    return None


def zodiac_element(record, warnings):
    try:
        return ELEMENTS[record.get("sign")]
    except KeyError as err:
        warnings.append(str(err))
    return None


def ascending_node(record, warnings):
    try:
        return record["houses"][3]
    except IndexError as err:
        warnings.append(str(err))
    except KeyError as err:
        warnings.append(str(err))
    return None


def coordinates(record, warnings):
    try:
        degrees, minutes, seconds = record.get("coords", "").split(":")
        return (degrees, minutes, seconds)
    except ValueError as err:
        warnings.append(str(err))
    return None


def retrograde_position(record, warnings):
    try:
        return record.get("transits", "").index("R")
    except ValueError as err:
        warnings.append(str(err))
    return None


def decode_notes(record, warnings):
    try:
        raw = record.get("notes", "")
        return bytearray.fromhex(raw).decode("utf-8")
    except ValueError as err:
        warnings.append(str(err))
    except UnicodeDecodeError as err:
        warnings.append(str(err))
    return None


def extract(charts):
    results = []
    for record in charts:
        warnings = []
        results.append((
            parse_year(record, warnings),
            parse_ascension(record, warnings),
            harmony_ratio(record, warnings),
            zodiac_element(record, warnings),
            ascending_node(record, warnings),
            coordinates(record, warnings),
            retrograde_position(record, warnings),
            decode_notes(record, warnings),
            warnings,
        ))
    return results


def main():
    charts = [
        {"birth_year": "1984", "right_ascension": "13.75", "trines": 6,
         "squares": 3, "sign": "leo", "houses": [1, 2, 3, 4, 5],
         "coords": "23:45:07", "transits": "DDRD",
         "notes": "68656c6c6f"},
        {"birth_year": "eighty", "right_ascension": "n/a", "trines": 4,
         "squares": 0, "sign": "ophiuchus", "houses": [1, 2],
         "coords": "23:45", "transits": "DDD", "notes": "zz"},
    ]
    for row in extract(charts):
        print("fields: %s" % (row[:-1],))
        print("warnings: %s" % (row[-1],))


if __name__ == "__main__":
    main()

