        warnings.append(str(err))
    return None


def decode_preset_name(raw, warnings):
    try:
        data = binascii.unhexlify(raw)
    except binascii.Error as err:
        warnings.append(str(err))
        return None
    except TypeError as err:
        warnings.append(str(err))
        return None
    try:
        return data.decode("utf-8")
