def parse_offset(text, warnings):
    try:
        return float(text)
    except ValueError as err:
        warnings.append(str(err))
        return None


def clarity_ratio(text, warnings):
    parts = [p.strip() for p in text.split("/")]
    try:
        return float(parts[0]) / float(parts[1])
    except IndexError as err:
        warnings.append(str(err))
    except ValueError as err:
        warnings.append(str(err))
    except ZeroDivisionError as err:
        warnings.append(str(err))
    return None


def lookup_mode(code, warnings):
    try:
        return MODES[code]
    except KeyError as err:
        warnings.append(str(err))
        return None


def antenna_flag(text, warnings):
    equipment = [item.strip() for item in text.split(",")]
    try:
        return equipment[2]
    except IndexError as err:
        warnings.append(str(err))
        return None


def split_grid(text, warnings):
    try:
        region, sector, field = text.split("-")
    except ValueError as err:
        warnings.append(str(err))
        return None
    return (region, sector, field)


def distress_index(remarks, warnings):
    try:
        return remarks.index("!")
    except ValueError as err:
        warnings.append(str(err))
        return None


def decode_suffix(hex_text, warnings):
    try:
        return bytearray.fromhex(hex_text).decode("ascii")
    except ValueError as err:
        warnings.append(str(err))
        return None


def parse_entry(entry):
    warnings = []
    try:
        power, offset, snr, mode, equip, grid, remarks, suffix = [
            field.strip() for field in entry.split("|")]
    except ValueError as err:
        warnings.append(str(err))
        power = offset = snr = mode = equip = grid = remarks = suffix = ""
    values = (parse_power(power, warnings),
              parse_offset(offset, warnings),
              clarity_ratio(snr, warnings),
              lookup_mode(mode, warnings),
              antenna_flag(equip, warnings),
              split_grid(grid, warnings),
              distress_index(remarks, warnings),
              decode_suffix(suffix, warnings))
    return (values, warnings)


def validate(logs):
    return [parse_entry(entry) for entry in logs]


def format_report(results):
    lines = []
    for number, result in enumerate(results, 1):
        values, warnings = result
        lines.append("entry %d: %r" % (number, values))
        for warning in warnings:
            lines.append("    warning: %s" % warning)
    return "\n".join(lines)


def main():
    logs = ["100 | -1.5 | 40/8 | J3E | tuner, rotor, yagi | FN-31-pr | qrm ! qsb | 4b31",
            "hi | 12x | 40/0 | Z9Z | tuner, rotor | FN31pr | clear copy | 4b3",
            "5 | 0.0 | 9/3 | A1A | atu, mast, dipole | IO-91-wm | mayday ! | 4732"]
    print(format_report(validate(logs)))


if __name__ == "__main__":
    main()

