import binascii

REAGENTS = {"DPD": "diethyl-p-phenylenediamine", "NTA": "nitrate test additive",
            "PAR": "4-(2-pyridylazo)resorcinol"}
SATURATION_MARK = "#"


def parse_volume(raw, warnings):
    try:
        return int(raw)
    except (TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def parse_temperature(raw, warnings):
    try:
        return float(raw)
    except (TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def dilution_ratio(concentration, baseline, warnings):
    try:
        return concentration / baseline
    except (TypeError, ZeroDivisionError) as err:
        warnings.append(str(err))
        return None


def lookup_reagent(code, warnings):
    try:
        return REAGENTS[code]
    except (KeyError, TypeError) as err:
        warnings.append(str(err))
        return None


def trace_element(minerals, warnings):
    try:
        return minerals[1]
    except (IndexError, KeyError, TypeError) as err:
        warnings.append(str(err))
        return None


def split_schedule(raw, warnings):
    try:
        dawn, daylight, dusk = raw.split(",")
    except (AttributeError, ValueError) as err:
        warnings.append(str(err))
        return (None, None, None)
    return (dawn, daylight, dusk)


def saturation_position(oxygen, warnings):
    try:
        return oxygen.index(SATURATION_MARK)
    except (AttributeError, ValueError) as err:
        warnings.append(str(err))
        return None


def decode_notes(raw, warnings):
    try:
        return binascii.unhexlify(raw).decode("utf-8")
    except (TypeError, ValueError, UnicodeDecodeError) as err:
        warnings.append(str(err))
        return None


def evaluate(samples):
    report = []
    for sample in samples:
        warnings = []
        dawn, daylight, dusk = split_schedule(sample.get("lighting"), warnings)
        parsed = (parse_volume(sample.get("volume"), warnings),
                  parse_temperature(sample.get("temperature"), warnings),
                  dilution_ratio(sample.get("nitrate"), sample.get("baseline"), warnings),
                  lookup_reagent(sample.get("reagent"), warnings),
                  trace_element(sample.get("minerals"), warnings),
                  dawn, daylight, dusk,
                  saturation_position(sample.get("oxygen"), warnings),
                  decode_notes(sample.get("notes"), warnings))
        report.append((parsed, warnings))
    return report


def clean_fraction(report):
    clean = len([1 for parsed, warnings in report if not warnings])
    try:
        return 100.0 * clean / len(report)
    except ZeroDivisionError as err:
        print("no samples analysed: %s" % err)
        return 0.0


def main():
    samples = [{"volume": "1200", "temperature": "21.5", "nitrate": 8.0, "baseline": 4.0,
                "reagent": "DPD", "minerals": ["Ca", "Mg", "Fe"], "lighting": "2,10,3",
                "oxygen": "abc#def", "notes": "66696c746572"},
               {"volume": "n/a", "temperature": None, "nitrate": 5.0, "baseline": 0,
                "reagent": "XYZ", "minerals": ["Ca"], "lighting": "6,18",
                "oxygen": 42, "notes": "zz"}]
    report = evaluate(samples)
    for index, entry in enumerate(report):
        parsed, warnings = entry
        print("sample %d: %s" % (index, parsed))
        for message in warnings:
            print("  warning: %s" % message)
    print("clean samples: %.1f%%" % clean_fraction(report))


if __name__ == "__main__":
    main()

