import binascii

WEATHER_CODES = {
    "W0": "clear",
    "W1": "rain",
    "W2": "fog",
    "W3": "storm",
    "W4": "snow",
}


def parse_turn(raw):
    try:
        return int(raw), None
    except (TypeError, ValueError) as err:
        return None, str(err)


def parse_multiplier(raw):
    try:
        return float(raw), None
    except (TypeError, ValueError) as err:
        return None, str(err)


def distribution_ratio(tokens, players):
    try:
        return float(tokens) / float(players), None
    except (TypeError, ValueError, ZeroDivisionError) as err:
        return None, str(err)


def lookup_weather(code):
    try:
        return WEATHER_CODES[code], None
    except (KeyError, TypeError) as err:
        return None, str(err)


def next_event_card(deck):
    try:
        return deck[0], None
    except (IndexError, KeyError, TypeError) as err:
        return None, str(err)


def parse_grid_position(raw):
    try:
        q, r, s = raw.split(",")
    except (ValueError, AttributeError) as err:
        return None, str(err)
    return (q.strip(), r.strip(), s.strip()), None


def find_collision(layout, marker):
    try:
        return layout.index(marker), None
    except (ValueError, AttributeError) as err:
        return None, str(err)


def decode_objective(raw):
    try:
        return binascii.unhexlify(raw.strip()).decode("utf-8"), None
    except (ValueError, TypeError, AttributeError) as err:
        return None, str(err)


def parse_state(state):
    warnings = []
    parsed = {}
    fields = [
        ("turn", parse_turn, ("turn",)),
        ("multiplier", parse_multiplier, ("multiplier",)),
        ("ratio", distribution_ratio, ("tokens", "players")),
        ("weather", lookup_weather, ("weather_code",)),
        ("event_card", next_event_card, ("deck",)),
        ("position", parse_grid_position, ("coordinates",)),
        ("objective", decode_objective, ("objective_hex",)),
    ]
    for name, parser, keys in fields:
        try:
            args = [state.get(key) for key in keys]
        except AttributeError as err:
            warnings.append(str(err))
            parsed[name] = None
            continue
        value, problem = parser(*args)
        parsed[name] = value
        if problem is not None:
            warnings.append(problem)
    value, problem = find_collision(state.get("layout"), state.get("marker", "X"))
    parsed["collision"] = value
    if problem is not None:
        warnings.append(problem)
    return parsed, warnings


def evaluate(states):
    try:
        sequence = list(states)
    except TypeError as err:
        return [], [[str(err)]]
    parsed_states = []
    all_warnings = []
    for state in sequence:
        parsed, warnings = parse_state(state)
        parsed_states.append(parsed)
        all_warnings.append(warnings)
    return parsed_states, all_warnings


def format_report(parsed, warnings):
    try:
        ratio = "%.2f" % parsed["ratio"]
    except TypeError as err:
        ratio = "unavailable (%s)" % err
    return "turn=%s weather=%s ratio=%s objective=%s warnings=%d" % (
        parsed["turn"], parsed["weather"], ratio, parsed["objective"], len(warnings))


def main():
    saves = [
        {"turn": "12", "multiplier": "1.5", "tokens": 30, "players": 4,
         "weather_code": "W2", "deck": ["Ambush", "Harvest"],
         "coordinates": "3, -1, -2", "layout": "..X...",
         "objective_hex": "426c6f636b20746865206272696467 65".replace(" ", "")},
        {"turn": "eight", "multiplier": None, "tokens": 12, "players": 0,
         "weather_code": "W9", "deck": [], "coordinates": "1,2",
         "layout": "......", "objective_hex": "zzzz"},
    ]
    parsed_states, all_warnings = evaluate(saves)
    for parsed, warnings in zip(parsed_states, all_warnings):
        print(format_report(parsed, warnings))
        for warning in warnings:
            print("  ! " + warning)


if __name__ == "__main__":
    main()

