        ratio = None

    try:
        glass = GLASSWARE[recipe["presentation"]]
    except KeyError as err:
        warnings.append(str(err))
        glass = None

    try:
        garnish = recipe["decorations"][0]
    except (IndexError, KeyError, TypeError) as err:
        warnings.append(str(err))
        garnish = None

    try:
        technique, duration, ice = recipe["method"].split("-")
    except (ValueError, AttributeError, KeyError) as err:
