    try:
        mark_index = recipe["ingredients"].index(SUB_MARK)
    except (ValueError, AttributeError, KeyError) as err:
        warnings.append(str(err))
        mark_index = None

    try:
        profile = binascii.unhexlify(recipe["profile_hex"]).decode("utf-8")
    except (ValueError, TypeError, KeyError) as err:
