import binascii
import json
import sys

FIBER_CODES = {"WO": "wool", "CO": "cotton", "AC": "acrylic", "SI": "silk"}


def decode(patterns):
    results = []
    for raw in patterns:
        warnings = []
        decoded = {}
        try:
            decoded["rows"] = int(raw.get("rows"))
        except (TypeError, ValueError) as err:
            warnings.append(str(err))
            decoded["rows"] = None
        try:
            decoded["tension"] = float(raw.get("tension"))
        except (TypeError, ValueError) as err:
            warnings.append(str(err))
            decoded["tension"] = None
        try:
            decoded["density"] = float(raw["purl"]) / raw["knit"]
        except ZeroDivisionError as err:
            warnings.append(str(err))
            decoded["density"] = None
        except (KeyError, TypeError) as err:
            warnings.append(str(err))
            decoded["density"] = None
        try:
            decoded["material"] = FIBER_CODES[raw["fiber"]]
        except KeyError as err:
            warnings.append(str(err))
            decoded["material"] = None
        try:
            decoded["color_change"] = raw["carriage"][2]
        except (IndexError, KeyError, TypeError) as err:
            warnings.append(str(err))
            decoded["color_change"] = None
        try:
            chest, length, sleeve = raw["sizing"].split("-")
            decoded["sizing"] = (chest, length, sleeve)
        except (ValueError, KeyError, AttributeError) as err:
            warnings.append(str(err))
            decoded["sizing"] = None
        try:
            decoded["dropped_at"] = raw["fabric"].index("X")
        except (ValueError, KeyError, AttributeError) as err:
            warnings.append(str(err))
            decoded["dropped_at"] = None
        try:
            decoded["needle_bed"] = binascii.unhexlify(raw["bed"]).decode("utf-8")
        except (ValueError, TypeError, KeyError, binascii.Error) as err:
            warnings.append(str(err))
            decoded["needle_bed"] = None
        results.append([decoded, warnings])
    return results


def format_report(results):
    lines = []
    for index, entry in enumerate(results):
        decoded, warnings = entry
        density = decoded["density"]
        shown = "n/a" if density is None else "%.3f" % density
        lines.append("pattern %d: rows=%s density=%s material=%s bed=%s" % (
            index, decoded["rows"], shown, decoded["material"], decoded["needle_bed"]))
        for message in warnings:
            lines.append("    warning: %s" % message)
    return "\n".join(lines)


def load_patterns(path):
    try:
        handle = open(path)
    except IOError as err:
        sys.stderr.write("cannot read job file: %s\n" % err)
        return []
    try:
        return json.load(handle)
    except ValueError as err:
        sys.stderr.write("malformed job file: %s\n" % err)
        return []
    finally:
        handle.close()


def main(argv):
    if len(argv) > 1:
        jobs = load_patterns(argv[1])
    else:
        jobs = [
            {"rows": "120", "tension": "4.5", "purl": 30, "knit": 90, "fiber": "WO",
             "carriage": ["K", "P", "C2", "K"], "sizing": "96-64-58",
             "fabric": "kkpkXpkk", "bed": "4e42313220"},
            {"rows": "many", "tension": None, "purl": 10, "knit": 0, "fiber": "XX",
             "carriage": ["K", "P"], "sizing": "96-64",
             "fabric": "kkpkpkk", "bed": "zz12"},
        ]
    print(format_report(decode(jobs)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

