    except (ValueError, TypeError) as err:
        warnings.append(str(err))
        return None


def parse_wingspan(record, warnings):
    try:
        return float(record.get("wingspan"))
    except (ValueError, TypeError) as err:
        warnings.append(str(err))
        return None


def parse_distance_ratio(record, warnings):
    try:
        return record.get("latitude_shift") / record.get("travel_distance")
    except (ZeroDivisionError, TypeError) as err:
        warnings.append(str(err))
        return None


def parse_plumage(record, warnings):
    try:
        return PLUMAGE[record.get("species_code")]
    except KeyError as err:
        warnings.append(str(err))
        return None


def parse_primary_song(record, warnings):
    try:
        return record.get("song_sequence")[0]
    except (IndexError, TypeError) as err:
        warnings.append(str(err))
        return None


def parse_habitat(record, warnings):
    try:
        biome, elevation, water = record.get("habitat").split(",")
    except (ValueError, AttributeError) as err:
        warnings.append(str(err))
        return None
    return (biome.strip(), elevation.strip(), water.strip())


def parse_band_position(record, warnings):
    try:
        return record.get("physical").index("B")
    except (ValueError, AttributeError) as err:
        warnings.append(str(err))
        return None


def parse_notebook(record, warnings):
    try:
        raw = bytearray.fromhex(record.get("notebook_hex"))
    except (ValueError, TypeError) as err:
        warnings.append(str(err))
        return None
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as err:
        warnings.append(str(err))
        return None


def validate(sightings):
    results = []
    for record in sightings:
        warnings = []
        details = {
            "flock_size": parse_flock_size(record, warnings),
            "wingspan": parse_wingspan(record, warnings),
            "distance_ratio": parse_distance_ratio(record, warnings),
            "plumage": parse_plumage(record, warnings),
            "primary_song": parse_primary_song(record, warnings),
            "habitat": parse_habitat(record, warnings),
            "band_position": parse_band_position(record, warnings),
            "notebook": parse_notebook(record, warnings),
        }
        results.append((details, warnings))
    return results


