import binascii

WEATHER_CODES = {
    "CLR": "clear skies",
    "SNW": "heavy snowfall",
    "WND": "high winds",
    "FOG": "dense fog",
}
HAZARD_MARK = "X"


def read_altitude(record, warnings):
    try:
        return int(record["basecamp_altitude"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_oxygen(record, warnings):
    try:
        return float(record["oxygen_saturation"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_ascent_rate(record, warnings):
    try:
        return record["vertical_gain"] / record["hours_elapsed"]
    except (KeyError, TypeError, ZeroDivisionError) as err:
        warnings.append(str(err))
        return None


def read_forecast(record, warnings):
    try:
        return WEATHER_CODES[record["weather_code"]]
    except (KeyError, TypeError) as err:
        warnings.append(str(err))
        return None


def read_secondary_check(record, warnings):
    try:
        return record["gear_sequence"][2]
    except (KeyError, IndexError, TypeError) as err:
        warnings.append(str(err))
        return None


def read_team(record, warnings):
    try:
        leader, guide, porter = record["team"].split("/")
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append(str(err))
        return None
    return (leader, guide, porter)


def read_hazard_index(record, warnings):
    try:
        return record["route_condition"].index(HAZARD_MARK)
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_contact(record, warnings):
    try:
        return binascii.unhexlify(record["emergency_contact"]).decode("utf-8")
    except (KeyError, TypeError, ValueError, binascii.Error) as err:
        warnings.append(str(err))
        return None


def parse(logs):
    results = []
    for entry in logs:
        warnings = []
        try:
            record = dict(entry)
        except (TypeError, ValueError) as err:
            warnings.append(str(err))
            results.append((None, warnings))
            continue
        parsed = (
            read_altitude(record, warnings),
            read_oxygen(record, warnings),
            read_ascent_rate(record, warnings),
            read_forecast(record, warnings),
            read_secondary_check(record, warnings),
            read_team(record, warnings),
            read_hazard_index(record, warnings),
            read_contact(record, warnings),
        )
        results.append((parsed, warnings))
    return results

