import binascii

BINDING_CODES = {
    "MOR": "morocco leather",
    "VEL": "vellum",
    "CLO": "buckram cloth",
    "CAL": "calfskin",
}
FOXING_MARK = "*"


def parse_year(raw, warnings):
    try:
        return int(raw)
    except ValueError as err:
        warnings.append(str(err))
        return None


def parse_value(raw, warnings):
    try:
        return float(raw)
    except ValueError as err:
        warnings.append(str(err))
        return None


def preservation_ratio(intact, total, warnings):
    try:
        return intact / float(total)
    except ZeroDivisionError as err:
        warnings.append(str(err))
    except ValueError as err:
        warnings.append(str(err))
    except TypeError as err:
        warnings.append(str(err))
    return None


def binding_material(code, warnings):
    try:
        return BINDING_CODES[code]
    except KeyError as err:
        warnings.append(str(err))
        return None


def secondary_provenance(signatures, warnings):
    try:
        return signatures[2]
    except IndexError as err:
        warnings.append(str(err))
        return None


def unpack_dimensions(raw, warnings):
    try:
        height, width, depth = raw.split("x")
        return (height, width, depth)
    except ValueError as err:
        warnings.append(str(err))
        return None


def foxing_position(paper, warnings):
    try:
        return paper.index(FOXING_MARK)
    except ValueError as err:
        warnings.append(str(err))
        return None


def decode_restorer_notes(raw, warnings):
    try:
        return binascii.unhexlify(raw).decode("utf-8")
    except ValueError as err:
        warnings.append(str(err))
    except TypeError as err:
        warnings.append(str(err))
    return None


def appraise(books):
    results = []
    for book in books:
        warnings = []
        record = {
            "title": book["title"],
            "year": parse_year(book["year"], warnings),
            "value": parse_value(book["value"], warnings),
            "preservation": preservation_ratio(book["intact_pages"], book["total_pages"], warnings),
            "binding": binding_material(book["binding_code"], warnings),
            "provenance": secondary_provenance(book["signatures"], warnings),
            "dimensions": unpack_dimensions(book["dimensions"], warnings),
            "foxing_at": foxing_position(book["paper"], warnings),
            "notes": decode_restorer_notes(book["restorer_notes"], warnings),
        }
        results.append((record, warnings))
    return results


def format_appraisal(record, warnings):
    lines = ["%s [%s]" % (record["title"], record["year"])]
    try:
        lines.append("  estimate: $%.2f" % record["value"])
    except TypeError as err:
        lines.append("  estimate: unavailable (%s)" % err)
    lines.append("  binding: %s, provenance: %s" % (record["binding"], record["provenance"]))
    lines.append("  notes: %s" % record["notes"])
    for message in warnings:
        lines.append("  warning: %s" % message)
    return "\n".join(lines)


def main():
    books = [
        {"title": "Hortus Sanitatis", "year": "1491", "value": "12500.50",
         "intact_pages": 470, "total_pages": 512, "binding_code": "VEL",
         "signatures": ["Aa", "Bb", "Cc"], "dimensions": "31x21x6",
         "paper": "laid rag *edge", "restorer_notes": "72657365776e"},
        {"title": "Codex Marginalia", "year": "MDCII", "value": "n/a",
         "intact_pages": 300, "total_pages": 0, "binding_code": "SLK",
         "signatures": ["Aa", "Bb"], "dimensions": "24x17",
         "paper": "wove clean", "restorer_notes": "zzq1"},
    ]
    for record, warnings in appraise(books):
        print(format_appraisal(record, warnings))


if __name__ == "__main__":
    main()

