import binascii

HULL_SIGNATURES = {
    "0A": "steel hull",
    "0B": "composite hull",
    "0C": "biological mass",
    "0D": "rock outcrop",
}


def read_ping_delay(echo, warnings):
    try:
        return int(echo["return_ping_delay"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_thermocline_shift(echo, warnings):
    try:
        return float(echo["thermocline_depth_shift"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_density_ratio(echo, warnings):
    try:
        return echo["primary_echo_strength"] / echo["secondary_echo_strength"]
    except (KeyError, TypeError, ZeroDivisionError) as err:
        warnings.append(str(err))
        return None


def read_signature(echo, warnings):
    try:
        return HULL_SIGNATURES[echo["hull_reflection_code"]]
    except (KeyError, TypeError) as err:
        warnings.append(str(err))
        return None


def read_biological_interference(echo, warnings):
    try:
        return echo["background_noise"][1]
    except (KeyError, IndexError, TypeError) as err:
        warnings.append(str(err))
        return None


def read_trajectory(echo, warnings):
    try:
        heading, pitch, velocity = echo["vector_trajectory"].split()
        return (heading, pitch, velocity)
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_cavitation_index(echo, warnings):
    try:
        return echo["frequency_spectrum"].index("~")
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append(str(err))
        return None


def read_survey_notes(echo, warnings):
    try:
        return binascii.unhexlify(echo["survey_notes_hex"]).decode("utf-8")
    except (KeyError, TypeError, ValueError, UnicodeDecodeError) as err:
        warnings.append(str(err))
        return None


def decode(echos):
    results = []
    for echo in echos:
        warnings = []
        reflection = [
            read_ping_delay(echo, warnings),
            read_thermocline_shift(echo, warnings),
            read_density_ratio(echo, warnings),
            read_signature(echo, warnings),
            read_biological_interference(echo, warnings),
            read_trajectory(echo, warnings),
            read_cavitation_index(echo, warnings),
            read_survey_notes(echo, warnings),
        ]
        results.append((reflection, warnings))
    return results


def mean_density_ratio(results):
    ratios = [data[2] for data, warnings in results if data[2] is not None]
    try:
        return sum(ratios) / len(ratios)
    except ZeroDivisionError as err:
        print("density averaging skipped: %s" % err)
        return None


def main():
    echos = [
        {"return_ping_delay": "412", "thermocline_depth_shift": "18.5",
         "primary_echo_strength": 90.0, "secondary_echo_strength": 30.0,
         "hull_reflection_code": "0B", "background_noise": [3, 7, 11],
         "vector_trajectory": "271 -4 12.5", "frequency_spectrum": "aabb~cc",
         "survey_notes_hex": "77726563"},
        {"return_ping_delay": "deep", "thermocline_depth_shift": None,
         "primary_echo_strength": 40.0, "secondary_echo_strength": 0.0,
         "hull_reflection_code": "0Z", "background_noise": [5],
         "vector_trajectory": "180 6", "frequency_spectrum": "aabbcc",
         "survey_notes_hex": "zz01"},
    ]
    for data, warnings in decode(echos):
        print("reflection: %s" % (data,))
        for note in warnings:
            print("  warning: %s" % note)
    print("mean density ratio: %s" % mean_density_ratio(decode(echos)))


if __name__ == "__main__":
    main()

