        except ValueError as err:
            warnings.append("instruction field %r: %s" % (part, err))
            continue
        fields[key.strip()] = value.strip()
    return fields


def read_fade(fields, warnings):
    try:
        return int(fields["fade_ms"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append("fade duration: %s" % err)
        return None


def read_intensity(fields, warnings):
    try:
        return float(fields["intensity"])
    except (KeyError, TypeError, ValueError) as err:
        warnings.append("intensity: %s" % err)
        return None


def read_contrast(fields, warnings):
    try:
        return float(fields["key_watts"]) / float(fields["fill_watts"])
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as err:
        warnings.append("contrast ratio: %s" % err)
        return None


def read_gel(fields, warnings):
    try:
        return GEL_COLORS[fields["gel_code"]]
    except KeyError as err:
        warnings.append("gel lookup: %s" % err)
        return None


def read_follow_spot(fields, warnings):
    try:
        return fields["fixtures"].split(",")[3]
    except (KeyError, AttributeError, IndexError) as err:
        warnings.append("follow spot: %s" % err)
        return None


def read_zones(fields, warnings):
    try:
        upstage, downstage, center = fields["zones"].split("/")
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append("stage zones: %s" % err)
        return (None, None, None)
    return (upstage, downstage, center)


def read_strobe(fields, warnings):
    try:
        return fields["description"].index("*")
    except (KeyError, AttributeError, ValueError) as err:
        warnings.append("strobe marker: %s" % err)
        return None


def read_notes(fields, warnings):
    import binascii
    try:
        return binascii.unhexlify(fields["notes_hex"]).decode("utf-8")
    except (KeyError, TypeError, ValueError, binascii.Error) as err:
        warnings.append("director notes: %s" % err)
        return None


def evaluate(cues):
    results = []
    for cue in cues:
        warnings = []
        if isinstance(cue, dict):
            fields = cue
        else:
            fields = parse_instruction(cue, warnings)
        upstage, downstage, center = read_zones(fields, warnings)
        data = {
            "fade_ms": read_fade(fields, warnings),
            "intensity": read_intensity(fields, warnings),
            "contrast": read_contrast(fields, warnings),
            "gel": read_gel(fields, warnings),
            "follow_spot": read_follow_spot(fields, warnings),
            "upstage": upstage,
            "downstage": downstage,
            "center": center,
            "strobe_index": read_strobe(fields, warnings),
            "notes": read_notes(fields, warnings),
        }
        results.append((data, warnings))
    return results


def format_report(results):
    lines = []
    total = 0.0
    graded = 0
    for data, warnings in results:
        lines.append("gel=%s spot=%s fade=%sms notes=%s issues=%d" % (
            data["gel"], data["follow_spot"], data["fade_ms"],
            data["notes"], len(warnings)))
        for message in warnings:
            lines.append("    ! %s" % message)
        if data["contrast"] is not None:
            total += data["contrast"]
            graded += 1
    try:
        average = total / graded
    except ZeroDivisionError as err:
        lines.append("average contrast unavailable: %s" % err)
    else:
        lines.append("average contrast: %.2f" % average)
    return "\n".join(lines)


def main(argv):
