        "fade_ms=1200;intensity=85.5;key_watts=750;fill_watts=300;"
        "gel_code=R02;fixtures=par1,par2,led3,spot4;zones=US/DS/CS;"
        "description=slow *strobe swell;notes_hex=48656c6c6f",
        "fade_ms=fast;intensity=;key_watts=500;fill_watts=0;"
        "gel_code=X99;fixtures=par1,par2;zones=US/DS;"
        "description=smooth cross;notes_hex=zz",
    ]
    threshold = 0.0
    if len(argv) > 1:
        try:
            threshold = float(argv[1])
        except ValueError as err:
            print("ignoring threshold (%s), using %.1f" % (err, threshold))
    results = evaluate(cues)
    kept = [item for item in results
            if item[0]["intensity"] is None or item[0]["intensity"] >= threshold]
    print(format_report(kept))


if __name__ == "__main__":
    import sys
    main(sys.argv)

