    try:
        fields = packet.split()
        temperature, acidity, sulfur, pressure, turbidity, rumble, radius, flow = fields
    except ValueError as err:
        return [str(err)]
    ordered = (temperature, acidity, sulfur, pressure, turbidity, rumble, radius, flow)
    return [helper(raw) for helper, raw in zip(HELPERS, ordered)]


def average_reading(values):
    numbers = [v for v in values if isinstance(v, float) or isinstance(v, int)]
    try:
        return sum(numbers) / float(len(numbers))
    except ZeroDivisionError as err:
        return str(err)


def format_report(packet):
    values = decode(packet)
    lines = ['packet: ' + packet]
    for label, value in zip(LABELS, values):
        lines.append('  %-12s %s' % (label, value))
    lines.append('  mean of usable readings: %s' % average_reading(values))
    return '\n'.join(lines)


