import sys

LABELS = ("wind speed", "grain size", "dune height", "movement angle",
          "moisture content", "obstacle presence", "solar reflection",
          "compaction ratio")


def process_wind_speed(raw):
    try:
        return float(raw)
    except ValueError as err:
        return str(err)


def process_grain_size(raw):
    try:
        return int(raw)
    except ValueError as err:
        return str(err)


def process_dune_height(raw):
    try:
        return float(raw)
    except ValueError as err:
        return str(err)


def process_movement_angle(raw):
    try:
        angle = int(raw)
    except ValueError as err:
        return str(err)
    return angle % 360


def process_moisture_content(raw):
    try:
        return 100.0 / int(raw)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def process_obstacle_presence(raw):
    try:
        return raw[4]
    except IndexError as err:
        return str(err)


def process_solar_reflection(raw):
    try:
        numerator, denominator = raw.split("/")
    except ValueError as err:
        return str(err)
    try:
        return float(numerator) / float(denominator)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def process_compaction_ratio(raw):
    try:
        return int(raw, 16)
    except ValueError as err:
        return str(err)


def model(attributes):
    handlers = (process_wind_speed, process_grain_size, process_dune_height,
                process_movement_angle, process_moisture_content,
                process_obstacle_presence, process_solar_reflection,
                process_compaction_ratio)
    return [handler(raw) for handler, raw in zip(handlers, attributes)]


def read_attributes(argv):
    if len(argv) != 8:
        raise ValueError("expected 8 attribute strings, got %d" % len(argv))
    return list(argv)


def format_report(outcomes):
    lines = []
    for label, outcome in zip(LABELS, outcomes):
        lines.append("%-18s %s" % (label + ":", outcome))
    return "\n".join(lines)


def main(argv):
    try:
        attributes = read_attributes(argv)
    except ValueError as err:
        sys.stderr.write("input error: %s\n" % err)
        return 2
    print(format_report(model(attributes)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

