def parse_iron(text):
    try:
        return float(text)
    except ValueError as err:
        return str(err)


def parse_silicon_ratio(text):
    try:
        numerator, denominator = text.split('/')
        return float(numerator) / float(denominator)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def parse_velocity(text):
    try:
        return int(text, 16)
    except ValueError as err:
        return str(err)


def parse_mass(text):
    try:
        return int(text)
    except ValueError as err:
        return str(err)


def parse_radiation(text):
    try:
        return int(text)
    except ValueError as err:
        return str(err)


def parse_magnetic(text):
    try:
        return 100.0 / int(text)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def parse_albedo(text):
    try:
        return text[2]
    except IndexError as err:
        return str(err)


def assess(fragment):
    fields = [part.strip() for part in fragment.split(',')]
    try:
        nickel, iron, silicon, velocity, mass, radiation, magnetic, albedo = fields
    except ValueError as err:
        return [str(err)]
    return [parse_nickel(nickel), parse_iron(iron), parse_silicon_ratio(silicon),
            parse_velocity(velocity), parse_mass(mass), parse_radiation(radiation),
            parse_magnetic(magnetic), parse_albedo(albedo)]


def report(fragment):
    results = assess(fragment)
    if len(results) != len(LABELS):
        return "malformed record: %s" % results[0]
    lines = []
    for label, value in zip(LABELS, results):
        lines.append("%-20s %s" % (label, value))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        try:
            handle = open(argv[1])
        except IOError as err:
            sys.stderr.write("cannot read spectrum file: %s\n" % err)
            return 1
        try:
            records = handle.readlines()
        finally:
            handle.close()
    else:
        records = sys.stdin.readlines()
    for record in records:
        if record.strip():
            print(report(record))
            print("-" * 40)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

