    """Split a raw buoy line into its eight fields."""
    fields = [part.strip() for part in line.split(',')]
    try:
        height, length, speed, depth, wind, crest, trough, battery = fields
    except ValueError as err:
        raise ValueError("malformed record %r (%s)" % (line, err))
    return [height, length, speed, depth, wind, crest, trough, battery]


