    try:
        return float(value)
    except (TypeError, ValueError) as err:
        return str(err)


def wavelength(value):
    try:
        return int(value)
    except (TypeError, ValueError) as err:
        return str(err)


def propagation_speed(value):
    try:
        return float(value)
    except (TypeError, ValueError) as err:
        return str(err)


def water_depth(value):
    try:
        return int(value)
    except (TypeError, ValueError) as err:
        return str(err)


def wind_resistance(value):
    try:
        return 200 / int(value)
    except ZeroDivisionError as err:
        return str(err)
    except (TypeError, ValueError) as err:
        return str(err)


def crest_period(value):
    try:
        return int(value, 16)
    except (TypeError, ValueError) as err:
        return str(err)


def trough_duration(value):
    try:
        return float(Fraction(value))
    except ZeroDivisionError as err:
        return str(err)
    except (TypeError, ValueError) as err:
        return str(err)


def buoy_battery(value):
    try:
        return value[-1]
    except (TypeError, IndexError, KeyError) as err:
        return str(err)


