    results = []
    for helper, field in zip(HELPERS, data):
        results.append(helper(field))
    return results


def format_report(results):
    lines = []
    for label, value in zip(LABELS, results):
        if isinstance(value, float):
            lines.append("%-18s %.2f" % (label, value))
        else:
            lines.append("%-18s %s" % (label, value))
