    except ValueError as err:
        return str(err)


def parse_organic_carbon(text):
    try:
        return int(text, 16)
    except ValueError as err:
        return str(err)


def parse_methane_release(text):
    try:
        return float(Fraction(text))
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def parse_surface_moisture(text):
    try:
        return 100 / int(text)
    except ValueError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


def parse_vegetation_height(text):
    try:
        return int(text)
    except ValueError as err:
        return str(err)


def parse_snow_cover(text):
