    ("methane release", parse_methane_release),
    ("surface moisture", parse_surface_moisture),
    ("vegetation height", parse_vegetation_height),
    ("snow cover", parse_snow_cover),
]


def measure(strings):
    results = []
    for index in range(len(PARSERS)):
        if index < len(strings):
            field = strings[index]
        else:
