import sys


def read_drip_rate(array):
    try:
        return float(array[0])
    except (IndexError, ValueError, TypeError) as err:
        return str(err)


def read_calcium_concentration(array):
    try:
        top, bottom = array[1].split('/')
        return float(top) / float(bottom)
    except (IndexError, ValueError, ZeroDivisionError, AttributeError) as err:
        return str(err)


def read_temperature(array):
    try:
        return float(array[2])
    except (IndexError, ValueError, TypeError) as err:
        return str(err)


def read_humidity(array):
    try:
        return 1000 / int(array[3])
    except (IndexError, ValueError, ZeroDivisionError, TypeError) as err:
        return str(err)


def read_carbon_dioxide(array):
    try:
        return int(array[4], 16)
    except (IndexError, ValueError, TypeError) as err:
        return str(err)


def read_water_acidity(array):
    try:
        return array[5][3]
    except (IndexError, TypeError) as err:
        return str(err)


def read_stalactite_length(array):
    try:
        return int(array[6])
    except (IndexError, ValueError, TypeError) as err:
        return str(err)


def read_airflow(array):
    try:
        return int(array[7])
    except (IndexError, ValueError, TypeError) as err:
        return str(err)


def quantify(array):
    return [read_drip_rate(array), read_calcium_concentration(array),
            read_temperature(array), read_humidity(array),
            read_carbon_dioxide(array), read_water_acidity(array),
            read_stalactite_length(array), read_airflow(array)]


def estimate_growth(values):
    try:
        return values[0] * values[1] * (values[6] + 1) / values[3]
    except TypeError as err:
        return str(err)
    except ZeroDivisionError as err:
        return str(err)


LABELS = ['drip rate', 'calcium concentration', 'temperature', 'humidity',
          'carbon dioxide', 'water acidity', 'stalactite length', 'airflow']


def format_report(values):
    lines = []
    for label, value in zip(LABELS, values):
        lines.append('%-22s %s' % (label, value))
    lines.append('%-22s %s' % ('growth estimate', estimate_growth(values)))
    return lines


def main():
    fields = [field.strip() for field in sys.stdin.read().split(',')]
    for line in format_report(quantify(fields)):
        print(line)


if __name__ == '__main__':
    main()

