from __future__ import print_function

import io
import sys

DEFAULT_SAMPLES = [
    "Racecar|yes",
    "Hello World|no",
    "A man, a plan, a canal: Panama|yes",
    "12321",
    "Was it a car or a cat I saw?|yes",
]


def normalize(text):
    try:
        lowered = text.lower()
    except AttributeError as err:
        raise TypeError("text must be a string (%s)" % err)
    return "".join(ch for ch in lowered if ch.isalnum())


def is_palindrome(text):
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def parse_min_length(spec):
    try:
        value = int(spec)
    except ValueError as err:
        raise ValueError("minimum length must be an integer (%s)" % err)
    if value < 0:
        raise ValueError("minimum length must not be negative: %d" % value)
    return value


def parse_expected(raw):
    flag = raw.strip().lower()
    if flag in ("yes", "true", "1"):
        return True
    if flag in ("no", "false", "0"):
        return False
    raise ValueError("unrecognised expectation: %r" % raw)


def split_record(line):
    fields = line.split("|")
    if len(fields) == 1:
        return line.strip(), None
    try:
        text, raw = fields
    except ValueError as err:
        raise ValueError("at most one '|' allowed in %r (%s)" % (line, err))
    try:
        expected = parse_expected(raw)
    except ValueError as err:
        raise ValueError("bad record %r: %s" % (line, err))
    return text.strip(), expected


def load_lines(path):
    with io.open(path, encoding="utf-8") as handle:
        return [line.rstrip("\n") for line in handle if line.strip()]


def report(records, min_length):
    checked = 0
    mismatches = 0
    for text, expected in records:
        if len(normalize(text)) < min_length:
            print("%-32s skipped (shorter than %d characters)" % (repr(text), min_length))
            continue
        verdict = is_palindrome(text)
        checked += 1
        note = ""
        if expected is not None and expected != verdict:
            note = " <- expected %s" % expected
            mismatches += 1
        print("%-32s %s%s" % (repr(text), verdict, note))
    try:
        rate = 100.0 * (checked - mismatches) / checked
    except ZeroDivisionError as err:
        print("no candidates were checked (%s)" % err)
        return 1
    print("%d checked, %d mismatched (%.1f%% agreement)" % (checked, mismatches, rate))
    return 1 if mismatches else 0


def main(argv):
    args = list(argv[1:])
    min_length = 0
    if "--min" in args:
        index = args.index("--min")
        spec = args.pop(index + 1) if index + 1 < len(args) else ""
        args.pop(index)
        try:
            min_length = parse_min_length(spec)
        except ValueError as err:
            print("bad --min option: %s" % err, file=sys.stderr)
            return 2
    if args:
        try:
            lines = load_lines(args[0])
        except (IOError, OSError) as err:
            print("cannot read candidates: %s" % err, file=sys.stderr)
            return 2
    else:
        lines = DEFAULT_SAMPLES
    records = []
    for line in lines:
        try:
            records.append(split_record(line))
        except ValueError as err:
            print("ignoring line: %s" % err, file=sys.stderr)
    return report(records, min_length)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

