import sys


def parse_number(text):
    """Convert a piece of player input into an integer."""
    try:
        return int(str(text).strip())
    except ValueError as err:
        raise ValueError("not a whole number: {!r} ({})".format(text, err))


def guess_number(secret_number, guess):
    """Compare a guess against the secret number."""
    try:
        secret = parse_number(secret_number)
        attempt = parse_number(guess)
    except ValueError as err:
        raise ValueError("guess_number needs integers: {}".format(err))
    if attempt > secret:
        return 'Too high'
    if attempt < secret:
        return 'Too low'
    return 'Correct!'


def play_round(secret, raw_guesses):
    outcomes = []
    for raw in raw_guesses:
        try:
            guess = parse_number(raw)
        except ValueError as err:
            outcomes.append((raw, "ignored ({})".format(err)))
            continue
        verdict = guess_number(secret, guess)
        outcomes.append((guess, verdict))
        if verdict == 'Correct!':
            break
    return outcomes


def parse_game(line):
    """Read one "secret: guess guess ..." transcript line."""
    head, sep, tail = line.partition(':')
    if not sep:
        raise ValueError("missing ':' in {!r}".format(line.strip()))
    try:
        secret = parse_number(head)
    except ValueError as err:
        raise ValueError("bad secret: {}".format(err))
    return secret, tail.split()


def format_report(secret, raw_guesses):
    """Build a human readable transcript for one game."""
    lines = ["secret is {}".format(secret)]
    outcomes = play_round(secret, raw_guesses)
    for value, verdict in outcomes:
        lines.append("  {} -> {}".format(value, verdict))
    winner = next((n for n, (_, v) in enumerate(outcomes, 1) if v == 'Correct!'), 0)
    if winner:
        lines.append("  solved on attempt {}".format(winner))
    else:
        lines.append("  out of guesses")
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        try:
            secret = parse_number(argv[1])
        except ValueError as err:
            print("usage: {} SECRET [GUESS ...] ({})".format(argv[0], err))
            return 2
        print(format_report(secret, argv[2:]))
        return 0
    for line in sys.stdin:
        try:
            secret, guesses = parse_game(line)
        except ValueError as err:
            print("skipping line: {}".format(err))
            continue
        print(format_report(secret, guesses))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

