def sum_digits(n):
    try:
        if not isinstance(n, int):
            raise TypeError("Input must be an integer.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if n < 0:
            raise ValueError("Input must be a non-negative integer.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        s = str(n)
    except Exception as err:
        print(f"Unexpected error converting to string: {err}")
        return None

    total_sum = 0
    for digit_char in s:
        try:
            digit = int(digit_char)
        except ValueError as err:
            print(f"Error converting character to integer: {err}")
            return None
        except TypeError as err:
            print(f"Error with character type: {err}")
            return None
        total_sum += digit

    try:
        if not isinstance(total_sum, int):
            raise TypeError("Sum is not an integer, unexpected.")
    except TypeError as err:
        print(f"Internal error: {err}")
        return None

    return total_sum

