import sys


def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    try:
        value = int(decimal_int)
    except (TypeError, ValueError) as err:
        raise ValueError("not an integer: {0!r} ({1})".format(decimal_int, err))
    if value < 0:
        raise ValueError("negative input not supported: {0}".format(value))
    digits = []
    while value > 0:
        digits.append(str(value & 1))
        value >>= 1
    if not digits:
        return "0"
    return "".join(reversed(digits))


def binary_to_decimal(bits):
    """Inverse of decimal_to_binary: read a binary string back as an integer."""
    try:
        return int(bits, 2)
    except ValueError as err:
        raise ValueError("not a binary string: {0!r} ({1})".format(bits, err))


def parse_token(token):
    """Accept either a decimal literal or a '0b...' binary literal."""
    text = token.strip()
    try:
        return int(text)
    except ValueError as err:
        if not text.lower().startswith("0b"):
            raise ValueError("unrecognised number {0!r} ({1})".format(token, err))
    try:
        return binary_to_decimal(text[2:])
    except ValueError as err:
        raise ValueError("bad binary literal {0!r}: {1}".format(token, err))


def group_bits(bits, size):
    if size <= 0:
        return bits
    padded = bits.rjust((len(bits) + size - 1) // size * size, "0")
    return " ".join(padded[i:i + size] for i in range(0, len(padded), size))


def format_row(token, width, group):
    try:
        value = parse_token(token)
    except ValueError as err:
        return "{0:>12} -> error: {1}".format(token, err)
    bits = decimal_to_binary(value).rjust(width, "0")
    return "{0:>12} -> {1}".format(token, group_bits(bits, group))


def parse_option_int(raw, name):
    try:
        return int(raw)
    except ValueError as err:
        raise ValueError("option --{0} needs an integer, got {1!r} ({2})".format(name, raw, err))


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    width, group = 0, 0
    while args and args[0].startswith("--"):
        option = args.pop(0)[2:]
        if "=" not in option:
            sys.stderr.write("option --{0} needs a value\n".format(option))
            return 2
        name, raw = option.split("=", 1)
        try:
            size = parse_option_int(raw, name)
        except ValueError as err:
            sys.stderr.write("{0}\n".format(err))
            return 2
        if name == "width":
            width = size
        elif name == "group":
            group = size
        else:
            sys.stderr.write("unknown option --{0}\n".format(name))
            return 2
    for token in args or ["0", "11", "255", "0b1011", "twelve"]:
        print(format_row(token, width, group))
    return 0


if __name__ == "__main__":
    sys.exit(main())

