    except ValueError as err:
        raise ValueError("octet %r is not a decimal number (%s)" % (text, err))
    if str(value) != text:
        raise ValueError("octet %r is not in canonical decimal form" % text)
    if not 0 <= value <= 255:
        raise ValueError("octet %r is outside the range 0-255" % text)
    return value


def split_octets(ip_address):
    """Return the four integer octets of ip_address, or raise ValueError."""
    if not isinstance(ip_address, str):
        raise ValueError("address must be a string, got %s" % type(ip_address).__name__)
    parts = ip_address.split('.')
    if len(parts) != 4:
        raise ValueError("expected 4 octets, found %d" % len(parts))
    return [parse_octet(part) for part in parts]


def validation_error(ip_address):
    """Return the reason ip_address is not a valid IPv4 address, or None."""
    try:
        split_octets(ip_address)
    except ValueError as err:
        return str(err)
    return None


def is_valid_ipv4(ip_address):
    """Simple validation check for an IPv4 address."""
    return validation_error(ip_address) is None


def describe(ip_address):
    """Return the category of a valid address such as 'private' or 'multicast'."""
    octets = split_octets(ip_address)
    first = octets[0]
    if first == 127:
        return "loopback"
    if first == 10 or (first == 192 and octets[1] == 168) or (first == 172 and 16 <= octets[1] <= 31):
        return "private"
    if 224 <= first <= 239:
        return "multicast"
    return "public"


def address_to_int(address):
    """Pack a dotted address into a single 32 bit integer."""
    octets = split_octets(address)
    return (octets[0] << 24) | (octets[1] << 16) | (octets[2] << 8) | octets[3]


def parse_address_list(text):
    """Parse a comma separated list, returning (packed, address) pairs and failures."""
    packed, failures = [], []
    for item in text.split(','):
        item = item.strip()
        try:
            packed.append((address_to_int(item), item))
        except ValueError as err:
            failures.append((item, str(err)))
    return packed, failures


def parse_cidr(spec):
    """Split 'address/prefix' into (packed address, prefix length)."""
    address, sep, prefix = spec.partition('/')
    if not sep:
        raise ValueError("missing '/' in %r" % spec)
    try:
