    """Return the network address of a CIDR block such as '192.168.1.37/24'."""
    packed, length = parse_cidr(spec)
    mask = ((1 << length) - 1) << (32 - length) if length else 0
    masked = packed & mask
    return '.'.join(str((masked >> shift) & 255) for shift in (24, 16, 8, 0))


