        raise ValueError("price %r is not a number (%s)" % (text, err))
    if price < 0:
        raise ValueError("price %.2f may not be negative" % price)
    return price


def parse_percentage(text):
    """Convert a textual discount into a float between 0 and 100."""
    stripped = str(text).strip().rstrip("%")
    try:
        percentage = float(stripped)
    except ValueError as err:
        raise ValueError("discount %r is not a number (%s)" % (text, err))
    if not 0.0 <= percentage <= 100.0:
        raise ValueError("discount %.2f is outside 0..100" % percentage)
    return percentage


def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after applying discount_percentage."""
    try:
        price = parse_price(original_price)
        percentage = parse_percentage(discount_percentage)
    except ValueError as err:
        raise ValueError("cannot compute discounted price: %s" % err)
    return round(price * (100.0 - percentage) / 100.0, 2)


def parse_item_line(line):
    """Split 'name,price,discount' into a (name, price, discount) tuple."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        raise ValueError("expected 3 comma separated fields, got %d" % len(fields))
    name = fields[0]
    if not name:
        raise ValueError("item name must not be empty")
    try:
