    except ValueError as err:
        raise ValueError("bad price column: %s" % err)
    try:
        discount = parse_percentage(fields[2])
    except ValueError as err:
        raise ValueError("bad discount column: %s" % err)
    return name, price, discount


def receipt_row(line):
    """Turn one input line into a (text, final_price) pair."""
    name, price, discount = parse_item_line(line)
    final = calculate_discount_price(price, discount)
    saved = round(price - final, 2)
    text = "%-14s %8.2f %7.1f%% %9.2f %9.2f" % (name, price, discount, final, saved)
    return text, final


