import sys


def parse_element(token):
    """Convert a single token into an int, a float, or leave it as text."""
    token = token.strip()
    if not token:
        raise ValueError("empty element in list specification")
    try:
        return int(token)
    except ValueError as err:
        if token.lower() in ("nan", "inf", "-inf"):
            raise ValueError("unsupported numeric literal %r: %s" % (token, err))
    try:
        return float(token)
    except ValueError:
        return token.strip("'\"")


def parse_list(spec):
    """Turn a textual specification such as "[1, 2]" or "a,b" into a list."""
    text = spec.strip()
    if text.startswith("[") and text.endswith("]"):
        text = text[1:-1]
    elif text.startswith("[") or text.endswith("]"):
        raise ValueError("unbalanced brackets in %r" % spec)
    if not text.strip():
        return []
    items = []
    for token in text.split(","):
        try:
            items.append(parse_element(token))
        except ValueError as err:
            raise ValueError("cannot parse %r: %s" % (spec, err))
    return items


def cartesian_product(list1, list2):
    """Return every ordered pair (x, y) with x from list1 and y from list2."""
    try:
        left = list(list1)
        right = list(list2)
    except TypeError as err:
        raise TypeError("both arguments must be iterable: %s" % err)
    return [(x, y) for x in left for y in right]


def pair_at(list1, list2, index):
    """Return the pair at the given position of the product, without building it."""
    width = len(list2)
    if width == 0:
        raise IndexError("the product is empty")
    try:
        return (list1[index // width], list2[index % width])
    except IndexError as err:
        raise IndexError("position %d is outside the product: %s" % (index, err))


def format_pairs(pairs):
    return "[" + ", ".join("(%r, %r)" % pair for pair in pairs) + "]"


def main(argv):
    if len(argv) not in (3, 4):
        print("usage: %s LIST1 LIST2 [INDEX]" % argv[0])
        return 2
    try:
        first = parse_list(argv[1])
        second = parse_list(argv[2])
    except ValueError as err:
        print("input error: %s" % err)
        return 1
    if len(argv) == 3:
        print(format_pairs(cartesian_product(first, second)))
        return 0
    try:
        position = int(argv[3])
    except ValueError as err:
        print("index error: %s" % err)
        return 1
    try:
        print("%r" % (pair_at(first, second, position),))
    except IndexError as err:
        print("index error: %s" % err)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

