def parse_hex_color(code):
    """Return the (r, g, b) tuple for a hex color code, or raise ValueError."""
    if not isinstance(code, str):
        raise ValueError("color code must be a string, got %s" % type(code).__name__)
    if not code.startswith("#"):
        raise ValueError("color code must start with '#': %r" % code)
    digits = code[1:]
    if len(digits) not in (3, 6):
        raise ValueError("expected 3 or 6 digits after '#', got %d" % len(digits))
    if not digits.isalnum():
        raise ValueError("unexpected characters in %r" % code)
    try:
        int(digits, 16)
    except ValueError as err:
        raise ValueError("not hexadecimal (%s)" % err)
    if len(digits) == 3:
        digits = "".join(c * 2 for c in digits)
    return tuple(int(digits[i:i + 2], 16) for i in (0, 2, 4))


def is_valid_hex_color(code):
    try:
        parse_hex_color(code)
    except ValueError:
        return False
    return True


def format_hex(rgb):
    return "#" + "".join("%02X" % channel for channel in rgb)


def parse_palette_line(line):
    """Parse a 'name = #rrggbb' palette entry into (name, rgb)."""
    if "=" not in line:
        raise ValueError("missing '=' in entry %r" % line)
    name, _, raw = line.partition("=")
    try:
        rgb = parse_hex_color(raw.strip())
    except ValueError as err:
        raise ValueError("entry %r has a bad color: %s" % (name.strip(), err))
    return name.strip(), rgb


def describe(rgb):
    luminance = 0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]
    return "light" if luminance >= 128 else "dark"


def blend(color_a, color_b, ratio="0.5"):
    try:
        weight = float(ratio)
    except ValueError as err:
        raise ValueError("bad blend ratio %r: %s" % (ratio, err))
    try:
        first = parse_hex_color(color_a)
        second = parse_hex_color(color_b)
    except ValueError as err:
        raise ValueError("cannot blend: %s" % err)
    return format_hex([round(a + (b - a) * weight) for a, b in zip(first, second)])


def adjust(code, percent):
    try:
        pct = int(percent)
    except ValueError as err:
        raise ValueError("bad percentage %r: %s" % (percent, err))
    rgb = parse_hex_color(code)
    factor = 1.0 + pct / 100.0
    return format_hex([min(255, max(0, round(c * factor))) for c in rgb])


def main():
    palette = ["primary = #1E90FF", "accent=#ABC", "broken = #GGGGGG",
               "nope = blue", "short = #12345", "grey"]
    for line in palette:
        try:
            name, rgb = parse_palette_line(line)
        except ValueError as err:
            print("skipping: %s" % err)
            continue
