def geometric_series_sum(a, r, n):
    """Return the sum of the first n terms of the geometric series a, a*r, a*r^2, ..."""
    try:
        a = float(a)
        r = float(r)
    except (TypeError, ValueError) as err:
        raise ValueError("first term and ratio must be numeric: %s" % err)
    try:
        n = int(n)
    except (TypeError, ValueError) as err:
        raise ValueError("term count must be an integer: %s" % err)
    if n < 0:
        raise ValueError("term count must be non-negative, got %d" % n)
    if r == 1.0:
        return a * n
    return a * (1.0 - r ** n) / (1.0 - r)


def parse_spec(text):
    """Turn a spec like '1, 2, 3' into the triple (a, r, n)."""
    parts = [piece.strip() for piece in text.replace(",", " ").split()]
    if len(parts) != 3:
        raise ValueError("expected 3 values, got %d" % len(parts))
    try:
        a, r = float(parts[0]), float(parts[1])
    except ValueError as err:
        raise ValueError("bad term or ratio in %r: %s" % (text, err))
    try:
        n = int(parts[2])
    except ValueError as err:
        raise ValueError("bad term count in %r: %s" % (text, err))
    return a, r, n


def tidy(value):
    """Format a float, dropping the decimal part when it is exact."""
    if value == int(value):
        return str(int(value))
    return "%.6g" % value


def series_terms(a, r, n, limit=6):
    terms = []
    current = a
    for _ in range(min(n, limit)):
        terms.append(tidy(current))
        current *= r
    if n > limit:
        terms.append("...")
    return " + ".join(terms)


def describe(text):
    """Return a one-line report for a series specification."""
    try:
        a, r, n = parse_spec(text)
    except ValueError as err:
        return "%-12s -> invalid (%s)" % (text, err)
    try:
        total = geometric_series_sum(a, r, n)
    except ValueError as err:
        return "%-12s -> rejected (%s)" % (text, err)
    body = series_terms(a, r, n) or "(empty)"
    return "%-12s -> %s = %s" % (text, body, tidy(total))


def main():
    specs = ["1, 2, 3", "5, 1, 4", "3, 0.5, 10", "2, 3, -1", "1, 2", "4, x, 5"]
    for spec in specs:
        print(describe(spec))
    try:
        print(tidy(geometric_series_sum(1, 2, "three")))
    except ValueError as err:
        print("direct call failed: %s" % err)


if __name__ == "__main__":
    main()

