def parse_task(record):
    """Normalise a raw task record into {'name': str, 'dependencies': [str]}."""
    try:
        name = record['name']
        raw_deps = record.get('dependencies', [])
    except (TypeError, KeyError) as err:
        raise ValueError("record is not a task mapping with a 'name' (%s)" % err)
    if not isinstance(name, str) or not name.strip():
        raise ValueError("task name must be a non-empty string")
    if isinstance(raw_deps, str) or not hasattr(raw_deps, '__iter__'):
        raise ValueError("dependencies of %r must be a list of names" % name)
    deps = []
    for dep in raw_deps:
        if not isinstance(dep, str) or not dep.strip():
            raise ValueError("dependency of %r must be a non-empty string" % name)
        deps.append(dep.strip())
    return {'name': name.strip(), 'dependencies': deps}


def build_index(tasks):
    index = {}
    for position, record in enumerate(tasks):
        try:
            task = parse_task(record)
        except ValueError as err:
            raise ValueError("task at position %d: %s" % (position, err))
        if task['name'] in index:
            raise ValueError("duplicate task name %r" % task['name'])
        index[task['name']] = task
    return index


def find_task(task_name, tasks):
    index = build_index(tasks)
    try:
        return index[task_name]
    except KeyError as err:
        raise ValueError("no task named %s in the task list" % err)


def unmet_dependencies(task_name, tasks, completed_tasks):
    task = find_task(task_name, tasks)
    done = set(completed_tasks)
    return [dep for dep in task['dependencies'] if dep not in done]


def has_unmet_dependencies(task_name, tasks, completed_tasks):
    return bool(unmet_dependencies(task_name, tasks, completed_tasks))


def parse_line(line):
    head, sep, tail = line.partition(':')
    if not sep:
        raise ValueError("expected 'name: dep, dep' but got %r" % line)
    deps = [part.strip() for part in tail.split(',') if part.strip()]
    return parse_task({'name': head, 'dependencies': deps})


def load_tasks(lines):
    tasks = []
    for lineno, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            tasks.append(parse_line(line))
        except ValueError as err:
            raise ValueError("line %d: %s" % (lineno, err))
    return tasks


def describe(task_name, tasks, completed_tasks):
    try:
        missing = unmet_dependencies(task_name, tasks, completed_tasks)
    except ValueError as err:
        return "%s: cannot check (%s)" % (task_name, err)
    if missing:
        return "%s: blocked by %s" % (task_name, ', '.join(missing))
    return "%s: ready" % task_name


def main():
    lines = ["A:", "B: A", "C: A, B", "D: C, E"]
    completed = ['A']
    try:
        tasks = load_tasks(lines)
    except ValueError as err:
        print("bad task file: %s" % err)
        return 1
    for task in tasks:
        print(describe(task['name'], tasks, completed))
    try:
        print(has_unmet_dependencies('Z', tasks, completed))
    except ValueError as err:
        print("query failed: %s" % err)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

